# ========= SegTree / SparseTable 用 op・単位元セット =========
"""
使い方:
    SegTree(n, *op_sum())              # 区間和
    SegTree(n, *op_min())              # 区間最小
    SparseTable(arr, op_min()[0])      # op だけ使う
    DisjointSparseTable(arr, *op_sum())# op と e をまとめて渡す

    op_min()  → (min,  INF)
    op_max()  → (max, -INF)
    op_sum()  → (lambda a,b: a+b,  0)
    ...
    
    SegTree(n, *op_min())
    SegTree(n, *op_max())
    SegTree(n, *op_sum())
    SegTree(n, *op_mul())
    SegTree(n, *op_gcd())
    SegTree(n, *op_lcm())
    SegTree(n, *op_or())
    SegTree(n, *op_and())
    SegTree(n, *op_xor())
    SegTree(n, *op_min_with_index())
    SegTree(n, *op_max_with_index())
    SegTree(n, *op_count_eq(target))
    SegTree(n, *op_sum_mod(mod))
    SegTree(n, *op_mul_mod(mod))
    SegTree(n, *op_affine(mod))        # LazySegTree の F 用
"""

NINF = -float('inf')

# --- 基本演算 ---
def op_min():
    """区間最小  冪等  SparseTable/SegTree/LazySegTree

    返り値: (min, INF)。INF = float("inf")。

    注意（単位元が float の inf であることの影響）:
        - 空区間の prod(l, l) や、全体が未設定の区間の結果は int ではなく float の inf になる。
          そのまま print すると "inf" と出る。「見つからなければ -1」などは
          `v = seg.prod(l, r); ans = -1 if v == INF else v` のように判定してから出す。
          int(INF) は OverflowError になる。
        - 空でない区間の答えは、min が引数のどれかをそのまま返すので元の int のまま
          （10^18 を超える int と inf の比較も Python では正確で、精度は落ちない）。
        - LazySegTree の mapping で 0 * x（代入を一次関数 0*x+c で書く）や x - x を使うと、
          inf が残った葉（列の長さが 2 冪でないときの詰め物）で nan になり、
          min が狂う。代入は op_lazy_range_assign_range_min のように None で表すか、
          単位元に int の番兵（例 1 << 62）を使って `SegTree(n, min, 1 << 62)` とする。
        - PyPy での速さは int の番兵とほぼ同じ（N = Q = 2×10^5 の一点更新・区間最小で 0.45 秒前後）。
    """
    return min, INF
def op_max():
    """区間最大  冪等  SparseTable/SegTree/LazySegTree

    返り値: (max, NINF)。NINF = -float("inf")。

    注意: 空区間の結果は float の -inf になる（print すると "-inf"）。int(NINF) は OverflowError。
    空でない区間の答えは元の int のまま。0 * x や x - x を含む mapping で nan になりうる点も
    op_min と同じなので、気になるときは単位元に int の番兵（例 -(1 << 62)）を使う。
    """
    return max, NINF
def op_sum():
    """区間和  和→0  SegTree/LazySegTree/DisjointSparseTable"""
    return (lambda a, b: a + b), 0
def op_mul():
    """区間積  積→1  SegTree/DisjointSparseTable"""
    return (lambda a, b: a * b), 1
def op_gcd():
    """区間GCD  冪等  SparseTable/SegTree  ※gcd(x,0)=x なので単位元=0"""
    return math.gcd, 0
def op_lcm():
    """区間LCM  単位元=1  SegTree"""
    return (lambda a, b: a * b // math.gcd(a, b) if a and b else 0), 1
def op_or():
    """区間 bitwise OR  冪等  SparseTable/SegTree"""
    return (lambda a, b: a | b), 0
def op_and():
    """区間 bitwise AND  冪等  SparseTable/SegTree"""
    return (lambda a, b: a & b), -1
def op_xor():
    """区間 XOR  単位元=0  SegTree/DisjointSparseTable"""
    return (lambda a, b: a ^ b), 0

# --- インデックス付き極値（「最小値がどこにあるか」も取得したい場合）---
def op_min_with_index():
    """
    区間最小 + そのインデックスを保持
    値は (value, index) のタプルで管理する

    使用例:
        seg = SegTree(n, *op_min_with_index())
        seg.build([(a[i], i) for i in range(n)])
        val, idx = seg.query(l, r)
    """
    return (lambda a, b: a if a[0] <= b[0] else b), (INF, -1)

def op_max_with_index():
    """
    区間最大 + そのインデックスを保持
    値は (value, index) のタプルで管理する

    使用例:
        seg = SegTree(n, *op_max_with_index())
        seg.build([(a[i], i) for i in range(n)])
        val, idx = seg.query(l, r)
    """
    return (lambda a, b: a if a[0] >= b[0] else b), (NINF, -1)

# --- 応用演算 ---
def op_count_eq(target):
    """
    区間内で条件を満たす要素の個数（和の組）
    target は使われない（op は単なる足し算）。数えたい値の指定は、
    build / set に渡す列を 1（一致）or 0（不一致）に変換して行う。
    元の値をそのまま入れると個数ではなく値の合計が返る。

    使用例:
        seg = SegTree(n, *op_count_eq(3))
        seg.build([1 if a[i]==3 else 0 for i in range(n)])
        seg.query(l, r)   # [l,r) に 3 が何個あるか
    """
    return (lambda a, b: a + b), 0

def op_sum_mod(mod):
    """
    区間和 mod m
    SegTree/DisjointSparseTable

    使用例:
        seg = SegTree(n, *op_sum_mod(10**9+7))
    """
    return (lambda a, b: (a + b) % mod), 0

def op_mul_mod(mod):
    """
    区間積 mod m
    SegTree/DisjointSparseTable

    使用例:
        seg = SegTree(n, *op_mul_mod(10**9+7))
    """
    return (lambda a, b: a * b % mod), 1

# --- LazySegTree 用 (op, e, mapping, composition, id_) セット ---

# 遅延操作: (add_val, assign_val or None)
# F = (add, assign)

# op          = max
# e           = lambda: float('-inf')
# mapping     = lambda f, x: f[0] + (x if f[1] is None else f[1])
# composition = lambda f, g: (f[0], f[1]) if f[1] is not None else (f[0] + g[0], g[1])
# id_         = lambda: (0, None)

# seg = LazySegTree(op, e, mapping, composition, id_, a)


def op_lazy_range_add_range_sum():
    """
    区間加算 + 区間和
    S = (sum, size)  F = add_value

    使用例:
        seg = LazySegTree(*op_lazy_range_add_range_sum(), [(a[i],1) for i in range(n)])
        seg.apply(l, r, x)      # A[l:r] += x
        seg.prod(l, r)[0]       # A[l:r] の和
    """
    op          = lambda a, b: (a[0] + b[0], a[1] + b[1])
    e           = lambda: (0, 0)
    mapping     = lambda f, x: (x[0] + f * x[1], x[1])
    composition = lambda f, g: f + g
    id_         = lambda: 0
    return op, e, mapping, composition, id_




def op_lazy_range_add_range_min():
    """
    区間加算 + 区間最小
    S = value  F = add_value

    使用例:
        seg = LazySegTree(*op_lazy_range_add_range_min(), a)
        seg.apply(l, r, x)   # A[l:r] += x
        seg.prod(l, r)        # A[l:r] の最小値
    """
    op          = min
    e           = lambda: INF
    mapping     = lambda f, x: x + f
    composition = lambda f, g: f + g
    id_         = lambda: 0
    return op, e, mapping, composition, id_

def op_lazy_range_add_range_max():
    """
    区間加算 + 区間最大
    S = value  F = add_value

    使用例:
        seg = LazySegTree(*op_lazy_range_add_range_max(), a)
        seg.apply(l, r, x)   # A[l:r] += x
        seg.prod(l, r)        # A[l:r] の最大値
    """
    op          = max
    e           = lambda: NINF
    mapping     = lambda f, x: x + f
    composition = lambda f, g: f + g
    id_         = lambda: 0
    return op, e, mapping, composition, id_

def op_lazy_range_assign_range_sum():
    """
    区間代入 + 区間和
    S = (sum, size)  F = value | None

    使用例:
        seg = LazySegTree(*op_lazy_range_assign_range_sum(), [(a[i],1) for i in range(n)])
        seg.apply(l, r, val)  # A[l:r] = val
        seg.prod(l, r)[0]     # A[l:r] の和
    """
    op          = lambda a, b: (a[0] + b[0], a[1] + b[1])
    e           = lambda: (0, 0)
    mapping     = lambda f, x: x if f is None else (f * x[1], x[1])
    composition = lambda f, g: g if f is None else f
    id_         = lambda: None
    return op, e, mapping, composition, id_

def op_lazy_range_assign_range_min():
    """
    区間代入 + 区間最小
    S = value  F = value | None

    使用例:
        seg = LazySegTree(*op_lazy_range_assign_range_min(), a)
        seg.apply(l, r, val)  # A[l:r] = val
        seg.prod(l, r)         # A[l:r] の最小値
    """
    op          = min
    e           = lambda: INF
    mapping     = lambda f, x: x if f is None else f
    composition = lambda f, g: g if f is None else f
    id_         = lambda: None
    return op, e, mapping, composition, id_

def op_lazy_range_assign_range_max():
    """
    区間代入 + 区間最大
    S = value  F = value | None

    使用例:
        seg = LazySegTree(*op_lazy_range_assign_range_max(), a)
        seg.apply(l, r, val)  # A[l:r] = val
        seg.prod(l, r)         # A[l:r] の最大値
    """
    op          = max
    e           = lambda: NINF
    mapping     = lambda f, x: x if f is None else f
    composition = lambda f, g: g if f is None else f
    id_         = lambda: None
    return op, e, mapping, composition, id_

def op_lazy_range_affine_range_sum(mod=None):
    """
    区間 affine（x → a*x + b）+ 区間和
    S = (sum, size)  F = (a, b)
    composition(new, old) は new∘old。mod は None または正の int。

    使用例:
        seg = LazySegTree(*op_lazy_range_affine_range_sum(), [(a[i],1) for i in range(n)])
        seg.apply(l, r, (a, b))  # A[l:r] の各要素 x を a*x+b に変換
        seg.prod(l, r)[0]        # A[l:r] の和
        
        # mod あり版
        seg = LazySegTree(*op_lazy_range_affine_range_sum(mod=10**9+7), ...)
    """
    if mod is not None:
        if not isinstance(mod, int) or isinstance(mod, bool) or mod <= 0:
            raise ValueError("mod must be a positive integer or None")
        op          = lambda a, b: ((a[0] + b[0]) % mod, a[1] + b[1])
        e           = lambda: (0, 0)
        mapping     = lambda f, x: ((f[0] * x[0] + f[1] * x[1]) % mod, x[1])
        composition = lambda f, g: ((f[0] * g[0]) % mod, (f[0] * g[1] + f[1]) % mod)
    else:
        op          = lambda a, b: (a[0] + b[0], a[1] + b[1])
        e           = lambda: (0, 0)
        mapping     = lambda f, x: (f[0] * x[0] + f[1] * x[1], x[1])
        composition = lambda f, g: (f[0] * g[0], f[0] * g[1] + f[1])
    id_         = lambda: (1, 0)
    return op, e, mapping, composition, id_

# ========= SmallToLargeUnionFind merge_func パターン集 =========
# 使い方: SmallToLargeUnionFind(n, initial_data=[...], merge_func=merge_func_OOO)
# 注意: set / list / dict / Counter / SortedList を持たせる関数は、第1引数 l（大きい側）を
#       その場で更新して返す（s は変えない）。数値・タプルを持たせる関数は新しい値を返す。

# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# ── set 系 ──────────────────────────────────────────
# initial: [{v} for v in a] / [set() for _ in range(n)]
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
def merge_func_set(l, s):              l.update(s);    return l   # 和集合
def merge_func_set_and(l, s):          l &= s;         return l   # 積集合
def merge_func_set_diff(l, s):         l -= s;         return l   # 差集合
def merge_func_set_xor(l, s):                                      # set + XOR
    l['set'].update(s['set']); l['xor'] ^= s['xor']; return l
# initial: [{'set': {v}, 'xor': v} for v in a]
def merge_func_set_sum_distinct(l, s):                             # set + distinct合計
    new_vals = s['set'] - l['set']
    l['set'].update(s['set']); l['sum'] += sum(new_vals); return l
# initial: [{'set': {v}, 'sum': v} for v in a]
def merge_func_set_max_freq(l, s):                                 # Counter + 最頻出現回数
    cnt = l['cnt']; cnt.update(s['cnt'])
    if 'max_freq' in l:
        best = l['max_freq']
        for k in s['cnt']:
            c = cnt[k]
            if c > best: best = c
    else:
        best = max(cnt.values(), default=0)
    l['max_freq'] = best; return l
# initial: [{'cnt': Counter([v]), 'max_freq': 1} for v in a]

# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# ── list 系 ─────────────────────────────────────────
# initial: [[v] for v in a] / [[] for _ in range(n)]
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
def merge_func_list(l, s):             l.extend(s);    return l   # 結合
def merge_func_list_sorted(l, s):      l.extend(s); l.sort(); return l  # ソート済み結合
def merge_func_prefix_max(l, s):                                   # list + prefix最大値
    vals = l['vals']; pm = l.get('prefix_max')
    if pm is None or len(pm) != len(vals):
        cur = float('-inf'); pm = []
        for v in vals: cur = max(cur, v); pm.append(cur)
        l['prefix_max'] = pm
    cur = pm[-1] if pm else float('-inf')
    sv = s['vals']
    vals.extend(sv)
    for v in sv:
        if v > cur: cur = v
        pm.append(cur)
    return l
# initial: [{'vals': [v], 'prefix_max': [v]} for v in a]
def merge_func_running_sum(l, s):                                  # list + 累積和
    offset = l['total']
    l['vals'].extend(s['vals'])
    l['prefix_sum'].extend(x + offset for x in s['prefix_sum'])
    l['total'] += s['total']; return l
# initial: [{'vals': [v], 'prefix_sum': [v], 'total': v} for v in a]

# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# ── Counter 系 ──────────────────────────────────────
# initial: [Counter([v]) for v in a] / [Counter() for _ in range(n)]
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
def merge_func_counter(l, s):          l.update(s);    return l   # 加算マージ
def merge_func_counter_sub(l, s):      l.subtract(s);  return l   # 減算マージ
def merge_func_counter_distinct(l, s):                             # Counter + distinct数
    l['cnt'].update(s['cnt']); l['distinct'] = len(l['cnt']); return l
# initial: [{'cnt': Counter([v]), 'distinct': 1} for v in a]
def merge_func_counter_mode(l, s):                                 # Counter + 最頻値（同数なら最小のキー）
    cnt = l['cnt']; cnt.update(s['cnt'])
    if not cnt: return l
    if 'mode' in l:
        best = l['mode']; bc = cnt[best]
        for k in s['cnt']:
            c = cnt[k]
            if c > bc or (c == bc and k < best): best = k; bc = c
    else:
        bc = max(cnt.values()); best = min(k for k, v in cnt.items() if v == bc)
    l['mode'] = best; return l
# initial: [{'cnt': Counter([v]), 'mode': v} for v in a]
def merge_func_counter_majority(l, s):                             # Counter + 過半数値（なければ -1）
    l['cnt'].update(s['cnt']); total = sum(l['cnt'].values())
    if not total: l['majority'] = -1; return l
    top = l['cnt'].most_common(1)[0]
    l['majority'] = top[0] if top[1] * 2 > total else -1; return l
# initial: [{'cnt': Counter([v]), 'majority': v} for v in a]

# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# ── SortedList 系 ───────────────────────────────────
# initial: [SortedList([v]) for v in a] / [SortedList() for _ in range(n)]
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
def merge_func_sortedlist(l, s):       l.update(s);    return l   # SortedList追加
def merge_func_sl_sum(l, s):                                       # SortedList + 合計
    l['sl'].update(s['sl']); l['sum'] += s['sum']; return l
# initial: [{'sl': SortedList([v]), 'sum': v} for v in a]
def merge_func_sl_min_max(l, s):                                   # SortedList + min/max
    l['sl'].update(s['sl'])
    l['min'] = min(l['min'], s['min']); l['max'] = max(l['max'], s['max']); return l
# initial: [{'sl': SortedList([v]), 'min': v, 'max': v} for v in a]
def merge_func_sl_sum_min_max(l, s):                               # SortedList + sum/min/max
    l['sl'].update(s['sl'])
    l['sum'] += s['sum']; l['min'] = min(l['min'], s['min']); l['max'] = max(l['max'], s['max']); return l
# initial: [{'sl': SortedList([v]), 'sum': v, 'min': v, 'max': v} for v in a]
def merge_func_sl_cnt(l, s):                                       # SortedList + 要素数（重複込み）
    l['sl'].update(s['sl']); l['cnt'] = len(l['sl']); return l
# initial: [{'sl': SortedList([v]), 'cnt': 1} for v in a]
def merge_func_sl_kth_ready(l, s):                                 # SortedList + 中央値キャッシュ
    l['sl'].update(s['sl']); sz = len(l['sl']); l['median'] = l['sl'][(sz-1)//2]; return l
# initial: [{'sl': SortedList([v]), 'median': v} for v in a]
# クエリ: component_data(x)['sl'][k-1]  # K番目  /  component_data(x)['median']  # 中央値O(1)
def merge_func_sl_full(l, s):                                      # SortedList + 全集約
    sl = l['sl']; new = 0; prev = None
    if 'distinct' in l:
        for v in s['sl']:
            if v != prev:
                prev = v
                if v not in sl: new += 1
    sl.update(s['sl']); l['sum'] += s['sum']
    l['min'] = min(l['min'], s['min']); l['max'] = max(l['max'], s['max'])
    l['distinct'] = l['distinct'] + new if 'distinct' in l else len(set(sl))
    l['xor'] ^= s['xor']; return l
# initial: [{'sl': SortedList([v]), 'sum': v, 'min': v, 'max': v, 'distinct': 1, 'xor': v} for v in a]

# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# ── SortedList + 差分・隣接管理 ─────────────────────
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
def merge_func_min_diff(l, s):                                     # 隣接差分の最小値
    for val in s['sl']:
        sl = l['sl']; idx = sl.bisect_left(val)
        if idx > 0:       l['min_diff'] = min(l['min_diff'], val - sl[idx-1])
        if idx < len(sl): l['min_diff'] = min(l['min_diff'], sl[idx] - val)
        sl.add(val)
    l['min_diff'] = min(l['min_diff'], s['min_diff']); return l
# initial: [{'sl': SortedList([v]), 'min_diff': float('inf')} for v in a]
def merge_func_max_diff(l, s):                                     # max - min
    l['sl'].update(s['sl']); l['max_diff'] = l['sl'][-1] - l['sl'][0]; return l
# initial: [{'sl': SortedList([v]), 'max_diff': 0} for v in a]

# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# ── dict 系 ─────────────────────────────────────────
# initial: [{i: 1} for i in range(n)] / [defaultdict(int) for _ in range(n)]
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
def merge_func_dict(l, s):             l.update(s);    return l   # 上書きマージ
def merge_func_dict_add(l, s):                                     # 値加算マージ
    for k, v in s.items(): l[k] = l.get(k, 0) + v
    return l
def merge_func_dict_max(l, s):                                     # 値最大マージ
    for k, v in s.items():
        if k not in l or v > l[k]: l[k] = v
    return l
def merge_func_dict_min(l, s):                                     # 値最小マージ
    for k, v in s.items():
        if k not in l or v < l[k]: l[k] = v
    return l
def merge_func_depth_dict(l, s):                                   # 深さ情報（浅い方優先）
    for k, v in s.items():
        if k not in l or l[k] > v: l[k] = v
    return l
# initial: [{i: 0} for i in range(n)]

# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# ── 集約値系（int / float） ──────────────────────────
# initial: [v for v in a]
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
def merge_func_sum(l, s):              return l + s               # 合計
def merge_func_mul(l, s):              return l * s               # 積
def merge_func_max(l, s):              return max(l, s)           # 最大
def merge_func_min(l, s):              return min(l, s)           # 最小
def merge_func_xor(l, s):              return l ^ s               # XOR
def merge_func_or(l, s):              return l | s               # bitwise OR
def merge_func_and(l, s):             return l & s               # bitwise AND
def merge_func_gcd(l, s):             return math.gcd(l, s)      # GCD
def merge_func_lcm(l, s):             return math.lcm(l, s)      # LCM

# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# ── タプル複合系 ─────────────────────────────────────
# initial: [(v, 1) for v in a] など
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
def merge_func_sum_cnt(l, s):          return (l[0]+s[0], l[1]+s[1])              # (sum, count)
def merge_func_min_max(l, s):          return (min(l[0],s[0]), max(l[1],s[1]))    # (min, max)
def merge_func_sum_min_max(l, s):      return (l[0]+s[0], min(l[1],s[1]), max(l[2],s[2]))  # (sum,min,max)
def merge_func_xor_cnt(l, s):          return (l[0]^s[0], l[1]+s[1])             # (xor, count)
def merge_func_gcd_sum(l, s):          return (math.gcd(l[0],s[0]), l[1]+s[1])   # (gcd, sum)
def merge_func_gcd_lcm(l, s):                                                      # (gcd, lcm)
    return {'gcd': math.gcd(l['gcd'], s['gcd']), 'lcm': math.lcm(l['lcm'], s['lcm'])}
# initial: [{'gcd': v, 'lcm': v} for v in a]
def merge_func_xor_and_or(l, s):                                                   # (xor, and, or)
    l['xor'] ^= s['xor']; l['and'] &= s['and']; l['or'] |= s['or']; return l
# initial: [{'xor': v, 'and': v, 'or': v} for v in a]

# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# ── グラフ・木構造系 ─────────────────────────────────
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
def merge_func_edge_set(l, s):         l.update(s);    return l   # 辺集合マージ
def merge_func_adj_list(l, s):         l.extend(s);    return l   # 隣接リストマージ

# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# ── ファクトリ関数系（外部変数更新） ──────────────────
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
def make_merge_func_inversion():
    """
    併合する l（要素数の多い側）と s の間の転倒数を total[0] に足していく。
    数えるのは l の要素 > s の要素 となる組だけ（等しい値は数えない）で、
    l の中・s の中の組は数えない。配列全体の転倒数は、すべて併合し終えた
    ときの total[0] の合計になる（l が位置の前側であるときの話）。
    """
    total = [0]
    def f(l, s):
        n = len(l); br = l.bisect_right; add = l.add; c = 0
        vs = list(s)
        for v in vs: c += n - br(v)
        total[0] += c
        if len(vs) < 8:
            for v in vs: add(v)
        else:
            l.update(vs)
        return l
    return f, total
# initial: [SortedList([v]) for v in a]

def make_merge_func_coinversion():
    """
    併合する l と s の間の正順数（l の要素 <= s の要素 となる組の数）を
    total[0] に足していく。l の中・s の中の組は数えない。
    """
    total = [0]
    def f(l, s):
        br = l.bisect_right; add = l.add; c = 0
        vs = list(s)
        for v in vs: c += br(v)
        total[0] += c
        if len(vs) < 8:
            for v in vs: add(v)
        else:
            l.update(vs)
        return l
    return f, total
# initial: [SortedList([v]) for v in a]

def make_merge_func_inversion_mod(mod):
    """
    併合する l と s の間の転倒数（l の要素 > s の要素 の組の数）を
    mod で割った余りの累計として total[0] に持つ。l の中・s の中の組は数えない。
    """
    total = [0]
    def f(l, s):
        n = len(l); br = l.bisect_right; add = l.add; c = 0
        vs = list(s)
        for v in vs: c += n - br(v)
        total[0] = (total[0] + c) % mod
        if len(vs) < 8:
            for v in vs: add(v)
        else:
            l.update(vs)
        return l
    return f, total
# initial: [SortedList([v]) for v in a]

def make_merge_func_count_pairs_gt(threshold):
    """
    併合する l と s の間で、(l の要素) - (s の要素) > threshold となる組の数を
    total[0] に足していく（向き付き。絶対値ではない）。l の中・s の中の組は数えない。
    """
    total = [0]
    def f(l, s):
        n = len(l); br = l.bisect_right; add = l.add; c = 0
        vs = list(s)
        for v in vs: c += n - br(v + threshold)
        total[0] += c
        if len(vs) < 8:
            for v in vs: add(v)
        else:
            l.update(vs)
        return l
    return f, total
# initial: [SortedList([v]) for v in a]

def make_merge_func_count_pairs_in_range(lo, hi):
    """
    併合する l と s の間で、lo <= (l の要素) - (s の要素) <= hi となる組の数を
    total[0] に足していく（向き付き。lo <= hi であること）。
    l の中・s の中の組は数えない。
    """
    if lo > hi:
        raise ValueError("lo must be <= hi")
    total = [0]
    def f(l, s):
        br = l.bisect_right; bl = l.bisect_left; add = l.add; c = 0
        vs = list(s)
        for v in vs: c += br(v + hi) - bl(v + lo)
        total[0] += c
        if len(vs) < 8:
            for v in vs: add(v)
        else:
            l.update(vs)
        return l
    return f, total
# initial: [SortedList([v]) for v in a]

def make_merge_func_sum_mod(mod):
    """合計 mod m"""
    def f(l, s): return (l + s) % mod
    return f
# initial: [v % mod for v in a]

def make_merge_func_poly_hash(base, mod):
    """
    多項式ハッシュ。f(l, s) は「l の後ろに s をつないだ」ハッシュの dict を
    新しく作って返す（l も s も書き換えない）。
    """
    def f(l, s):
        return {'hash': (l['hash'] * pow(base, s['size'], mod) + s['hash']) % mod,
                'size': l['size'] + s['size']}
    return f
# initial: [{'hash': v % mod, 'size': 1} for v in a]

