def gdi_0wall_input(h, w): return [[0 for _ in range(w+2)]] + [[0] + list(map(int, input().split())) + [0] for _ in range(h)] + [[0 for _ in range(w+2)]]
def gdi_1wall_input(h, w): return [[1 for _ in range(w+2)]] + [[1] + list(map(int, input().split())) + [1] for _ in range(h)] + [[1 for _ in range(w+2)]]
def gdi_black_wall_input(h, w): return [['#' for _ in range(w+2)]] + [['#']+ ls() + ['#'] for _ in range(h)] + [['#' for _ in range(w+2)]]
def gdi_white_wall_input(h, w): return [['.' for _ in range(w+2)]] + [['.']+ ls() + ['.'] for _ in range(h)] + [['.' for _ in range(w+2)]]

def add_black_wall(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    new_grid = ['#' * (w+2)]  # 上の壁
    for row in grid:
        new_grid.append('#' + row + '#')  # 左右に壁
    new_grid.append('#' * (w+2))  # 下の壁
    return new_grid

def add_white_wall(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    new_grid = ['.' * (w+2)]  # 上の壁
    for row in grid:
        new_grid.append('.' + row + '.')  # 左右に壁
    new_grid.append('.' * (w+2))  # 下の壁
    return new_grid


