def upswap(a,b): # 大きい方が左
    if a < b:
        return b, a
    return a, b

def lowswap(a,b): # 小さい方が左
    if a < b:
        return a, b
    return b, a

def ketawa(n: int) -> int: # 各桁の合計
    return sum(map(int, str(n)))

def in_in_range_2D(y, x, H, W):
    """範囲内チェック"""
    return 0 <= y < H and 0 <= x < W

