def get_input_edges(n : int) -> list:
    edge = []
    for _ in range(n):
        edge.append(tuple(lmi()))
    return edge

def build_graph(n, edge, default_cost = 1, directed = False, build_reverse=False):
    """
    グラフを構築する関数（1-indexed対応）
    N: 頂点数
    edges: [(a, b, cost), ...] のリスト
    default_cost : cost未決定なものに割り当てる値
    directed: Trueなら有向グラフ、Falseなら無向グラフ
    build_reverse : Trueなら逆向きグラフ（rev_graph）も返す。
        無向グラフ（directed=False）の逆向きグラフは graph と同じ内容（別のリスト）になる。
    頂点番号は 0〜n（添字0は通常使わない）。範囲外は IndexError。
    """
    
    graph = [[] for _ in range(n+1)]
    rev_graph = [[] for _ in range(n + 1)] if build_reverse else None

    
    for e in edge:
        if len(e) == 2:
            a, b = e
            cost = default_cost
        elif len(e) == 3:
            a, b, cost = e
        else:
            raise ValueError(f"無効な辺データ: {e}")

        if not (0 <= a <= n and 0 <= b <= n):
            raise IndexError(f"頂点番号が範囲外: {e}")
        graph[a].append((b, cost))
        if directed:
            if build_reverse:
                rev_graph[b].append((a, cost))  # 逆方向を構築
        else:
            graph[b].append((a, cost))

    if build_reverse and not directed:
        rev_graph = [row[:] for row in graph]
    return (graph, rev_graph) if build_reverse else graph

def adjlist_to_matrix_weighted(adj, n=None, INF=10**18):
    """
    adj : [[(to, cost), ...], ...]
    n   : 頂点数（Noneならlen(adj)）
    INF : 辺が存在しないときの値。Floyd--Warshall には math.inf を推奨。

    有向隣接リストを変更せず変換し、平行辺は最小重みを残す。対角成分は
    min(0, 自己ループ重み) なので、負の自己ループだけが 0 を上書きする。
    """
    if n is None:
        n = len(adj)
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n > len(adj):
        raise ValueError("n must not exceed len(adj)")

    mat = [[INF] * n for _ in range(n)]

    # 自己距離を0にする場合
    for i in range(n):
        mat[i][i] = 0

    for u in range(n):
        for v, cost in adj[u]:
            if not isinstance(v, int):
                raise TypeError("edge destinations must be integers")
            if not 0 <= v < n:
                raise IndexError("edge destination out of range")
            mat[u][v] = min(mat[u][v], cost)

    return mat

def adjlist_to_matrix(adj, n=None):
    if n is None:
        n = len(adj)

    mat = [[0] * n for _ in range(n)]

    for u in range(n):
        for v in adj[u]:
            if not 0 <= v < n:
                raise IndexError("edge destination out of range")
            mat[u][v] = 1

    return mat

def matrix_to_adjlist(mat):
    n = len(mat)
    adj = [[] for _ in range(n)]

    for i in range(n):
        adj_i = adj[i]
        for j, x in enumerate(mat[i]):
            if x != 0:
                adj_i.append(j)

    return adj

def grid_to_id(x: int, y: int, W: int) -> int:return x * W + y
def id_to_grid(idx: int, W: int) -> tuple:return idx // W, idx % W

