def array_between(a, l, r): # 昇順リストA中の 閉区間 [数値L, 数値R]のすべての要素リスト返却する。 ex) 7, 9 -> out [7, 7,  8,  9, 9, 9, ]
    return a[bisect.bisect_left(a, l) : bisect.bisect_right(a, r)]
def array_between_index(a, l, r): # 返すindexは[ L, R )を意味することに注意(この方が累積和prefix_sumのindexと都合が良い)
    return bisect.bisect_left(a, l), bisect.bisect_right(a, r)


