def joinprint(a):
    print("".join(map(str, a)))

def psort(arr, order, dirs=None, *, in_place=False):
    """
    arr   : list[list or tuple] ソート対象
    order : 比較に使うインデックス順 (例: [0,2,1])
    dirs  : 各キーの昇降 (1=昇順, -1=降順). 未指定なら全て昇順
              文字列などの数値以外のキーも -1 で降順にできる。
    in_place : Trueなら arr 自身を並べ替えて返す

    return: ソート済みリスト
    """

    # --- 軽いエラー処理 ---
    if not isinstance(arr, list):
        raise TypeError("arr must be a list")

    if not all(isinstance(o, int) for o in order):
        raise TypeError("order must be list of int")

    if dirs is None:
        dirs = [1] * len(order)

    if len(order) != len(dirs):
        raise ValueError("order and dirs must have same length")

    if not all(d in (1, -1) for d in dirs):
        raise ValueError("dirs must contain only 1 or -1")

    # 空配列はそのまま返す
    if not arr:
        return arr if in_place else []

    # --- 後ろのキーから順に安定ソート（文字列キーでも -1 で降順にできる）---
    from operator import itemgetter
    result = arr[:]
    try:
        for i, d in zip(reversed(order), reversed(dirs)):
            result.sort(key=itemgetter(i), reverse=(d == -1))
    except IndexError:
        raise IndexError("index in order out of range for some element")
    if in_place:
        arr[:] = result
        return arr
    return result



def div_pairs_list(x : int):
    a = []
    for i in range(1, x+1):
        b = []
        for j in range(1, math.isqrt(i)+1):
            if i % j == 0:
                b.append((j, i//j))
        a.append(b)
    return [(0, 0)] + a



# ==================================================
# Geometry Library Quick Index
# やりたいこと -> 関数名
# ==================================================
#
# ------------------------------
# 基本方針・数値処理
# ------------------------------
