# float 専用の符号判定をしたい              -> fsign(x, tol)
# 値を区間 [lo, hi] に収めたい              -> clamp(x, lo, hi)
# 分数 a/b と c/d を厳密比較したい           -> cmp_frac(fr1, fr2)
# a + b√D を厳密比較したい                  -> surd_cmp(x, y, D)
# a + b√D の符号を厳密判定したい             -> surd_sgn(a, b, D)
# a + b√D のリストを厳密ソートしたい         -> surd_sort(values, D)
# 2次以下整数多項式の実根・異なる二次根比較  -> IntPolynomial2 / QuadraticAlgebraic
#
# ------------------------------
# 点・ベクトル基本演算
# ------------------------------
# 足し算                                   -> add(a, b)
# 引き算                                   -> sub(a, b)
# 符号反転                                 -> neg(a)
# スカラー倍                               -> mul(a, k)
# スカラー除算、float化                     -> div(a, k)
# 内積                                     -> dot(a, b)
# 外積                                     -> cross(a, b)
# A基準で dot(AB, AC)                       -> dot3(a, b, c)
# A基準で cross(AB, AC)                     -> cross3(a, b, c)
# 長さの2乗                                 -> norm2(a)
# 長さ、float                               -> norm(a)
# 2点間距離の2乗                            -> dist2(a, b)
# 2点間距離、float                          -> dist(a, b)
# マンハッタン距離                          -> manhattan(a, b)
# チェビシェフ距離                          -> chebyshev(a, b)
# 90度回転                                  -> rotate90(a)
# 任意角回転、float                         -> rotate(a, theta)
# 偏角 atan2、float                         -> arg(a)
# 単位ベクトル、float                       -> unit(a)
# 2ベクトルのなす角、float                  -> angle_between(a, b)
# 同一点判定                                -> same_point(a, b)
#
# ------------------------------
# 向き判定・直線・線分、すべて整数厳密
# ------------------------------
# 点 A,B,C の位置関係                       -> ccw(a, b, c)
# 外積の符号だけ見たい                      -> orientation(a, b, c)
# 2直線が平行か                             -> is_parallel(a, b, c, d)
# 2直線が直交か                             -> is_orthogonal(a, b, c, d)
# 点 P が直線 AB 上か                        -> on_line(a, b, p)
# 点 P が半直線 AB 上か                      -> on_ray(a, b, p)
# 点 P が線分 AB 上か                        -> on_segment(a, b, p)
# 直線 AB と直線 CD が交わるか               -> intersect_ll(a, b, c, d)
# 直線 AB と線分 CD が交わるか               -> intersect_ls(a, b, c, d)
# 線分 AB と線分 CD が交わるか               -> intersect_ss(a, b, c, d)
# 直線 AB と直線 CD の交点、float            -> line_intersection(a, b, c, d)
# 直線 AB と直線 CD の交点、分数             -> line_intersection_fraction(a, b, c, d)
# 線分 AB と線分 CD の交点                   -> segment_intersection_points(a, b, c, d)
# 点 P と直線 AB の距離2乗を分数で           -> line_point_dist2_frac(a, b, p)
# 点 P と線分 AB の距離2乗を分数で           -> segment_point_dist2_frac(a, b, p)
# 線分 AB と線分 CD の距離2乗を分数で        -> segment_segment_dist2_frac(a, b, c, d)
# 点 P を直線 AB に射影、float               -> projection(a, b, p)
# 点 P を直線 AB で反射、float               -> reflection(a, b, p)
# 点 P と直線 AB の距離、float               -> dist_lp(a, b, p)
# 点 P と線分 AB の距離、float               -> dist_sp(a, b, p)
# 線分 AB と線分 CD の距離、float            -> dist_ss(a, b, c, d)
# POINT/LINE/RAY/SEGMENTを統一表現           -> LinearPrimitiveExact / linear_*_exact
# 任意2線形primitiveの交差とexact domain     -> linear_intersection_exact(a, b)
# 任意2線形primitiveの距離2乗、分数          -> linear_dist2_exact(a, b)
#
# ------------------------------
# 偏角ソート、整数厳密
# ------------------------------
# 上半平面判定                              -> upper_half(p)
# 偏角比較                                  -> polar_cmp(a, b)
# 点を原点まわりに厳密偏角ソート            -> polar_sort(points, origin)
# ベクトルを厳密偏角ソート                  -> polar_sort_vectors(vectors)
# atan2 で簡易ソート、float                 -> atan2_sort(points, origin)
#
# ------------------------------
# 多角形・凸包、整数厳密
# ------------------------------
# 符号付き2倍面積                            -> polygon_area2(poly)
# 絶対値2倍面積                              -> polygon_area_abs2(poly)
# 面積、float                                -> polygon_area(poly)
# 周長、float                                -> polygon_perimeter(poly)
# 辺を順に取り出す                           -> polygon_edges(poly)
# CCWに正規化                                -> normalize_polygon_ccw(poly)
# 凸判定                                     -> is_convex(poly, strict)
# 点が単純多角形内/境界/外部か               -> contains_polygon(poly, p)
# 自己交差・retrace可walkのsigned winding     -> winding_number_exact(walk, p)
# nonzero windingによるwalk内/境界/外判定    -> point_in_walk_exact(walk, p)
# 点集合の凸包                               -> convex_hull(points, include_collinear)
# 凸多角形の直径2乗                          -> convex_diameter2(poly)
# 凸多角形の直径、float                      -> convex_diameter(poly)
# 凸多角形内判定 O(log N)                    -> contains_convex(poly, p)
# 格子多角形の境界格子点数                  -> boundary_lattice_points(poly)
# 格子多角形の内部格子点数                  -> interior_lattice_points(poly)
# 凸多角形を直線で切断、float                -> convex_cut(poly, a, b)
# 2凸多角形の共通部分、float                 -> convex_intersection(poly1, poly2)
# 凸包への接線face・strict可視辺 O(log N)     -> ConvexPolygonExact.tangents_from_external_point(p)
# 2凸集合の交差関係、整数厳密 O(N+M)         -> convex_intersection_relation_exact(p, q)
# 2凸集合の距離2乗、分数 O(N+M)              -> convex_distance2_exact(p, q)
# 有理凸polygonをinteger半平面で安全clip     -> convex_polygon_clip_halfplanes_exact(poly, hs)
# 2有理凸polygon共通部分 O(NM)               -> convex_polygon_intersection_exact(p, q)
# 有理polygon signed area2                   -> rational_polygon_area2_exact(poly)
# 軸平行長方形和の面積・全周長 O(N log N)    -> rectangle_union_measure(rectangles)
# exact polygon area/centroid/second moments    -> PolygonMomentsExact
# convex polygon x line, witnesses + side areas -> ConvexPolygonExact.slice_line_exact(a, b)
#
# ------------------------------
# 点集合・包囲図形・距離
# ------------------------------
# 最近点対距離2乗 O(N log N)                 -> closest_pair_dist2(points)
# 最近点対距離、float                        -> closest_pair_dist(points)
# 凸包周長                                   -> convex_hull_perimeter(points)
# 凸包面積                                   -> convex_hull_area(points)
# 軸平行外接長方形                           -> bounding_box(points)
# 最小包含円、float                          -> minimum_enclosing_circle(points)
# 最小面積回転長方形、float                  -> minimum_area_enclosing_rectangle(points)
# minimum-area rotated rectangle, exact O(H)    -> minimum_area_enclosing_rectangle_exact(points)
# 最小周長回転長方形、float                  -> minimum_perimeter_enclosing_rectangle(points)
# 最小幅ストリップ、float                    -> minimum_width(points)
# 点集合の包囲情報まとめ                     -> enclosing_summary(points)
# 点と多角形の距離、float                    -> dist_point_polygon(poly, p)
# 多角形同士の距離、float                    -> dist_polygon_polygon(poly1, poly2)
# 3D segment closest witnesses + distance^2     -> closest_points_segments3_exact(a, b, c, d)
# tetrahedron dimension/barycentric/containment  -> TetrahedronExact(a, b, c, d)
#
# ------------------------------
# 円、主に float
# ------------------------------
# 円と直線の交点                             -> circle_line_intersections(c, r, a, b)
# 円と線分の交点                             -> circle_segment_intersections(c, r, a, b)
# 2円の位置関係                              -> circle_circle_relation(c1, r1, c2, r2)
# 2円の交点                                  -> circle_circle_intersections(c1, r1, c2, r2)
# 2円の共通面積                              -> circle_circle_intersection_area(c1, r1, c2, r2)
# 点から円への接点                           -> tangent_points_from_point(c, r, p)
# 2円の共通接線                              -> common_tangents(c1, r1, c2, r2)
# 円と多角形の共通面積                       -> circle_polygon_intersection_area(c, r, poly)
# 半径2乗を使って円内判定、整数厳密          -> in_circle2(c, r2, p)
# 半径2乗を使って円内点数、整数厳密          -> count_points_in_circle2(points, c, r2)
# exact分岐+float交点（EPS dedupなし）        -> circle_*_intersections_tagged_approx
#
# ------------------------------
# 三角形
# ------------------------------
# 三角形2倍面積                              -> triangle_area2(a, b, c)
# 三角形面積、float                          -> triangle_area(a, b, c)
# 周長、float                                -> triangle_perimeter(a, b, c)
# 重心、float                                -> triangle_centroid(a, b, c)
# 辺長2乗                                    -> triangle_side_lengths2(a, b, c)
# 成立判定                                   -> is_valid_triangle(a, b, c)
# 点が三角形内/境界/外部か                   -> contains_triangle(a, b, c, p)
# 鋭角/直角/鈍角/退化分類                    -> triangle_angle_type(a, b, c)
# 外心、float                                -> circumcenter(a, b, c)
# 内心、float                                -> incenter(a, b, c)
# 外接円、float                              -> triangle_circumcircle(a, b, c)
# 内接円、float                              -> triangle_incircle(a, b, c)
# 垂心、float                                -> triangle_orthocenter(a, b, c)
# 三角形内の点数                             -> count_points_in_triangle(points, a, b, c)
#
# ------------------------------
# 四角形・長方形
# ------------------------------
# 4点を巡回順に並べる、整数厳密偏角          -> order_quad(points)
# 四角形分類                                 -> classify_quadrilateral(points)
# 平行四辺形/長方形/ひし形/正方形判定        -> is_parallelogram_quad / is_rectangle_quad / is_rhombus_quad / is_square_quad
# 回転長方形の頂点生成、float                -> rectangle_vertices(center, width, height, theta)
# 回転長方形内判定、float                    -> contains_rectangle(rect, p)
#
# ------------------------------
# 整数直線・格子・マンハッタン・Minkowski
# ------------------------------
# 直線 Ax+By+C=0 の正規化                    -> line_coeff(a, b)
# 方向ベクトル正規化                         -> direction(a, b, directed)
# 線分上の格子点数                           -> lattice_points_on_segment(a, b)
# 45度変換                                   -> transform45(p)
# 最大マンハッタン距離                       -> max_manhattan_dist(points)
# 2凸多角形の Minkowski 和                   -> minkowski_sum_convex(poly1, poly2)
# 整数2D affine変換・順序固定compose          -> Affine2Exact / affine2_compose_exact
# 3D dot/cross/orient/plane side             -> dot3d / cross3d / orient3d / plane_side3d
# 3D線分×三角形、全退化exact                 -> segment_triangle_intersection_exact(s, t, a, b, c)
# fraction-free determinant・d次元orientation -> determinant_bareiss / orient_nd_exact
# orientation非依存incircle/insphere          -> incircle_exact / insphere3d_exact
# 球面方向・minor大円弧交差                  -> SphericalDirectionExact / GreatCircleArcExact
# oriented一般化円の平行移動・反転           -> GeneralizedCircleExact
#
# ==================================================
# Function Reference
# 関数名 -> 出来ること
# ==================================================
# ccw(a,b,c): 1=左, -1=右, 2=c-a-b, -2=a-b-c, 0=a-c-bつまり線分上。
# contains_polygon / contains_convex / contains_triangle: 2=内部, 1=境界, 0=外部。
# polygon_area2 / triangle_area2 / quad_area2: 2倍面積を整数厳密に返す。
# polar_sort / polar_cmp: atan2 を使わず、半平面 + 外積で厳密に偏角比較する。
# dist2 / norm2 / convex_diameter2 / closest_pair_dist2: sqrt せず2乗値で厳密比較できる。
# line_point_dist2_frac / segment_point_dist2_frac: 距離2乗を (分子, 分母) で返す。
# cmp_frac: 分数を交差乗算で厳密比較する。
# surd_cmp: a+b√D 形式を float にせず厳密比較する。
# circle_* / rectangle_vertices / minimum_*_rectangle: 実数座標を返すため float を使う。
# FLOAT_TOL は float 専用であり、整数幾何判定では使わない。
# ==================================================

import math
import random
from functools import cmp_to_key

FLOAT_TOL = 1e-12
INF = float("inf")
PI = math.pi
TAU = 2.0 * math.pi


# ==================================================
# Scalar utilities
# ==================================================

def sign(x):
    if x > 0:
        return 1
    if x < 0:
        return -1
    return 0


sign_i = sign


def fsign(x, tol=FLOAT_TOL):
    if x > tol:
        return 1
    if x < -tol:
        return -1
    return 0


def clamp(x, lo, hi):
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x


def cmp_frac(fr1, fr2):
    """分数 fr1=(a, b), fr2=(c, d) を交差乗算で厳密比較する。fr1 < fr2 で -1。

    分母は正で渡す（負や 0 の検査はしない）。
    """
    a, b = fr1
    c, d = fr2
    left = a * d
    right = c * b
    if left < right:
        return -1
    if left > right:
        return 1
    return 0


# ==================================================
# Exact rational / intersection foundation (integer coordinates)
# ==================================================

GEO_LINE_INVALID = "INVALID"
GEO_LINE_PARALLEL = "PARALLEL"
GEO_LINE_SAME = "SAME"
GEO_LINE_POINT = "POINT"

GEO_SEG_NONE = "NONE"
GEO_SEG_POINT = "POINT"
GEO_SEG_OVERLAP = "OVERLAP"

GEO_OUT = 0
GEO_BOUNDARY = 1
GEO_IN = 2


def _require_integer_value_exact(value, label="value"):
    """Exact API scalar contract: Python ``int`` (``bool`` included)."""
    if not isinstance(value, int):
        raise TypeError(f"{label} must be an integer for an exact API")
    return value


def _require_integer_point_exact(point, dimension=2, label="point"):
    """Validate and freeze a nested integer point without float coercion."""
    try:
        coordinates = tuple(point)
    except TypeError as error:
        raise TypeError(f"{label} must be an iterable integer point") from error
    if len(coordinates) != dimension:
        raise ValueError(f"{label} must have dimension {dimension}")
    if not all(isinstance(value, int) for value in coordinates):
        raise TypeError(f"{label} coordinates must be integers for an exact API")
    return coordinates


def _require_integer_points_exact(points, dimension=2, label="points"):
    """Validate a possibly generated nested point sequence exactly once."""
    return tuple(
        _require_integer_point_exact(point, dimension, f"{label}[{index}]")
        for index, point in enumerate(points)
    )


def fraction_normalize_exact(num, den):
    """整数分数を既約な ``(num, den>0)`` にする。O(log max(|num|,|den|))。"""
    _require_integer_value_exact(num, "fraction numerator")
    _require_integer_value_exact(den, "fraction denominator")
    if den == 0:
        raise ZeroDivisionError("fraction denominator must be nonzero")
    if den < 0:
        num = -num
        den = -den
    g = math.gcd(abs(num), den)
    return (num // g, den // g)


def fraction_compare_exact(fr1, fr2):
    """正規化不要の整数分数2個を交差乗算で厳密比較する。O(1) bigint演算。"""
    a, b = fr1
    c, d = fr2
    for value, label in (
        (a, "first numerator"), (b, "first denominator"),
        (c, "second numerator"), (d, "second denominator"),
    ):
        _require_integer_value_exact(value, label)
    if b == 0 or d == 0:
        raise ZeroDivisionError("fraction denominator must be nonzero")
    if b < 0:
        a, b = -a, -b
    if d < 0:
        c, d = -c, -d
    left = a * d
    right = c * b
    return (left > right) - (left < right)


class RationalPointKey(tuple):
    """整数同次座標 ``(X, Y, W)`` のcanonical・hashableな有理点。

    ``W > 0`` かつ ``gcd(|X|, |Y|, W) == 1`` に必ず正規化する。
    equality/hashはcanonical tuple、順序比較は実座標 ``x``、次に ``y`` の
    cross multiplicationであり、floatへ変換しない。生成・比較はO(1) bigint演算。
    """

    __slots__ = ()

    def __new__(cls, x_num, y_num, denominator=1):
        _require_integer_value_exact(x_num, "homogeneous x numerator")
        _require_integer_value_exact(y_num, "homogeneous y numerator")
        _require_integer_value_exact(denominator, "homogeneous denominator")
        if denominator == 0:
            raise ZeroDivisionError("homogeneous denominator must be nonzero")
        if denominator < 0:
            x_num = -x_num
            y_num = -y_num
            denominator = -denominator
        g = math.gcd(math.gcd(abs(x_num), abs(y_num)), denominator)
        return tuple.__new__(
            cls,
            (x_num // g, y_num // g, denominator // g),
        )

    @property
    def x_num(self):
        return self[0]

    @property
    def y_num(self):
        return self[1]

    @property
    def denominator(self):
        return self[2]

    def as_fractions(self):
        """``((x_num, den), (y_num, den))`` を返す。O(1)。"""
        return ((self[0], self[2]), (self[1], self[2]))

    def to_float(self):
        """最終出力向けの ``(float(x), float(y))``。topology判定には使わない。"""
        return (self[0] / self[2], self[1] / self[2])

    @staticmethod
    def _compare(a, b):
        try:
            bx, by, bw = b
        except (TypeError, ValueError):
            return NotImplemented
        if not all(isinstance(value, int) for value in (bx, by, bw)):
            raise TypeError("exact rational point comparison requires integers")
        if bw == 0:
            raise ZeroDivisionError("homogeneous denominator must be nonzero")
        ax, ay, aw = a
        if bw < 0:
            bx, by, bw = -bx, -by, -bw
        left = ax * bw
        right = bx * aw
        if left != right:
            return (left > right) - (left < right)
        left = ay * bw
        right = by * aw
        return (left > right) - (left < right)

    def __lt__(self, other):
        comparison = self._compare(self, other)
        return NotImplemented if comparison is NotImplemented else comparison < 0

    def __le__(self, other):
        comparison = self._compare(self, other)
        return NotImplemented if comparison is NotImplemented else comparison <= 0

    def __gt__(self, other):
        comparison = self._compare(self, other)
        return NotImplemented if comparison is NotImplemented else comparison > 0

    def __ge__(self, other):
        comparison = self._compare(self, other)
        return NotImplemented if comparison is NotImplemented else comparison >= 0


def rational_point_key(x_num, y_num, denominator=1):
    """RationalPointKeyをcanonical生成する短いfactory。"""
    return RationalPointKey(x_num, y_num, denominator)


def rational_point_from_integer(point):
    """整数点 ``(x,y)`` を denominator=1 のRationalPointKeyへ変換。"""
    return RationalPointKey(point[0], point[1], 1)


# ==================================================
# Exact comparison for a + b * sqrt(D)
# ==================================================

def surd_sgn(a, b, D):
    """a + b√D の符号（-1, 0, 1）を整数だけで厳密に返す。D は 0 以上の整数。"""
    if b == 0 or D == 0:
        return sign(a)
    if a == 0:
        return sign(b)
    if a > 0 and b > 0:
        return 1
    if a < 0 and b < 0:
        return -1

    aa = a * a
    bbD = b * b * D

    if b > 0 and a < 0:
        if bbD > aa:
            return 1
        if bbD < aa:
            return -1
        return 0

    if aa > bbD:
        return 1
    if aa < bbD:
        return -1
    return 0


def surd_cmp(x, y, D):
    return surd_sgn(x[0] - y[0], x[1] - y[1], D)


def surd_lt(x, y, D):
    return surd_cmp(x, y, D) < 0


def surd_le(x, y, D):
    return surd_cmp(x, y, D) <= 0


def surd_gt(x, y, D):
    return surd_cmp(x, y, D) > 0


def surd_ge(x, y, D):
    return surd_cmp(x, y, D) >= 0


def surd_sort(values, D):
    return sorted(values, key=cmp_to_key(lambda x, y: surd_cmp(x, y, D)))


def surd_to_float(x, D):
    return x[0] + x[1] * math.sqrt(D)


# ==================================================
# Degree <= 2 integer polynomials / exact real algebraic roots
# ==================================================

ALGEBRAIC_LOW = "LOW"
ALGEBRAIC_HIGH = "HIGH"


def _two_quadratic_surd_sign_exact(constant, first_coefficient, first_radicand,
                                   second_coefficient, second_radicand):
    """A+B√D+C√Eの符号を有限回のbigint比較だけで返す。"""
    if first_coefficient == 0:
        return surd_sgn(constant, second_coefficient, second_radicand)
    if second_coefficient == 0:
        return surd_sgn(constant, first_coefficient, first_radicand)
    if first_radicand == second_radicand:
        return surd_sgn(
            constant,
            first_coefficient + second_coefficient,
            first_radicand,
        )
    first_part_sign = surd_sgn(
        constant, first_coefficient, first_radicand
    )
    second_part_sign = sign(second_coefficient)
    if first_part_sign == 0:
        return second_part_sign
    if second_part_sign == 0:
        return first_part_sign
    if first_part_sign == second_part_sign:
        return first_part_sign
    squared_difference_sign = surd_sgn(
        constant * constant
        + first_coefficient * first_coefficient * first_radicand
        - second_coefficient * second_coefficient * second_radicand,
        2 * constant * first_coefficient,
        first_radicand,
    )
    return (
        squared_difference_sign
        if first_part_sign > 0
        else -squared_difference_sign
    )


class IntPolynomial2:
    """次数2以下のprimitive canonical整数多項式 ``a*x²+b*x+c``。

    gcdを除きleading coefficientを正にする。zero polynomialだけdegree=-1。
    ``real_roots()`` は定数非zeroで空、zero polynomialでNone（全実数）、
    それ以外は昇順QuadraticAlgebraic tuple。
    """

    __slots__ = ("a", "b", "c", "degree")

    def __init__(self, a=0, b=0, c=0):
        gcd = math.gcd(math.gcd(abs(a), abs(b)), abs(c))
        if gcd:
            a //= gcd
            b //= gcd
            c //= gcd
        if a < 0 or (a == 0 and b < 0) or (a == 0 and b == 0 and c < 0):
            a = -a
            b = -b
            c = -c
        self.a = a
        self.b = b
        self.c = c
        self.degree = 2 if a else (1 if b else (0 if c else -1))

    def coefficients(self):
        return (self.a, self.b, self.c)

    def serialize(self):
        return self.coefficients()

    def evaluate(self, value):
        return (self.a * value + self.b) * value + self.c

    def discriminant(self):
        if self.degree != 2:
            return None
        return self.b * self.b - 4 * self.a * self.c

    def real_roots(self):
        if self.degree < 0:
            return None
        if self.degree == 0:
            return ()
        if self.degree == 1:
            return (QuadraticAlgebraic(self, ALGEBRAIC_LOW),)
        discriminant = self.discriminant()
        if discriminant < 0:
            return ()
        low = QuadraticAlgebraic(self, ALGEBRAIC_LOW)
        if discriminant == 0:
            return (low,)
        high = QuadraticAlgebraic(self, ALGEBRAIC_HIGH)
        if low == high:
            return (low,)
        return (low, high)

    def root(self, branch=ALGEBRAIC_LOW):
        return QuadraticAlgebraic(self, branch)

    def __eq__(self, other):
        if not isinstance(other, IntPolynomial2):
            return NotImplemented
        return self.coefficients() == other.coefficients()

    def __hash__(self):
        return hash(self.coefficients())

    def __repr__(self):
        return f"IntPolynomial2{self.coefficients()!r}"


class QuadraticAlgebraic:
    """degree<=2 integer polynomialのcanonical real root。

    rational rootは既約 ``num/den`` へ必ず縮約。irrational rootはprimitive
    polynomialとLOW/HIGHで一意化する。異なる二次無理根の比較も
    ``A+B√D+C√E`` の有限exact符号判定で行い、interval refinementしない。
    """

    __slots__ = (
        "kind", "numerator", "denominator", "a", "b", "c", "branch",
        "radicand",
    )

    def __init__(self, polynomial, branch=ALGEBRAIC_LOW):
        if not isinstance(polynomial, IntPolynomial2):
            polynomial = IntPolynomial2(*polynomial)
        if branch not in (ALGEBRAIC_LOW, ALGEBRAIC_HIGH):
            raise ValueError("quadratic root branch must be LOW or HIGH")
        if polynomial.degree <= 0:
            raise ValueError("constant polynomial has no isolated real root")
        self.a = polynomial.a
        self.b = polynomial.b
        self.c = polynomial.c
        self.branch = branch
        self.radicand = 0
        if polynomial.degree == 1:
            self._set_rational(-polynomial.c, polynomial.b)
            return
        discriminant = polynomial.discriminant()
        if discriminant < 0:
            raise ValueError("quadratic polynomial has no real root")
        square_root = math.isqrt(discriminant)
        if square_root * square_root == discriminant:
            signed_root = -square_root if branch == ALGEBRAIC_LOW else square_root
            self._set_rational(-polynomial.b + signed_root, 2 * polynomial.a)
            return
        self.kind = "QUADRATIC"
        self.numerator = None
        self.denominator = None
        self.radicand = discriminant

    @classmethod
    def from_rational(cls, numerator, denominator=1):
        polynomial = IntPolynomial2(0, denominator, -numerator)
        return cls(polynomial)

    def _set_rational(self, numerator, denominator):
        numerator, denominator = fraction_normalize_exact(numerator, denominator)
        self.kind = "RATIONAL"
        self.numerator = numerator
        self.denominator = denominator
        self.a = 0
        self.b = denominator
        self.c = -numerator
        self.branch = ALGEBRAIC_LOW
        self.radicand = 0

    def minimal_polynomial(self):
        return IntPolynomial2(self.a, self.b, self.c)

    def serialize(self):
        if self.kind == "RATIONAL":
            return ("RATIONAL", self.numerator, self.denominator)
        return ("QUADRATIC", self.a, self.b, self.c, self.branch)

    def _surd_expression(self):
        if self.kind == "RATIONAL":
            return (self.numerator, 0, 0, self.denominator)
        coefficient = -1 if self.branch == ALGEBRAIC_LOW else 1
        return (-self.b, coefficient, self.radicand, 2 * self.a)

    @staticmethod
    def _coerce(other):
        if isinstance(other, QuadraticAlgebraic):
            return other
        if isinstance(other, int):
            return QuadraticAlgebraic.from_rational(other)
        if isinstance(other, tuple) and len(other) == 2:
            return QuadraticAlgebraic.from_rational(other[0], other[1])
        return NotImplemented

    def compare(self, other):
        other = self._coerce(other)
        if other is NotImplemented:
            raise TypeError("QuadraticAlgebraic compares with algebraic/int/(num,den)")
        first_constant, first_coefficient, first_radicand, first_denominator = (
            self._surd_expression()
        )
        second_constant, second_coefficient, second_radicand, second_denominator = (
            other._surd_expression()
        )
        constant = (
            first_constant * second_denominator
            - second_constant * first_denominator
        )
        first_coefficient *= second_denominator
        second_coefficient *= -first_denominator
        return _two_quadratic_surd_sign_exact(
            constant,
            first_coefficient,
            first_radicand,
            second_coefficient,
            second_radicand,
        )

    def sign(self):
        return self.compare(0)

    def in_closed_unit_interval(self):
        return self.compare(0) >= 0 and self.compare(1) <= 0

    def to_float(self):
        if self.kind == "RATIONAL":
            return self.numerator / self.denominator
        root = math.sqrt(self.radicand)
        if self.branch == ALGEBRAIC_LOW:
            root = -root
        return (-self.b + root) / (2 * self.a)

    def __eq__(self, other):
        other = self._coerce(other)
        if other is NotImplemented:
            return False
        return self.compare(other) == 0

    def __lt__(self, other):
        return self.compare(other) < 0

    def __le__(self, other):
        return self.compare(other) <= 0

    def __gt__(self, other):
        return self.compare(other) > 0

    def __ge__(self, other):
        return self.compare(other) >= 0

    def __hash__(self):
        return hash(self.serialize())

    def __repr__(self):
        return f"QuadraticAlgebraic{self.serialize()!r}"


# ==================================================
# Point / Vector
# ==================================================

def add(a, b):
    return (a[0] + b[0], a[1] + b[1])


def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])


def neg(a):
    return (-a[0], -a[1])


def mul(a, k):
    return (a[0] * k, a[1] * k)


def div(a, k):
    return (a[0] / k, a[1] / k)


def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]


def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]


def dot3(a, b, c):
    return (b[0] - a[0]) * (c[0] - a[0]) + (b[1] - a[1]) * (c[1] - a[1])


def cross3(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])


def norm2(a):
    return a[0] * a[0] + a[1] * a[1]


def norm(a):
    return math.sqrt(norm2(a))


abs_vec = norm


def dist2(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    return dx * dx + dy * dy


def dist(a, b):
    return math.sqrt(dist2(a, b))


def manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])


def chebyshev(a, b):
    return max(abs(a[0] - b[0]), abs(a[1] - b[1]))


def rotate90(a):
    return (-a[1], a[0])


def rotate(a, theta):
    c = math.cos(theta)
    s = math.sin(theta)
    return (a[0] * c - a[1] * s, a[0] * s + a[1] * c)


def arg(a):
    return math.atan2(a[1], a[0])


def unit(a):
    d = norm(a)
    if d == 0:
        return (0.0, 0.0)
    return (a[0] / d, a[1] / d)


def angle_between(a, b):
    d = norm(a) * norm(b)
    if d == 0:
        return 0.0
    return math.acos(clamp(dot(a, b) / d, -1.0, 1.0))


def normalize_angle(theta):
    """角度（ラジアン）を [0, 2π) に直す。"""
    theta %= TAU
    if theta >= TAU:
        theta = 0.0
    return theta


def same_point(a, b):
    return a[0] == b[0] and a[1] == b[1]


# Backward-readable exact aliases.
add_i = add
sub_i = sub
neg_i = neg
mul_i = mul
dot_i = dot
cross_i = cross
dot3_i = dot3
cross3_i = cross3
norm2_i = norm2
dist2_i = dist2
manhattan_i = manhattan
chebyshev_i = chebyshev
rotate90_i = rotate90


# ==================================================
# ccw / orientation
# ==================================================

def ccw(a, b, c):
    ab = sub(b, a)
    ac = sub(c, a)
    cr = cross(ab, ac)

    if cr > 0:
        return 1
    if cr < 0:
        return -1

    if dot(ab, ac) < 0:
        return 2

    if norm2(ab) < norm2(ac):
        return -2

    return 0


ccw_i = ccw


def orientation(a, b, c):
    return sign(cross3(a, b, c))


orient_i = orientation


def is_parallel(a, b, c, d):
    return norm2(sub(b, a)) != 0 and norm2(sub(d, c)) != 0 and cross(sub(b, a), sub(d, c)) == 0


def is_orthogonal(a, b, c, d):
    return norm2(sub(b, a)) != 0 and norm2(sub(d, c)) != 0 and dot(sub(b, a), sub(d, c)) == 0


# ==================================================
# Line / Segment predicates and operations
# ==================================================

def on_line(a, b, p):
    return same_point(a, p) if same_point(a, b) else cross3(a, b, p) == 0


def on_ray(a, b, p):
    return on_line(a, b, p) and dot(sub(p, a), sub(b, a)) >= 0


def on_segment(a, b, p):
    return on_line(a, b, p) and dot(sub(p, a), sub(p, b)) <= 0


def intersect_ll(a, b, c, d):
    if same_point(a, b) or same_point(c, d): return False
    return (not is_parallel(a, b, c, d)) or on_line(a, b, c)

def intersect_ls(a, b, c, d):
    if same_point(a, b): return False
    return sign(cross3(a, b, c)) * sign(cross3(a, b, d)) <= 0

def intersect_ss(a, b, c, d):
    if same_point(a, b): return on_segment(c, d, a)
    if same_point(c, d): return on_segment(a, b, c)
    return ccw(a, b, c) * ccw(a, b, d) <= 0 and ccw(c, d, a) * ccw(c, d, b) <= 0
def line_intersection_exact(a, b, c, d):
    """整数2点で表す2無限直線を厳密分類する。

    Returns:
        ``(GEO_LINE_INVALID, None)``: a==b または c==d
        ``(GEO_LINE_PARALLEL, None)``: 異なる平行線
        ``(GEO_LINE_SAME, None)``: 同一直線
        ``(GEO_LINE_POINT, RationalPointKey)``: 一意な交点

    浮動小数点の除算・float・EPSを使わずO(1) bigint演算（交点の最後の約分だけ
    gcdと整数の ``//`` を使う）。座標が int の2要素なら入力検査を省く速い経路を通る
    （PyPy で座標 10^9 のとき 1 回 約 0.5 マイクロ秒。N 本の直線の全組 N = 2000 で約 1 秒。以前は約 4 秒）。
    """
    try:
        ax, ay = a
        bx, by = b
        cx, cy = c
        dx, dy = d
        fast = (type(ax) is int and type(ay) is int and type(bx) is int and type(by) is int
                and type(cx) is int and type(cy) is int and type(dx) is int and type(dy) is int)
    except (TypeError, ValueError):
        fast = False
    if not fast:
        a = _require_integer_point_exact(a, 2, "first line start")
        b = _require_integer_point_exact(b, 2, "first line end")
        c = _require_integer_point_exact(c, 2, "second line start")
        d = _require_integer_point_exact(d, 2, "second line end")
        ax, ay = a
        bx, by = b
        cx, cy = c
        dx, dy = d
    if (ax == bx and ay == by) or (cx == dx and cy == dy):
        return (GEO_LINE_INVALID, None)
    vx = bx - ax
    vy = by - ay
    wx = dx - cx
    wy = dy - cy
    denominator = vx * wy - vy * wx
    if denominator == 0:
        if vx * (cy - ay) - vy * (cx - ax) == 0:
            return (GEO_LINE_SAME, None)
        return (GEO_LINE_PARALLEL, None)
    parameter_num = (cx - ax) * wy - (cy - ay) * wx
    x_num = ax * denominator + vx * parameter_num
    y_num = ay * denominator + vy * parameter_num
    return (GEO_LINE_POINT, _g09_rpk(x_num, y_num, denominator))


def line_intersection_kind_exact(a, b, c, d):
    """line_intersection_exactの分類文字列だけ返す。O(1) bigint演算。"""
    return line_intersection_exact(a, b, c, d)[0]


def segment_intersection_exact(a, b, c, d):
    """整数線分を退化込みで厳密分類する。

    常に ``(kind, points)`` を返し、pointsはRationalPointKeyのtuple。
    NONEなら空、POINTなら長さ1、正の長さで重なるOVERLAPなら両端2点。
    OVERLAP端点は座標辞書順にcanonical化する。O(1) bigint演算。
    """
    a = _require_integer_point_exact(a, 2, "first segment start")
    b = _require_integer_point_exact(b, 2, "first segment end")
    c = _require_integer_point_exact(c, 2, "second segment start")
    d = _require_integer_point_exact(d, 2, "second segment end")
    if a == b and c == d:
        if a == c:
            return (GEO_SEG_POINT, (rational_point_from_integer(a),))
        return (GEO_SEG_NONE, ())
    if a == b:
        if on_segment(c, d, a):
            return (GEO_SEG_POINT, (rational_point_from_integer(a),))
        return (GEO_SEG_NONE, ())
    if c == d:
        if on_segment(a, b, c):
            return (GEO_SEG_POINT, (rational_point_from_integer(c),))
        return (GEO_SEG_NONE, ())

    o1 = cross3(a, b, c)
    o2 = cross3(a, b, d)
    o3 = cross3(c, d, a)
    o4 = cross3(c, d, b)

    if o1 == 0 and o2 == 0:
        a1, a2 = sorted((a, b))
        c1, c2 = sorted((c, d))
        low = max(a1, c1)
        high = min(a2, c2)
        if low > high:
            return (GEO_SEG_NONE, ())
        low_key = rational_point_from_integer(low)
        if low == high:
            return (GEO_SEG_POINT, (low_key,))
        return (
            GEO_SEG_OVERLAP,
            (low_key, rational_point_from_integer(high)),
        )

    if ((o1 > 0 and o2 > 0) or (o1 < 0 and o2 < 0)
            or (o3 > 0 and o4 > 0) or (o3 < 0 and o4 < 0)):
        return (GEO_SEG_NONE, ())

    for point, orientation_value, left, right in (
        (c, o1, a, b),
        (d, o2, a, b),
        (a, o3, c, d),
        (b, o4, c, d),
    ):
        if orientation_value == 0 and on_segment(left, right, point):
            return (GEO_SEG_POINT, (rational_point_from_integer(point),))

    kind, point = line_intersection_exact(a, b, c, d)
    if kind != GEO_LINE_POINT:
        return (GEO_SEG_NONE, ())
    return (GEO_SEG_POINT, (point,))


def segment_intersection_kind_exact(a, b, c, d):
    """segment_intersection_exactのNONE/POINT/OVERLAPだけ返す。"""
    return segment_intersection_exact(a, b, c, d)[0]


def segments_intersect_exact(a, b, c, d):
    """退化を含む2整数線分の共通部分が空でないか。"""
    return segment_intersection_kind_exact(a, b, c, d) != GEO_SEG_NONE


def segments_properly_intersect_exact(a, b, c, d):
    """両線分の相対内部で1点交差するか。端点接触・退化・重なりはFalse。"""
    a = _require_integer_point_exact(a, 2, "first segment start")
    b = _require_integer_point_exact(b, 2, "first segment end")
    c = _require_integer_point_exact(c, 2, "second segment start")
    d = _require_integer_point_exact(d, 2, "second segment end")
    if a == b or c == d:
        return False
    o1 = cross3(a, b, c)
    o2 = cross3(a, b, d)
    o3 = cross3(c, d, a)
    o4 = cross3(c, d, b)
    return ((o1 > 0) != (o2 > 0)) and ((o3 > 0) != (o4 > 0)) and all(
        value != 0 for value in (o1, o2, o3, o4)
    )


def segments_touch_exact(a, b, c, d):
    """共通部分が1点で、proper crossingではないか。"""
    kind, _ = segment_intersection_exact(a, b, c, d)
    return kind == GEO_SEG_POINT and not segments_properly_intersect_exact(a, b, c, d)


def segments_overlap_exact(a, b, c, d):
    """共通部分が正の長さを持つ線分か。"""
    return segment_intersection_kind_exact(a, b, c, d) == GEO_SEG_OVERLAP


# ==================================================
# Unified exact linear primitives
# ==================================================

GEO_PRIMITIVE_POINT = "POINT"
GEO_PRIMITIVE_LINE = "LINE"
GEO_PRIMITIVE_RAY = "RAY"
GEO_PRIMITIVE_SEGMENT = "SEGMENT"


class LinearPrimitiveExact:
    """整数 ``origin + t * direction`` とparameter domainで表す線形図形。

    ``kind`` は POINT/LINE/RAY/SEGMENT。domainはそれぞれ
    ``[0,0] / (-inf,inf) / [0,inf) / [0,1]`` で、端点は既約
    ``(num,den)``、無限端はNone。zero directionはkindに関係なくPOINTへ
    canonical化する。判定はすべて整数bigint exact。
    """

    __slots__ = ("kind", "origin", "direction", "parameter_domain")

    def __init__(self, origin, direction=(0, 0), kind=GEO_PRIMITIVE_LINE):
        if kind not in {
            GEO_PRIMITIVE_POINT,
            GEO_PRIMITIVE_LINE,
            GEO_PRIMITIVE_RAY,
            GEO_PRIMITIVE_SEGMENT,
        }:
            raise ValueError("unknown exact linear primitive kind")
        origin = _require_integer_point_exact(origin, 2, "primitive origin")
        direction = _require_integer_point_exact(
            direction, 2, "primitive direction"
        )
        if kind == GEO_PRIMITIVE_POINT or direction == (0, 0):
            kind = GEO_PRIMITIVE_POINT
            direction = (0, 0)
            domain = ((0, 1), (0, 1))
        elif kind == GEO_PRIMITIVE_LINE:
            domain = (None, None)
        elif kind == GEO_PRIMITIVE_RAY:
            domain = ((0, 1), None)
        else:
            domain = ((0, 1), (1, 1))
        self.kind = kind
        self.origin = origin
        self.direction = direction
        self.parameter_domain = domain

    @classmethod
    def point(cls, point):
        return cls(point, (0, 0), GEO_PRIMITIVE_POINT)

    @classmethod
    def line(cls, a, b):
        return cls(a, sub(b, a), GEO_PRIMITIVE_LINE)

    @classmethod
    def ray(cls, origin, through):
        return cls(origin, sub(through, origin), GEO_PRIMITIVE_RAY)

    @classmethod
    def segment(cls, a, b):
        return cls(a, sub(b, a), GEO_PRIMITIVE_SEGMENT)

    def endpoint(self):
        """SEGMENTの終点。ほかのkindではNone。O(1)。"""
        if self.kind != GEO_PRIMITIVE_SEGMENT:
            return None
        return add(self.origin, self.direction)

    def __repr__(self):
        return (
            "LinearPrimitiveExact("
            f"origin={self.origin!r}, direction={self.direction!r}, "
            f"kind={self.kind!r})"
        )


def linear_point_exact(point):
    """整数点をexact POINT primitiveへ変換。"""
    return LinearPrimitiveExact.point(point)


def linear_line_exact(a, b):
    """2整数点を通るexact LINE。a==bならPOINTへcanonical化。"""
    return LinearPrimitiveExact.line(a, b)


def linear_ray_exact(origin, through):
    """originからthrough方向のexact RAY。両点同一ならPOINT。"""
    return LinearPrimitiveExact.ray(origin, through)


def linear_segment_exact(a, b):
    """整数端点のexact SEGMENT。a==bならPOINT。"""
    return LinearPrimitiveExact.segment(a, b)


def _fraction_add_exact(left, right):
    return fraction_normalize_exact(
        left[0] * right[1] + right[0] * left[1],
        left[1] * right[1],
    )


def _fraction_sub_exact(left, right):
    return fraction_normalize_exact(
        left[0] * right[1] - right[0] * left[1],
        left[1] * right[1],
    )


def _fraction_mul_exact(left, right):
    return fraction_normalize_exact(left[0] * right[0], left[1] * right[1])


def _fraction_div_exact(left, right):
    if right[0] == 0:
        raise ZeroDivisionError("fraction division by zero")
    return fraction_normalize_exact(left[0] * right[1], left[1] * right[0])


def _fraction_min_exact(left, right):
    return left if fraction_compare_exact(left, right) <= 0 else right


def _fraction_max_exact(left, right):
    return left if fraction_compare_exact(left, right) >= 0 else right


def _parameter_in_primitive_exact(numerator, denominator, primitive):
    """未約分parameterがprimitive domain内かを交差乗算だけで判定。"""
    if denominator < 0:
        numerator = -numerator
        denominator = -denominator
    if primitive.kind == GEO_PRIMITIVE_LINE:
        return True
    if primitive.kind == GEO_PRIMITIVE_POINT:
        return numerator == 0
    if primitive.kind == GEO_PRIMITIVE_RAY:
        return numerator >= 0
    return 0 <= numerator <= denominator


def _point_on_linear_primitive_exact(point, primitive):
    if primitive.kind == GEO_PRIMITIVE_POINT:
        return point == primitive.origin
    vector = sub(point, primitive.origin)
    direction = primitive.direction
    if cross(direction, vector) != 0:
        return False
    parameter_num = dot(vector, direction)
    parameter_den = norm2(direction)
    return _parameter_in_primitive_exact(parameter_num, parameter_den, primitive)


def _point_parameter_on_linear_exact(point, primitive):
    """primitive上の整数点parameterを既約分数で返す。"""
    if primitive.kind == GEO_PRIMITIVE_POINT:
        return (0, 1)
    direction = primitive.direction
    return fraction_normalize_exact(
        dot(sub(point, primitive.origin), direction),
        norm2(direction),
    )


def _rational_point_at_parameter_exact(primitive, parameter):
    numerator, denominator = parameter
    return RationalPointKey(
        primitive.origin[0] * denominator + primitive.direction[0] * numerator,
        primitive.origin[1] * denominator + primitive.direction[1] * numerator,
        denominator,
    )


def _primitive_interval_mapped_to_first_exact(first, second):
    """collinear non-point second domainをfirst parameterへ写す。"""
    direction = first.direction
    if direction[0] != 0:
        alpha = fraction_normalize_exact(
            second.origin[0] - first.origin[0], direction[0]
        )
        beta = fraction_normalize_exact(second.direction[0], direction[0])
    else:
        alpha = fraction_normalize_exact(
            second.origin[1] - first.origin[1], direction[1]
        )
        beta = fraction_normalize_exact(second.direction[1], direction[1])
    if second.kind == GEO_PRIMITIVE_LINE:
        return (None, None), alpha, beta
    if second.kind == GEO_PRIMITIVE_RAY:
        if beta[0] > 0:
            return (alpha, None), alpha, beta
        return (None, alpha), alpha, beta
    other = _fraction_add_exact(alpha, beta)
    return (_fraction_min_exact(alpha, other), _fraction_max_exact(alpha, other)), alpha, beta


def _intersect_parameter_intervals_exact(first_domain, second_domain):
    first_low, first_high = first_domain
    second_low, second_high = second_domain
    if first_low is None:
        low = second_low
    elif second_low is None:
        low = first_low
    else:
        low = _fraction_max_exact(first_low, second_low)
    if first_high is None:
        high = second_high
    elif second_high is None:
        high = first_high
    else:
        high = _fraction_min_exact(first_high, second_high)
    if low is not None and high is not None:
        if fraction_compare_exact(low, high) > 0:
            return None
    return (low, high)


def _map_interval_from_first_exact(domain, alpha, beta):
    """first parameter intervalをsecond parameter s=(t-alpha)/betaへ写す。"""
    low, high = domain

    def convert(value):
        return _fraction_div_exact(_fraction_sub_exact(value, alpha), beta)

    if beta[0] > 0:
        return (
            None if low is None else convert(low),
            None if high is None else convert(high),
        )
    return (
        None if high is None else convert(high),
        None if low is None else convert(low),
    )


def _integer_point_from_rational_exact(point):
    if point.denominator != 1:
        raise ArithmeticError("linear overlap endpoint unexpectedly non-integral")
    return (point.x_num, point.y_num)


def _overlap_primitive_from_interval_exact(first, domain):
    low, high = domain
    if low is None and high is None:
        return LinearPrimitiveExact(first.origin, first.direction, GEO_PRIMITIVE_LINE)
    if high is None:
        start = _integer_point_from_rational_exact(
            _rational_point_at_parameter_exact(first, low)
        )
        return LinearPrimitiveExact(start, first.direction, GEO_PRIMITIVE_RAY)
    if low is None:
        start = _integer_point_from_rational_exact(
            _rational_point_at_parameter_exact(first, high)
        )
        return LinearPrimitiveExact(start, neg(first.direction), GEO_PRIMITIVE_RAY)
    start_key = _rational_point_at_parameter_exact(first, low)
    end_key = _rational_point_at_parameter_exact(first, high)
    start = _integer_point_from_rational_exact(start_key)
    end = _integer_point_from_rational_exact(end_key)
    if start == end:
        return LinearPrimitiveExact.point(start)
    return LinearPrimitiveExact.segment(start, end)


def linear_intersection_exact(first, second):
    """任意のexact POINT/LINE/RAY/SEGMENT 2個の共通部分を返す。

    Returns:
        ``(NONE, None, None)``
        ``(POINT, RationalPointKey, (t_on_first, t_on_second))``
        ``(OVERLAP, LinearPrimitiveExact, (domain_on_first, domain_on_second))``

    parameter/domain端点は既約 ``(num,den)``、無限端はNone。OVERLAP witness
    自身もLINE/RAY/SEGMENTのdomainを持つ。O(1) bigint演算。
    """
    if not isinstance(first, LinearPrimitiveExact):
        raise TypeError("first must be LinearPrimitiveExact")
    if not isinstance(second, LinearPrimitiveExact):
        raise TypeError("second must be LinearPrimitiveExact")

    if first.kind == GEO_PRIMITIVE_POINT:
        if not _point_on_linear_primitive_exact(first.origin, second):
            return (GEO_SEG_NONE, None, None)
        point = rational_point_from_integer(first.origin)
        return (
            GEO_SEG_POINT,
            point,
            ((0, 1), _point_parameter_on_linear_exact(first.origin, second)),
        )
    if second.kind == GEO_PRIMITIVE_POINT:
        if not _point_on_linear_primitive_exact(second.origin, first):
            return (GEO_SEG_NONE, None, None)
        point = rational_point_from_integer(second.origin)
        return (
            GEO_SEG_POINT,
            point,
            (_point_parameter_on_linear_exact(second.origin, first), (0, 1)),
        )

    d1 = first.direction
    d2 = second.direction
    offset = sub(second.origin, first.origin)
    denominator = cross(d1, d2)
    if denominator != 0:
        first_num = cross(offset, d2)
        second_num = cross(offset, d1)
        if not _parameter_in_primitive_exact(first_num, denominator, first):
            return (GEO_SEG_NONE, None, None)
        if not _parameter_in_primitive_exact(second_num, denominator, second):
            return (GEO_SEG_NONE, None, None)
        first_parameter = fraction_normalize_exact(first_num, denominator)
        second_parameter = fraction_normalize_exact(second_num, denominator)
        point = _rational_point_at_parameter_exact(first, first_parameter)
        return (
            GEO_SEG_POINT,
            point,
            (first_parameter, second_parameter),
        )

    if cross(d1, offset) != 0:
        return (GEO_SEG_NONE, None, None)
    second_on_first, alpha, beta = _primitive_interval_mapped_to_first_exact(
        first, second
    )
    common = _intersect_parameter_intervals_exact(
        first.parameter_domain, second_on_first
    )
    if common is None:
        return (GEO_SEG_NONE, None, None)
    low, high = common
    if low is not None and high is not None:
        if fraction_compare_exact(low, high) == 0:
            point = _rational_point_at_parameter_exact(first, low)
            second_parameter = _fraction_div_exact(
                _fraction_sub_exact(low, alpha), beta
            )
            return (GEO_SEG_POINT, point, (low, second_parameter))
    overlap = _overlap_primitive_from_interval_exact(first, common)
    second_common = _map_interval_from_first_exact(common, alpha, beta)
    return (GEO_SEG_OVERLAP, overlap, (common, second_common))


def linear_intersection_kind_exact(first, second):
    """linear_intersection_exactのNONE/POINT/OVERLAPだけ返す。"""
    return linear_intersection_exact(first, second)[0]


def point_linear_dist2_exact(point, primitive):
    """整数点とexact linear primitiveの最短距離2乗を既約(num,den)で返す。"""
    point = _require_integer_point_exact(point, 2, "point")
    if not isinstance(primitive, LinearPrimitiveExact):
        raise TypeError("primitive must be LinearPrimitiveExact")
    if primitive.kind == GEO_PRIMITIVE_POINT:
        return (dist2(point, primitive.origin), 1)
    direction = primitive.direction
    vector = sub(point, primitive.origin)
    parameter_num = dot(vector, direction)
    parameter_den = norm2(direction)
    if primitive.kind in {GEO_PRIMITIVE_RAY, GEO_PRIMITIVE_SEGMENT}:
        if parameter_num <= 0:
            return (dist2(point, primitive.origin), 1)
        if (primitive.kind == GEO_PRIMITIVE_SEGMENT
                and parameter_num >= parameter_den):
            return (dist2(point, primitive.endpoint()), 1)
    area = cross(direction, vector)
    return fraction_normalize_exact(area * area, parameter_den)


def linear_dist2_exact(first, second):
    """任意のexact linear primitive間の距離2乗を既約(num,den)で返す。

    交差時は(0,1)。非交差時は有限端点から相手への射影候補だけを比較するため
    O(1) bigint演算で、LINE/RAY/SEGMENT/POINT全退化を扱う。
    """
    if linear_intersection_kind_exact(first, second) != GEO_SEG_NONE:
        return (0, 1)

    def finite_endpoints(primitive):
        if primitive.kind == GEO_PRIMITIVE_POINT:
            return (primitive.origin,)
        if primitive.kind == GEO_PRIMITIVE_RAY:
            return (primitive.origin,)
        if primitive.kind == GEO_PRIMITIVE_SEGMENT:
            return (primitive.origin, primitive.endpoint())
        return ()

    candidates = [
        point_linear_dist2_exact(point, second)
        for point in finite_endpoints(first)
    ]
    candidates.extend(
        point_linear_dist2_exact(point, first)
        for point in finite_endpoints(second)
    )
    if not candidates:
        candidates.append(point_linear_dist2_exact(first.origin, second))
    best = candidates[0]
    for candidate in candidates[1:]:
        if fraction_compare_exact(candidate, best) < 0:
            best = candidate
    return best


on_line_i = on_line
on_ray_i = on_ray
on_segment_i = on_segment
intersect_ll_i = intersect_ll
intersect_ls_i = intersect_ls
intersect_ss_i = intersect_ss


def line_intersection_fraction(a, b, c, d):
    v = sub(b, a)
    w = sub(d, c)
    den = cross(v, w)

    if den == 0:
        return None

    num = cross(sub(c, a), w)
    x_num = a[0] * den + v[0] * num
    y_num = a[1] * den + v[1] * num

    if den < 0:
        den = -den
        x_num = -x_num
        y_num = -y_num

    gx = math.gcd(abs(x_num), den)
    gy = math.gcd(abs(y_num), den)

    return ((x_num // gx, den // gx), (y_num // gy, den // gy))


def line_intersection(a, b, c, d):
    frac = line_intersection_fraction(a, b, c, d)
    if frac is None:
        return None
    (xn, xd), (yn, yd) = frac
    return (xn / xd, yn / yd)


def segment_intersection_points(a, b, c, d):
    if not intersect_ss(a, b, c, d):
        return []

    if same_point(a, b):
        return [a]
    if same_point(c, d):
        return [c]

    if not on_line(a, b, c) or not on_line(a, b, d):
        p = line_intersection(a, b, c, d)
        if p is None:
            return []
        return [p]

    a1, a2 = sorted((a, b))
    c1, c2 = sorted((c, d))
    lo = max(a1, c1)
    hi = min(a2, c2)

    if lo > hi:
        return []
    if lo == hi:
        return [lo]
    return [lo, hi]


def line_point_dist2_frac(a, b, p):
    ab = sub(b, a)
    den = norm2(ab)
    if den == 0:
        return (dist2(a, p), 1)
    cr = cross(ab, sub(p, a))
    return (cr * cr, den)


def segment_point_dist2_frac(a, b, p):
    ab = sub(b, a)
    if norm2(ab) == 0:
        return (dist2(a, p), 1)
    if dot(ab, sub(p, a)) < 0:
        return (dist2(a, p), 1)
    if dot(neg(ab), sub(p, b)) < 0:
        return (dist2(b, p), 1)
    return line_point_dist2_frac(a, b, p)


def segment_segment_dist2_frac(a, b, c, d):
    if intersect_ss(a, b, c, d):
        return (0, 1)
    vals = [
        segment_point_dist2_frac(a, b, c),
        segment_point_dist2_frac(a, b, d),
        segment_point_dist2_frac(c, d, a),
        segment_point_dist2_frac(c, d, b),
    ]
    best = vals[0]
    for v in vals[1:]:
        if cmp_frac(v, best) < 0:
            best = v
    return best


def projection(a, b, p):
    base = sub(b, a)
    l2 = norm2(base)
    if l2 == 0:
        return (float(a[0]), float(a[1]))
    r = dot(sub(p, a), base) / l2
    return add(a, mul(base, r))


def reflection(a, b, p):
    q = projection(a, b, p)
    return sub(mul(q, 2.0), p)


def dist_lp(a, b, p):
    num, den = line_point_dist2_frac(a, b, p)
    return math.sqrt(num / den)


def dist_sp(a, b, p):
    num, den = segment_point_dist2_frac(a, b, p)
    return math.sqrt(num / den)


def dist_ll(a, b, c, d):
    if intersect_ll(a, b, c, d):
        return 0.0
    if same_point(a, b):
        return dist_lp(c, d, a)
    return dist_lp(a, b, c)


def dist_ls(a, b, c, d):
    if intersect_ls(a, b, c, d):
        return 0.0
    if same_point(a, b):
        return dist_sp(c, d, a)
    return min(dist_lp(a, b, c), dist_lp(a, b, d))


def dist_ss(a, b, c, d):
    num, den = segment_segment_dist2_frac(a, b, c, d)
    return math.sqrt(num / den)


# ==================================================
# Exact polar angle sort
# ==================================================

def upper_half(p):
    x, y = p
    if y > 0:
        return 0
    if y == 0 and x >= 0:
        return 0
    return 1


upper_half_i = upper_half


def polar_cmp(a, b):
    """ベクトル a, b を偏角 [0, 2π) の順に比べる比較関数（-1, 0, 1）。cmp_to_key 用。

    偏角は「上半分（y > 0、または y == 0 かつ x >= 0）が先」と外積の符号で厳密に比べる。
    注意: 同じ向きのベクトルどうしは長さ（ノルムの2乗）の短い方を小さいとする。
    つまり (1, 1) と (2, 2) は 0 ではなく -1 を返す。向きだけを比べたい（同じ向きなら 0）
    ときは arg_cmp を使う。零ベクトルは偏角 0 で長さ最小として先頭に来る。
    整数座標なら厳密。O(1)。

    大量に並べるときは sorted(..., key=cmp_to_key(polar_cmp)) より polar_sort_vectors・
    polar_order（atan2 のキーで並べて近い値だけ外積で直す。PyPy で 5〜10 倍速い）を使う。

    使用例:
        >>> polar_cmp((1, 0), (0, 1)), polar_cmp((1, 1), (2, 2)), polar_cmp((0, -1), (-1, 0))
        (-1, -1, 1)
    """
    ha = upper_half(a)
    hb = upper_half(b)

    if ha != hb:
        return -1 if ha < hb else 1

    cr = cross(a, b)
    if cr > 0:
        return -1
    if cr < 0:
        return 1

    na = norm2(a)
    nb = norm2(b)
    if na < nb:
        return -1
    if na > nb:
        return 1
    return 0


polar_cmp_i = polar_cmp


def polar_sort_vectors(vectors):
    """ベクトルの列を偏角 [0, 2π) の昇順（同じ向きは短い順、零ベクトルは先頭）に並べた新しいリストを返す。

    sorted(vectors, key=cmp_to_key(polar_cmp)) と同じ結果（安定）。atan2 のキーで並べて近い値だけ
    外積で直すので PyPy で速い（N = 2×10^5 で約 0.3 秒）。整数座標なら厳密。O(N log N)。
    """
    vectors = list(vectors)
    idx = _g09_polar_idx([v[0] for v in vectors], [v[1] for v in vectors], True)
    return [vectors[i] for i in idx]


def polar_sort(points, origin=(0, 0), start=None, start_on_zero=True):
    """points を origin まわりに偏角順（反時計回り）に並べた新しいリストを返す。

    偏角は整数の外積で厳密に比べる。同じ向きの点は origin に近い順。origin と同じ
    座標の点は先頭。start=(sx, sy) を渡すとその向きを偏角0として測る
    （start_on_zero=False なら start と同じ向きの点を最後に回す）。
    結果は cmp_to_key(polar_cmp) で並べたときと同じ（安定）。

    計算量: O(N log N)。atan2 のキーで並べて値の近い塊だけを外積で並べ直すので、PyPy で
    N = 2×10^5 が約 0.3 秒（以前の cmp_to_key 版は約 1.1 秒）。2000 点で全点を基準に並べ直すと約 2〜3 秒。
    """
    points = list(points)
    ox, oy = origin
    if start is None:
        X = [p[0] - ox for p in points]
        Y = [p[1] - oy for p in points]
        idx = _g09_polar_idx(X, Y, True)
        return [points[i] for i in idx]
    sx, sy = start
    if sx == 0 and sy == 0:
        raise ValueError("start must be a nonzero vector")
    U = []
    V = []
    for p in points:
        vx = p[0] - ox
        vy = p[1] - oy
        U.append(vx * sx + vy * sy)
        V.append(sx * vy - sy * vx)
    idx = _g09_polar_idx(U, V, True)
    if not start_on_zero:
        # origin と同じ点（先頭）→ 偏角 (0, 2π) の点 → start と同じ向きの点（近い順）
        zero = []
        mid = []
        last = []
        for i in idx:
            if V[i] == 0 and U[i] > 0:
                last.append(i)
            elif V[i] == 0 and U[i] == 0:
                zero.append(i)
            else:
                mid.append(i)
        idx = zero + mid + last
    return [points[i] for i in idx]


polar_sort_i = polar_sort
polar_sort_vectors_i = polar_sort_vectors


def atan2_sort(points, origin=(0, 0)):
    ox, oy = origin
    return sorted(points, key=lambda p: math.atan2(p[1] - oy, p[0] - ox))


# ==================================================
# Polygon
# ==================================================

def polygon_area2(poly):
    """多角形の符号付き面積の2倍を返す（反時計回りで正、時計回りで負）。

    本来の面積の2倍が返ることに注意。整数座標なら誤差なしの int。O(n)。
    """
    n = len(poly)
    s = 0
    for i in range(n):
        s += cross(poly[i], poly[(i + 1) % n])
    return s


polygon_area2_i = polygon_area2


def polygon_area_abs2(poly):
    return abs(polygon_area2(poly))


def polygon_area(poly):
    return abs(polygon_area2(poly)) / 2.0


def polygon_perimeter(poly):
    n = len(poly)
    if n <= 1:
        return 0.0
    s = 0.0
    for i in range(n):
        s += dist(poly[i], poly[(i + 1) % n])
    return s


def polygon_edges(poly):
    n = len(poly)
    for i in range(n):
        yield poly[i], poly[(i + 1) % n]


def normalize_polygon_ccw(poly):
    """
    多角形の頂点列を反時計回り(CCW)にそろえた新しいリストを返す。
    polygon_area2(poly) > 0 を CCW、< 0 を CW とする。
    頂点の開始位置は正規化しない。面積0（一直線など）や頂点2個以下は何もしない。
    """
    p = list(poly)
    if len(p) >= 3 and polygon_area2(p) < 0:
        p.reverse()
    return p


def polygon_centroid(poly):
    a2 = polygon_area2(poly)
    if a2 == 0:
        return None
    sx = 0
    sy = 0
    n = len(poly)
    for i in range(n):
        p = poly[i]
        q = poly[(i + 1) % n]
        cr = cross(p, q)
        sx += (p[0] + q[0]) * cr
        sy += (p[1] + q[1]) * cr
    return (sx / (3.0 * a2), sy / (3.0 * a2))


def is_convex(poly, strict=False):
    """頂点列 poly（辺の順）が凸多角形か。すべての曲がりが同じ向きで、1周だけ回る。

    strict=False なら一直線上の頂点（外積0）を許し、strict=True なら許さない。
    頂点が2個以下は False。星形や2周する列（巻き数が2以上）も False。
    """
    n = len(poly)
    if n <= 2:
        return False

    direction = 0
    first_x = first_y = last_x = last_y = 0
    changes_x = changes_y = 0
    for i in range(n):
        a = poly[i]
        b = poly[(i + 1) % n]
        dx = b[0] - a[0]
        dy = b[1] - a[1]
        if dx:
            dx = 1 if dx > 0 else -1
            if last_x == 0:
                first_x = dx
            elif dx != last_x:
                changes_x += 1
            last_x = dx
        if dy:
            dy = 1 if dy > 0 else -1
            if last_y == 0:
                first_y = dy
            elif dy != last_y:
                changes_y += 1
            last_y = dy
        cr = sign(cross3(a, b, poly[(i + 2) % n]))
        if cr == 0:
            if strict:
                return False
            continue
        if direction == 0:
            direction = cr
        elif direction * cr < 0:
            return False
    if last_x != first_x:
        changes_x += 1
    if last_y != first_y:
        changes_y += 1
    return changes_x <= 2 and changes_y <= 2


is_convex_i = is_convex


def contains_polygon(poly, p):
    inside = False
    px, py = p
    n = len(poly)

    for i in range(n):
        a = poly[i]
        b = poly[(i + 1) % n]

        if on_segment(a, b, p):
            return 1

        ax = a[0] - px
        ay = a[1] - py
        bx = b[0] - px
        by = b[1] - py

        if ay > by:
            ax, ay, bx, by = bx, by, ax, ay

        if ay <= 0 < by and cross((ax, ay), (bx, by)) > 0:
            inside = not inside

    return 2 if inside else 0


contains_polygon_i = contains_polygon


def winding_number_exact(walk, point):
    """閉walkに対するpointのsigned winding number。境界上ならNone。

    末尾から先頭への辺も含める。self-cross、辺のretrace、zero edgeを許し、
    境界判定を最優先する。上向きは ``y1 <= py < y2``、下向きは
    ``y2 <= py < y1`` のhalf-open crossingなので頂点を二重計数しない。
    O(n)、整数bigint exact。
    """
    vertices = _require_integer_points_exact(walk, 2, "walk")
    point = _require_integer_point_exact(point, 2, "query point")
    n = len(vertices)
    if n == 0:
        return 0
    px, py = point
    winding = 0
    for index in range(n):
        a = vertices[index]
        b = vertices[(index + 1) % n]
        if (a == b and a == point) or (a != b and on_segment(a, b, point)):
            return None
        side = cross3(a, b, point)
        if a[1] <= py < b[1]:
            if side > 0:
                winding += 1
        elif b[1] <= py < a[1] and side < 0:
            winding -= 1
    return winding


def point_in_walk_exact(walk, point):
    """一般の閉walkに対しGEO_OUT/BOUNDARY/INを返す。

    winding_number_exactのboundary優先・signed half-open crossingを使うため、
    self-cross/retrace/zero edgeを含むwalkでもeven-odd規則ではなくnonzero
    winding規則で分類する。O(n)、整数bigint exact。
    """
    winding = winding_number_exact(walk, point)
    if winding is None:
        return GEO_BOUNDARY
    return GEO_IN if winding != 0 else GEO_OUT


def boundary_lattice_points(poly):
    n = len(poly)
    s = 0
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        s += math.gcd(abs(x1 - x2), abs(y1 - y2))
    return s


def interior_lattice_points(poly):
    a2 = abs(polygon_area2(poly))
    b = boundary_lattice_points(poly)
    return (a2 - b + 2) // 2


def lattice_polygon_with_holes_stats_exact(outer, holes=()):
    """格子simple polygon外周と互いに素なhole群のPick統計を返す。

    Returns ``(net_area2, total_boundary_points, interior_lattice_points)``。
    各ringは非退化simple、holeはouter内部で互いに交差・包含しないことを
    前提とする。向きは任意。O(全頂点数)、整数bigint exact。
    """
    outer = _require_integer_points_exact(outer, 2, "outer")
    hole_list = [
        _require_integer_points_exact(hole, 2, f"holes[{index}]")
        for index, hole in enumerate(holes)
    ]
    net_area2 = abs(polygon_area2(outer)) - sum(
        abs(polygon_area2(hole)) for hole in hole_list
    )
    if net_area2 < 0:
        raise ValueError("total hole area exceeds outer area")
    boundary = boundary_lattice_points(outer) + sum(
        boundary_lattice_points(hole) for hole in hole_list
    )
    numerator = net_area2 - boundary + 2 - 2 * len(hole_list)
    if numerator < 0 or numerator & 1:
        raise ValueError("rings do not satisfy the lattice Pick preconditions")
    return (net_area2, boundary, numerator // 2)


# ==================================================
# Convex hull / Convex polygon
# ==================================================

def convex_hull(points, include_collinear=False):
    pts = sorted(set(points))
    n = len(pts)

    if n <= 1:
        return pts

    if include_collinear:
        all_collinear = True
        for p in pts[1:-1]:
            if cross3(pts[0], pts[-1], p) != 0:
                all_collinear = False
                break
        if all_collinear:
            return pts

    def should_pop(o, a, b):
        cr = cross3(o, a, b)
        if include_collinear:
            return cr < 0
        return cr <= 0

    lower = []
    for p in pts:
        while len(lower) >= 2 and should_pop(lower[-2], lower[-1], p):
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and should_pop(upper[-2], upper[-1], p):
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]


convex_hull_i = convex_hull


class ConvexTangentsExact(tuple):
    """凸多角形から点への接線query結果。

    tuple内容は ``(status, first_face, last_face, visible_edge_interval)``。
    faceはcanonical hull indexの ``(start,end)``（1頂点faceなら同値）、
    visible intervalはstrict visible edgeの先頭・末尾indexをinclusive cyclicで
    表す。face は IN（内部）と空集合（頂点0個）では None。頂点1個・線分でも face は
    入る。visible interval は P が外部で頂点が3個以上のときだけ入り、ON（境界上）、
    IN、頂点2個以下では None になる。
    """

    __slots__ = ()

    def __new__(cls, status, first_face, last_face, visible_edge_interval):
        return tuple.__new__(
            cls, (status, first_face, last_face, visible_edge_interval)
        )

    @property
    def status(self):
        return self[0]

    @property
    def first_face(self):
        return self[1]

    @property
    def last_face(self):
        return self[2]

    @property
    def visible_edge_interval(self):
        return self[3]


class MinimumAreaRectangleExact(tuple):
    """exact minimum-area enclosing rectangle result。

    tuple内容は ``(area_fraction, direction, vertices, support_indices)``。
    directionは符号canonicalなprimitive整数方向、verticesはCCW
    RationalPointKey、supportは ``(min_u,max_u,min_v,max_v)`` hull indices。
    """

    __slots__ = ()

    def __new__(cls, area, direction, vertices, support_indices):
        return tuple.__new__(
            cls, (area, direction, tuple(vertices), support_indices)
        )

    @property
    def area(self):
        return self[0]

    @property
    def direction(self):
        return self[1]

    @property
    def vertices(self):
        return self[2]

    @property
    def support_indices(self):
        return self[3]


GEO_SLICE_EMPTY = "EMPTY"
GEO_SLICE_POINT = "POINT"
GEO_SLICE_SEGMENT = "SEGMENT"


class ConvexLineSliceExact(tuple):
    """integer lineとconvex setのslice、および両closed halfplane area2。

    tuple内容は ``(kind, points, positive_area2, negative_area2)``。
    positiveはdirected line a->bの左側 ``cross(b-a,p-a)>=0``。
    """

    __slots__ = ()

    def __new__(cls, kind, points, positive_area2, negative_area2):
        return tuple.__new__(
            cls,
            (kind, tuple(points), positive_area2, negative_area2),
        )

    @property
    def kind(self):
        return self[0]

    @property
    def points(self):
        return self[1]

    @property
    def positive_area2(self):
        return self[2]

    @property
    def negative_area2(self):
        return self[3]


def _direction_angle_compare_exact(first, second):
    """非zero方向を長さtieなしで [0,2pi) exact比較する。"""
    first_half = upper_half(first)
    second_half = upper_half(second)
    if first_half != second_half:
        return -1 if first_half < second_half else 1
    area = cross(first, second)
    return (area < 0) - (area > 0)


class ConvexPolygonExact:
    """整数点集合をstrict convex hullへ一度だけcanonical化するquery class。

    重複点・末尾の閉じ点・辺上のcollinear点を除き、頂点は辞書順最小点から
    CCWに並ぶ。``dimension`` は空=-1、点=0、線分=1、多角形=2。
    構築 O(n log n)、contains/support/argmax/argmin/width は O(log h)、
    area/lattice stats は構築時cacheにより O(1)。全predicateは整数bigint exact。

    support plateauのtieはcanonical頂点index最小。zero directionもindex 0
    （空ならNone）。``original_indices[i]`` はその座標が入力で最初に現れた位置。
    """

    __slots__ = (
        "points", "original_indices", "dimension", "_area2", "_boundary",
        "_interior", "_edges", "_edge_angle_order", "_vertex_sum",
        "_edge_cross_prefix",
    )

    def __init__(self, points):
        source = list(_require_integer_points_exact(points, 2, "points"))
        first_index = {}
        for index, point in enumerate(source):
            if point not in first_index:
                first_index[point] = index
        hull = convex_hull(source, include_collinear=False)
        self.points = tuple(hull)
        self.original_indices = tuple(first_index[point] for point in hull)
        n = len(hull)
        self._vertex_sum = (
            sum(point[0] for point in hull),
            sum(point[1] for point in hull),
        )
        self.dimension = -1 if n == 0 else (0 if n == 1 else (1 if n == 2 else 2))
        self._area2 = polygon_area_abs2(hull) if n >= 3 else 0
        if n == 0:
            self._boundary = 0
            self._interior = 0
            self._edges = ()
            self._edge_angle_order = ()
            self._edge_cross_prefix = (0,)
        elif n == 1:
            self._boundary = 1
            self._interior = 0
            self._edges = ()
            self._edge_angle_order = ()
            self._edge_cross_prefix = (0,)
        elif n == 2:
            dx = hull[1][0] - hull[0][0]
            dy = hull[1][1] - hull[0][1]
            self._boundary = math.gcd(abs(dx), abs(dy)) + 1
            self._interior = 0
            self._edges = ()
            self._edge_angle_order = ()
            self._edge_cross_prefix = (0,)
        else:
            edges = tuple(
                (hull[(i + 1) % n][0] - hull[i][0], hull[(i + 1) % n][1] - hull[i][1])
                for i in range(n)
            )
            self._edges = edges
            # 反時計回りの真に凸な多角形の辺は偏角が巡回的に単調増加なので、偏角最小の辺から
            # 回した順がそのまま偏角順（全体を並べ替えなくてよい）。
            k0 = 0
            for i in range(1, n):
                if polar_cmp(edges[i], edges[k0]) < 0:
                    k0 = i
            self._edge_angle_order = tuple(range(k0, n)) + tuple(range(k0))
            boundary = 0
            for ex, ey in edges:
                boundary += math.gcd(ex, ey)
            self._boundary = boundary
            self._interior = (self._area2 - boundary + 2) // 2
            prefix = [0]
            acc = 0
            for index in range(n):
                p = hull[index]
                q = hull[(index + 1) % n]
                acc += p[0] * q[1] - p[1] * q[0]
                prefix.append(acc)
            self._edge_cross_prefix = tuple(prefix)

    def __len__(self):
        return len(self.points)

    def __iter__(self):
        return iter(self.points)

    def __getitem__(self, index):
        return self.points[index]

    def area2(self):
        """hullの絶対2倍面積。O(1)。"""
        return self._area2

    def boundary_lattice_points(self):
        """hull境界上の相異なる格子点数。dimension 0/1にも対応。O(1)。"""
        return self._boundary

    def interior_lattice_points(self):
        """hullの相対境界を除く2次元内部格子点数。dimension<2なら0。O(1)。"""
        return self._interior

    def lattice_stats(self):
        """``(area2, boundary_lattice, interior_lattice)``。O(1)。"""
        return (self._area2, self._boundary, self._interior)

    def contains(self, point):
        """GEO_OUT/GEO_BOUNDARY/GEO_INを返す。O(log h)、整数exact。"""
        point = _require_integer_point_exact(point, 2, "query point")
        n = len(self.points)
        if n == 0:
            return GEO_OUT
        if n == 1:
            return GEO_BOUNDARY if self.points[0] == point else GEO_OUT
        if n == 2:
            return GEO_BOUNDARY if on_segment(self.points[0], self.points[1], point) else GEO_OUT

        p0 = self.points[0]
        first_side = cross3(p0, self.points[1], point)
        last_side = cross3(p0, self.points[-1], point)
        if first_side < 0 or last_side > 0:
            return GEO_OUT
        if first_side == 0:
            return GEO_BOUNDARY if on_segment(p0, self.points[1], point) else GEO_OUT
        if last_side == 0:
            return GEO_BOUNDARY if on_segment(p0, self.points[-1], point) else GEO_OUT

        left = 1
        right = n - 1
        while right - left > 1:
            middle = (left + right) // 2
            if cross3(p0, self.points[middle], point) >= 0:
                left = middle
            else:
                right = middle
        side = cross3(self.points[left], self.points[left + 1], point)
        if side < 0:
            return GEO_OUT
        return GEO_BOUNDARY if side == 0 else GEO_IN

    def _support_candidates(self, direction):
        n = len(self.points)
        if n <= 2:
            return range(n)
        query = (-direction[1], direction[0])
        order = self._edge_angle_order
        low = 0
        high = n
        while low < high:
            middle = (low + high) // 2
            if polar_cmp(self._edges[order[middle]], query) < 0:
                low = middle + 1
            else:
                high = middle
        edge_index = order[low % n]
        return {
            edge_index,
            (edge_index - 1) % n,
            (edge_index + 1) % n,
            (edge_index + 2) % n,
        }

    def argmax(self, direction):
        """dot(direction, vertex)最大のcanonical index。tie最小、空ならNone。"""
        direction = _require_integer_point_exact(
            direction, 2, "support direction"
        )
        n = len(self.points)
        if n == 0:
            return None
        if direction[0] == 0 and direction[1] == 0:
            return 0
        candidates = self._support_candidates(direction)
        return min(
            candidates,
            key=lambda index: (-dot(direction, self.points[index]), index),
        )

    def argmin(self, direction):
        """dot(direction, vertex)最小のcanonical index。tie最小、空ならNone。"""
        direction = _require_integer_point_exact(
            direction, 2, "support direction"
        )
        return self.argmax((-direction[0], -direction[1]))

    def support_value(self, direction):
        """最大dot値。空ならNone。O(log h)。"""
        index = self.argmax(direction)
        return None if index is None else dot(direction, self.points[index])

    def support_point(self, direction):
        """最大dot頂点。空ならNone。O(log h)。"""
        index = self.argmax(direction)
        return None if index is None else self.points[index]

    def _boundary_feature(self, point):
        """BOUNDARY点の('vertex',i)または('edge',i)。dimension 2専用。"""
        vertices = self.points
        n = len(vertices)
        if point == vertices[0]:
            return ("vertex", 0)
        first_side = cross3(vertices[0], vertices[1], point)
        last_side = cross3(vertices[0], vertices[-1], point)
        if first_side == 0 and on_segment(vertices[0], vertices[1], point):
            if point == vertices[1]:
                return ("vertex", 1)
            return ("edge", 0)
        if last_side == 0 and on_segment(vertices[0], vertices[-1], point):
            if point == vertices[-1]:
                return ("vertex", n - 1)
            return ("edge", n - 1)
        left = 1
        right = n - 1
        while right - left > 1:
            middle = (left + right) // 2
            if cross3(vertices[0], vertices[middle], point) >= 0:
                left = middle
            else:
                right = middle
        if point == vertices[left]:
            return ("vertex", left)
        if point == vertices[(left + 1) % n]:
            return ("vertex", (left + 1) % n)
        return ("edge", left)

    def _negative_edge_for_outside_point(self, point):
        """OUT点からstrict visibleな辺を1本、fan searchで返す。O(log h)。"""
        vertices = self.points
        n = len(vertices)
        first_side = cross3(vertices[0], vertices[1], point)
        last_side = cross3(vertices[0], vertices[-1], point)
        if first_side < 0:
            return 0
        if last_side > 0:
            return n - 1

        candidates = []
        if first_side == 0:
            along = dot(sub(point, vertices[0]), sub(vertices[1], vertices[0]))
            candidates.extend((n - 1, 1 % n) if along < 0 else (1 % n, n - 1))
        elif last_side == 0:
            along = dot(sub(point, vertices[0]), sub(vertices[-1], vertices[0]))
            candidates.extend((0, n - 2) if along < 0 else (n - 2, 0))
        else:
            left = 1
            right = n - 1
            while right - left > 1:
                middle = (left + right) // 2
                if cross3(vertices[0], vertices[middle], point) >= 0:
                    left = middle
                else:
                    right = middle
            if cross3(vertices[left], vertices[(left + 1) % n], point) < 0:
                return left
            candidates.extend(((left - 1) % n, (left + 1) % n))
        for edge_index in candidates:
            if cross3(
                vertices[edge_index],
                vertices[(edge_index + 1) % n],
                point,
            ) < 0:
                return edge_index
        raise ArithmeticError("outside point has no strict visible convex edge")

    def _nonnegative_edge_anchor(self, point):
        """可視辺区間外の辺を内部頂点平均とedge angleから返す。O(log h)。"""
        n = len(self.points)
        direction = (
            n * point[0] - self._vertex_sum[0],
            n * point[1] - self._vertex_sum[1],
        )
        order = self._edge_angle_order
        low = 0
        high = n
        while low < high:
            middle = (low + high) // 2
            if _direction_angle_compare_exact(
                self._edges[order[middle]], direction
            ) < 0:
                low = middle + 1
            else:
                high = middle
        edge_index = order[(low - 1) % n]
        if cross3(
            self.points[edge_index],
            self.points[(edge_index + 1) % n],
            point,
        ) < 0:
            raise ArithmeticError("failed to construct a non-visible edge anchor")
        return edge_index

    def tangents_from_external_point(self, point):
        """点からstrict convex hullへの接線faceと可視辺区間。O(log h)。

        OUTではstrict visible edge（辺の右側にpoint）の唯一のcyclic intervalを
        二分探索し、その両端のsupport faceを返す。pointが接線辺の延長上なら
        singleton頂点でなくcollinearな辺両端をfaceに含める。ONでは接触辺、
        または頂点の両incident edgeを返す。INではfaceなし。
        """
        point = _require_integer_point_exact(point, 2, "external point")
        vertices = self.points
        n = len(vertices)
        if n == 0:
            return ConvexTangentsExact(GEO_OUT, None, None, None)
        if n == 1:
            status = GEO_BOUNDARY if point == vertices[0] else GEO_OUT
            face = (0, 0)
            return ConvexTangentsExact(status, face, face, None)
        if n == 2:
            if on_segment(vertices[0], vertices[1], point):
                return ConvexTangentsExact(
                    GEO_BOUNDARY, (0, 1), (0, 1), None
                )
            if cross3(vertices[0], vertices[1], point) == 0:
                return ConvexTangentsExact(GEO_OUT, (0, 1), (0, 1), None)
            return ConvexTangentsExact(GEO_OUT, (0, 0), (1, 1), None)

        status = self.contains(point)
        if status == GEO_IN:
            return ConvexTangentsExact(GEO_IN, None, None, None)
        if status == GEO_BOUNDARY:
            feature_kind, index = self._boundary_feature(point)
            if feature_kind == "edge":
                face = (index, (index + 1) % n)
                return ConvexTangentsExact(
                    GEO_BOUNDARY, face, face, None
                )
            return ConvexTangentsExact(
                GEO_BOUNDARY,
                ((index - 1) % n, index),
                (index, (index + 1) % n),
                None,
            )

        negative = self._negative_edge_for_outside_point(point)
        nonnegative = self._nonnegative_edge_anchor(point)

        distance = (negative - nonnegative) % n
        low = 0
        high = distance
        while high - low > 1:
            middle = (low + high) // 2
            edge_index = (nonnegative + middle) % n
            side = cross3(
                vertices[edge_index], vertices[(edge_index + 1) % n], point
            )
            if side < 0:
                high = middle
            else:
                low = middle
        first_visible = (nonnegative + high) % n

        distance = (nonnegative - negative) % n
        low = 0
        high = distance
        while high - low > 1:
            middle = (low + high) // 2
            edge_index = (negative + middle) % n
            side = cross3(
                vertices[edge_index], vertices[(edge_index + 1) % n], point
            )
            if side < 0:
                low = middle
            else:
                high = middle
        last_visible = (negative + low) % n

        first_vertex = first_visible
        last_vertex = (last_visible + 1) % n
        previous_edge = (first_vertex - 1) % n
        if cross3(
            vertices[previous_edge], vertices[first_vertex], point
        ) == 0:
            first_face = (previous_edge, first_vertex)
        else:
            first_face = (first_vertex, first_vertex)
        if cross3(
            vertices[last_vertex], vertices[(last_vertex + 1) % n], point
        ) == 0:
            last_face = (last_vertex, (last_vertex + 1) % n)
        else:
            last_face = (last_vertex, last_vertex)
        return ConvexTangentsExact(
            GEO_OUT,
            first_face,
            last_face,
            (first_visible, last_visible),
        )

    def width_value(self, direction):
        """max dot - min dot（方向をunit化しない幅分子）。空なら0。O(log h)。"""
        maximum = self.argmax(direction)
        if maximum is None:
            return 0
        minimum = self.argmin(direction)
        return dot(direction, self.points[maximum]) - dot(direction, self.points[minimum])

    def width(self, direction):
        """width_valueの補完しやすい別名。sqrtを取らない。"""
        return self.width_value(direction)

    def width_squared_fraction(self, direction):
        """unit方向へ射影した幅2乗を既約(num,den)で返す。zero方向はValueError。"""
        direction = _require_integer_point_exact(
            direction, 2, "width direction"
        )
        length2 = norm2(direction)
        if length2 == 0:
            raise ValueError("width direction must be nonzero")
        width = self.width_value(direction)
        return fraction_normalize_exact(width * width, length2)

    def diameter_squared_with_pair(self):
        """``(最大距離2乗, canonical index pair)``。pair tieは辞書順。O(h)。"""
        p = self.points
        n = len(p)
        if n == 0:
            return (0, None)
        if n == 1:
            return (0, (0, 0))
        if n == 2:
            return (dist2(p[0], p[1]), (0, 1))

        best_value = -1
        best_pair = None

        def update(i, j):
            nonlocal best_value, best_pair
            pair = (i, j) if i <= j else (j, i)
            value = dist2(p[i], p[j])
            if value > best_value or (value == best_value and pair < best_pair):
                best_value = value
                best_pair = pair

        j = 1
        for i in range(n):
            next_i = (i + 1) % n
            edge = sub(p[next_i], p[i])
            while True:
                next_j = (j + 1) % n
                current_area = cross(edge, sub(p[j], p[i]))
                next_area = cross(edge, sub(p[next_j], p[i]))
                if next_area > current_area:
                    j = next_j
                else:
                    break
            update(i, j)
            update(next_i, j)
            next_j = (j + 1) % n
            if cross(edge, sub(p[next_j], p[i])) == cross(edge, sub(p[j], p[i])):
                update(i, next_j)
                update(next_i, next_j)
        return (best_value, best_pair)

    def minimum_width_squared_fraction(self):
        """``(既約width²分数, (support_edge, opposite_vertex))``。O(h)。

        dimension<2ではwidth²=0、winner=None。
        """
        p = self.points
        n = len(p)
        if n <= 2:
            return ((0, 1), None)
        best_fraction = None
        best_winner = None
        j = 1
        for i in range(n):
            next_i = (i + 1) % n
            edge = sub(p[next_i], p[i])
            while True:
                next_j = (j + 1) % n
                current_height = cross(edge, sub(p[j], p[i]))
                next_height = cross(edge, sub(p[next_j], p[i]))
                if next_height > current_height:
                    j = next_j
                else:
                    break
            height = cross(edge, sub(p[j], p[i]))
            opposite = min(
                index for index in (j, (j - 1) % n, (j + 1) % n)
                if cross(edge, sub(p[index], p[i])) == height
            )
            candidate = fraction_normalize_exact(height * height, norm2(edge))
            winner = (i, opposite)
            if (best_fraction is None
                    or fraction_compare_exact(candidate, best_fraction) < 0
                    or (candidate == best_fraction and winner < best_winner)):
                best_fraction = candidate
                best_winner = winner
        return (best_fraction, best_winner)

    def minimum_area_enclosing_rectangle_exact(self):
        """strict hullのminimum-area enclosing rectangle。O(h) calipers。"""
        return _minimum_area_enclosing_rectangle_from_convex_exact(self)

    def clip_line_exact(self, a, b):
        """integer line ABとのsliceと両closed halfplane area2。O(log h)。"""
        return _convex_polygon_line_slice_exact(self, a, b)

    def slice_line_exact(self, a, b):
        """clip_line_exactの幾何検索向けalias。O(log h)。"""
        return self.clip_line_exact(a, b)

    def intersection_relation_exact(self, other):
        """別のpreprocessed convex setとのOVERLAP/TOUCH/DISJOINT。O(h+k)。"""
        return convex_intersection_relation_exact(self, other)

    def distance2_exact(self, other):
        """別のpreprocessed convex setとの距離2乗既約分数。O(h+k)。"""
        return convex_distance2_exact(self, other)


def diameter_squared_with_pair(points):
    """点集合のdiameter²とcanonical hull上の座標pair。O(n log n)。"""
    polygon = ConvexPolygonExact(points)
    value, pair = polygon.diameter_squared_with_pair()
    if pair is None:
        return (value, None)
    return (value, (polygon.points[pair[0]], polygon.points[pair[1]]))


def minimum_width_squared_fraction(points):
    """点集合hullの最小幅²既約分数とsupport witness。O(n log n)。"""
    return ConvexPolygonExact(points).minimum_width_squared_fraction()


def convex_tangents_from_external_point_exact(points, point):
    """点集合をhull化し、pointからのexact tangent query結果を返す。O(n log n)。"""
    return ConvexPolygonExact(points).tangents_from_external_point(point)


def _minimum_area_enclosing_rectangle_from_convex_exact(polygon):
    points = polygon.points
    n = len(points)
    if n == 0:
        return MinimumAreaRectangleExact((0, 1), None, (), None)
    if n == 1:
        point = rational_point_from_integer(points[0])
        return MinimumAreaRectangleExact(
            (0, 1), (1, 0), (point,), (0, 0, 0, 0)
        )
    if n == 2:
        primitive = direction(points[0], points[1], directed=True)
        if primitive[0] < 0 or (primitive[0] == 0 and primitive[1] < 0):
            primitive = neg(primitive)
        vertices = tuple(rational_point_from_integer(point) for point in points)
        return MinimumAreaRectangleExact(
            (0, 1), primitive, vertices, (0, 1, 0, 0)
        )

    first_edge = sub(points[1], points[0])
    left_index = min(range(n), key=lambda index: dot(first_edge, points[index]))
    right_index = max(range(n), key=lambda index: dot(first_edge, points[index]))
    top_index = max(range(n), key=lambda index: cross(first_edge, points[index]))
    best = None

    def advance(index, value, maximize):
        for _ in range(n):
            next_index = (index + 1) % n
            current_value = value(index)
            next_value = value(next_index)
            if (next_value > current_value) if maximize else (next_value < current_value):
                index = next_index
            else:
                break
        return index

    def plateau_min_index(index, value):
        target = value(index)
        return min(
            candidate
            for candidate in (index, (index - 1) % n, (index + 1) % n)
            if value(candidate) == target
        )

    for edge_index in range(n):
        next_edge_index = (edge_index + 1) % n
        edge = sub(points[next_edge_index], points[edge_index])

        def dot_value(index):
            return dot(edge, points[index])

        def cross_value(index):
            return cross(edge, points[index])

        left_index = advance(left_index, dot_value, False)
        right_index = advance(right_index, dot_value, True)
        top_index = advance(top_index, cross_value, True)
        left_support = plateau_min_index(left_index, dot_value)
        right_support = plateau_min_index(right_index, dot_value)
        top_support = plateau_min_index(top_index, cross_value)
        bottom_support = min(edge_index, next_edge_index)
        width = dot_value(right_support) - dot_value(left_support)
        height = cross_value(top_support) - cross_value(bottom_support)
        area = fraction_normalize_exact(width * height, norm2(edge))

        primitive = direction(points[edge_index], points[next_edge_index], directed=True)
        flipped = primitive[0] < 0 or (primitive[0] == 0 and primitive[1] < 0)
        if flipped:
            primitive = neg(primitive)
            support = (
                right_support,
                left_support,
                top_support,
                bottom_support,
            )
        else:
            support = (
                left_support,
                right_support,
                bottom_support,
                top_support,
            )
        normal = rotate90(primitive)
        minimum_u = dot(primitive, points[support[0]])
        maximum_u = dot(primitive, points[support[1]])
        minimum_v = dot(normal, points[support[2]])
        maximum_v = dot(normal, points[support[3]])
        length2 = norm2(primitive)

        def corner(u_value, v_value):
            return RationalPointKey(
                u_value * primitive[0] - v_value * primitive[1],
                u_value * primitive[1] + v_value * primitive[0],
                length2,
            )

        vertices = (
            corner(minimum_u, minimum_v),
            corner(maximum_u, minimum_v),
            corner(maximum_u, maximum_v),
            corner(minimum_u, maximum_v),
        )
        tie_key = (primitive, vertices, support)
        if (best is None
                or fraction_compare_exact(area, best[0]) < 0
                or (area == best[0] and tie_key < best[1])):
            best = (area, tie_key, vertices, support, primitive)
    return MinimumAreaRectangleExact(best[0], best[4], best[2], best[3])


def minimum_area_enclosing_rectangle_exact(points):
    """exact minimum-area rectangle。class入力O(h)、raw pointsはhull込みO(n log n)。"""
    polygon = points if isinstance(points, ConvexPolygonExact) else ConvexPolygonExact(points)
    return polygon.minimum_area_enclosing_rectangle_exact()


def _rational_cross_fraction_exact(first, second):
    return fraction_normalize_exact(
        first.x_num * second.y_num - first.y_num * second.x_num,
        first.denominator * second.denominator,
    )


def _convex_polygon_line_slice_exact(polygon, a, b):
    a = _require_integer_point_exact(a, 2, "slice line start")
    b = _require_integer_point_exact(b, 2, "slice line end")
    if a == b:
        raise ValueError("slice line requires two distinct integer points")
    points = polygon.points
    n = len(points)
    zero = (0, 1)
    if n == 0:
        return ConvexLineSliceExact(GEO_SLICE_EMPTY, (), zero, zero)
    line_direction = sub(b, a)

    def side(point):
        return cross(line_direction, sub(point, a))

    if n == 1:
        if side(points[0]) == 0:
            witness = (rational_point_from_integer(points[0]),)
            return ConvexLineSliceExact(GEO_SLICE_POINT, witness, zero, zero)
        return ConvexLineSliceExact(GEO_SLICE_EMPTY, (), zero, zero)
    if n == 2:
        first_side = side(points[0])
        second_side = side(points[1])
        if first_side == 0 and second_side == 0:
            witness = tuple(
                rational_point_from_integer(point) for point in points
            )
            return ConvexLineSliceExact(GEO_SLICE_SEGMENT, witness, zero, zero)
        if first_side == 0:
            witness = (rational_point_from_integer(points[0]),)
            return ConvexLineSliceExact(GEO_SLICE_POINT, witness, zero, zero)
        if second_side == 0:
            witness = (rational_point_from_integer(points[1]),)
            return ConvexLineSliceExact(GEO_SLICE_POINT, witness, zero, zero)
        if (first_side > 0) == (second_side > 0):
            return ConvexLineSliceExact(GEO_SLICE_EMPTY, (), zero, zero)
        point = RationalPointKey(
            first_side * points[1][0] - second_side * points[0][0],
            first_side * points[1][1] - second_side * points[0][1],
            first_side - second_side,
        )
        return ConvexLineSliceExact(GEO_SLICE_POINT, (point,), zero, zero)

    functional = (-line_direction[1], line_direction[0])
    maximum_index = polygon.argmax(functional)
    minimum_index = polygon.argmin(functional)
    maximum_side = side(points[maximum_index])
    minimum_side = side(points[minimum_index])
    total_area = (polygon.area2(), 1)
    if minimum_side > 0:
        return ConvexLineSliceExact(GEO_SLICE_EMPTY, (), total_area, zero)
    if maximum_side < 0:
        return ConvexLineSliceExact(GEO_SLICE_EMPTY, (), zero, total_area)

    if minimum_side == 0 or maximum_side == 0:
        support_index = minimum_index if minimum_side == 0 else maximum_index
        support_points = {support_index}
        for candidate in ((support_index - 1) % n, (support_index + 1) % n):
            if side(points[candidate]) == 0:
                support_points.add(candidate)
        witnesses = tuple(sorted(
            rational_point_from_integer(points[index])
            for index in support_points
        ))
        kind = GEO_SLICE_POINT if len(witnesses) == 1 else GEO_SLICE_SEGMENT
        if minimum_side == 0:
            return ConvexLineSliceExact(kind, witnesses, total_area, zero)
        return ConvexLineSliceExact(kind, witnesses, zero, total_area)

    def transition(start_index, end_index, target_nonnegative):
        distance = (end_index - start_index) % n
        low = 0
        high = distance
        while high - low > 1:
            middle = (low + high) // 2
            vertex_index = (start_index + middle) % n
            value = side(points[vertex_index])
            reached = value >= 0 if target_nonnegative else value <= 0
            if reached:
                high = middle
            else:
                low = middle
        vertex_index = (start_index + high) % n
        previous_index = (vertex_index - 1) % n
        current_side = side(points[vertex_index])
        if current_side == 0:
            return previous_index, rational_point_from_integer(points[vertex_index])
        previous_side = side(points[previous_index])
        point = RationalPointKey(
            previous_side * points[vertex_index][0]
            - current_side * points[previous_index][0],
            previous_side * points[vertex_index][1]
            - current_side * points[previous_index][1],
            previous_side - current_side,
        )
        return previous_index, point

    positive_to_negative_edge, positive_to_negative_point = transition(
        maximum_index, minimum_index, False
    )
    negative_to_positive_edge, negative_to_positive_point = transition(
        minimum_index, maximum_index, True
    )

    start_vertex = (negative_to_positive_edge + 1) % n
    end_vertex = positive_to_negative_edge
    step_count = (end_vertex - start_vertex) % n
    prefix = polygon._edge_cross_prefix
    if start_vertex + step_count <= n:
        original_cross_sum = prefix[start_vertex + step_count] - prefix[start_vertex]
    else:
        first_part = prefix[n] - prefix[start_vertex]
        remaining = start_vertex + step_count - n
        original_cross_sum = first_part + prefix[remaining]
    positive_area = (original_cross_sum, 1)
    positive_area = _fraction_add_exact(
        positive_area,
        _rational_cross_fraction_exact(
            negative_to_positive_point,
            rational_point_from_integer(points[start_vertex]),
        ),
    )
    positive_area = _fraction_add_exact(
        positive_area,
        _rational_cross_fraction_exact(
            rational_point_from_integer(points[end_vertex]),
            positive_to_negative_point,
        ),
    )
    positive_area = _fraction_add_exact(
        positive_area,
        _rational_cross_fraction_exact(
            positive_to_negative_point,
            negative_to_positive_point,
        ),
    )
    negative_area = _fraction_sub_exact(total_area, positive_area)
    witnesses = tuple(sorted((
        positive_to_negative_point,
        negative_to_positive_point,
    )))
    if witnesses[0] == witnesses[1]:
        return ConvexLineSliceExact(
            GEO_SLICE_POINT, (witnesses[0],), positive_area, negative_area
        )
    return ConvexLineSliceExact(
        GEO_SLICE_SEGMENT, witnesses, positive_area, negative_area
    )


def convex_polygon_clip_line_exact(points, a, b):
    """convex set×line slice。class入力O(log h)、raw pointsはhull込みO(n log n)。"""
    polygon = points if isinstance(points, ConvexPolygonExact) else ConvexPolygonExact(points)
    return polygon.clip_line_exact(a, b)


# ==================================================
# Exact convex relation / distance by strict Minkowski difference
# ==================================================

GEO_CONVEX_DISJOINT = "DISJOINT"
GEO_CONVEX_TOUCH = "TOUCH"
GEO_CONVEX_OVERLAP = "OVERLAP"


def _rotate_cycle_to_lowest_exact(points):
    if not points:
        return []
    start = min(range(len(points)), key=lambda index: (points[index][1], points[index][0]))
    return list(points[start:]) + list(points[:start])


def _canonical_strict_convex_cycle_exact(points):
    """strict Minkowski merge結果をlex-first CCWへO(n) canonical化。"""
    if not points:
        return ()
    cleaned = []
    for point in points:
        point = tuple(point)
        if not cleaned or point != cleaned[-1]:
            cleaned.append(point)
    if len(cleaned) > 1 and cleaned[0] == cleaned[-1]:
        cleaned.pop()
    if len(cleaned) <= 1:
        return tuple(cleaned)
    area2 = polygon_area2(cleaned)
    if area2 == 0:
        low = min(cleaned)
        high = max(cleaned)
        return (low,) if low == high else (low, high)
    if area2 < 0:
        cleaned.reverse()
    start = min(range(len(cleaned)), key=cleaned.__getitem__)
    cleaned = cleaned[start:] + cleaned[:start]
    return tuple(cleaned)


def _minkowski_sum_strict_exact(first_points, second_points):
    """strict canonical convex cyclesの和。sorting/hull再構築なしO(n+m)。"""
    if not first_points or not second_points:
        return ()
    if len(first_points) == 1:
        shift = first_points[0]
        return _canonical_strict_convex_cycle_exact(
            [add(shift, point) for point in second_points]
        )
    if len(second_points) == 1:
        shift = second_points[0]
        return _canonical_strict_convex_cycle_exact(
            [add(point, shift) for point in first_points]
        )

    first = _rotate_cycle_to_lowest_exact(first_points)
    second = _rotate_cycle_to_lowest_exact(second_points)
    first_edges = [
        sub(first[(index + 1) % len(first)], first[index])
        for index in range(len(first))
    ]
    second_edges = [
        sub(second[(index + 1) % len(second)], second[index])
        for index in range(len(second))
    ]
    result = [add(first[0], second[0])]
    first_index = 0
    second_index = 0
    while first_index < len(first_edges) or second_index < len(second_edges):
        if second_index == len(second_edges):
            edge = first_edges[first_index]
            first_index += 1
        elif first_index == len(first_edges):
            edge = second_edges[second_index]
            second_index += 1
        else:
            comparison = _direction_angle_compare_exact(
                first_edges[first_index], second_edges[second_index]
            )
            if comparison < 0:
                edge = first_edges[first_index]
                first_index += 1
            elif comparison > 0:
                edge = second_edges[second_index]
                second_index += 1
            else:
                edge = add(
                    first_edges[first_index], second_edges[second_index]
                )
                first_index += 1
                second_index += 1
        result.append(add(result[-1], edge))
    if result[-1] != result[0]:
        raise ArithmeticError("strict Minkowski edge walk did not close")
    result.pop()
    return _canonical_strict_convex_cycle_exact(result)


def _convex_difference_points_exact(first, second):
    return _minkowski_sum_strict_exact(
        first.points,
        tuple((-point[0], -point[1]) for point in second.points),
    )


def _origin_in_strict_convex_cycle_exact(points):
    """原点を相対IN/BOUNDARY/OUT分類。dimension 0/1にも対応。"""
    n = len(points)
    origin = (0, 0)
    if n == 0:
        return GEO_OUT
    if n == 1:
        return GEO_IN if points[0] == origin else GEO_OUT
    if n == 2:
        if cross3(points[0], points[1], origin) != 0:
            return GEO_OUT
        product = dot(sub(origin, points[0]), sub(origin, points[1]))
        if product < 0:
            return GEO_IN
        if product == 0:
            return GEO_BOUNDARY
        return GEO_OUT
    boundary = False
    for index in range(n):
        side = cross3(points[index], points[(index + 1) % n], origin)
        if side < 0:
            return GEO_OUT
        if side == 0:
            boundary = True
    return GEO_BOUNDARY if boundary else GEO_IN


def _as_convex_polygon_exact(points):
    return points if isinstance(points, ConvexPolygonExact) else ConvexPolygonExact(points)


def convex_intersection_relation_exact(first, second):
    """2凸集合のDISJOINT/TOUCH/OVERLAPを整数exactに分類する。

    ConvexPolygonExact同士ならstrict Minkowski difference edge mergeによりO(n+m)。
    iterable入力は各hull構築を含みO(n log n + m log m)。OVERLAPは両集合の
    relative interiorが交わる場合で、点・線分・proper segment crossingも
    dimensionに応じて一貫して扱う。
    """
    first = _as_convex_polygon_exact(first)
    second = _as_convex_polygon_exact(second)
    if not first.points or not second.points:
        return GEO_CONVEX_DISJOINT
    difference = _convex_difference_points_exact(first, second)
    status = _origin_in_strict_convex_cycle_exact(difference)
    if status == GEO_IN:
        return GEO_CONVEX_OVERLAP
    if status == GEO_BOUNDARY:
        return GEO_CONVEX_TOUCH
    return GEO_CONVEX_DISJOINT


def convex_distance2_exact(first, second):
    """2凸集合の最短距離2乗を既約 ``(num,den)`` で返す。

    ConvexPolygonExact同士ならP+(-Q)をO(n+m) edge-walkし、原点が外なら
    そのstrict boundaryまでの最短距離を走査する。空集合があればNone。
    iterable入力はhull構築のsorting時間が追加される。
    """
    first = _as_convex_polygon_exact(first)
    second = _as_convex_polygon_exact(second)
    if not first.points or not second.points:
        return None
    difference = _convex_difference_points_exact(first, second)
    if _origin_in_strict_convex_cycle_exact(difference) != GEO_OUT:
        return (0, 1)
    if len(difference) == 1:
        return (norm2(difference[0]), 1)
    if len(difference) == 2:
        return point_segment_dist2_exact((0, 0), difference[0], difference[1])
    best = point_segment_dist2_exact(
        (0, 0), difference[0], difference[1]
    )
    for index in range(1, len(difference)):
        candidate = point_segment_dist2_exact(
            (0, 0), difference[index], difference[(index + 1) % len(difference)]
        )
        if fraction_compare_exact(candidate, best) < 0:
            best = candidate
    return best


# ==================================================
# Axis-aligned rectangle union area / perimeter
# ==================================================

class RectangleUnionResult(tuple):
    """``(union_area, total_perimeter)`` のimmutable result。"""

    __slots__ = ()

    def __new__(cls, area, perimeter):
        return tuple.__new__(cls, (area, perimeter))

    @property
    def area(self):
        return self[0]

    @property
    def perimeter(self):
        return self[1]


class RectangleUnionMeasure:
    """軸平行長方形和集合の面積と全周長をsweep lineで測る。

    rectangleは ``(x1,y1,x2,y2)``。端点順は任意に正規化し、幅または高さ0は
    ignoreする。y座標圧縮 + coverage segment treeでO(N log N)、O(N) memory。
    tree内部でcovered length・covered y component数・左右端被覆を保持する。
    """

    __slots__ = ("rectangles",)

    def __init__(self, rectangles=()):
        self.rectangles = []
        for rectangle in rectangles:
            self.add(*rectangle)

    def add(self, x1, y1, x2, y2):
        """長方形を追加する。positive-areaならTrue、zero-areaならFalse。O(1)。"""
        for value, label in (
            (x1, "x1"), (y1, "y1"), (x2, "x2"), (y2, "y2")
        ):
            _require_integer_value_exact(value, f"rectangle {label}")
        if x1 > x2:
            x1, x2 = x2, x1
        if y1 > y2:
            y1, y2 = y2, y1
        if x1 == x2 or y1 == y2:
            return False
        self.rectangles.append((x1, y1, x2, y2))
        return True

    def measure(self):
        """和集合の面積と全周長 ``RectangleUnionResult(area, perimeter)`` を返す。O(N log N)。

        y を座標圧縮し、x の順にイベントを掃きながら、反復版（再帰なし）のセグメント木で
        「被覆の枚数・覆われた長さ・覆われた区間の個数・両端が覆われているか」を持つ。
        同じ x では追加を先、削除を後に行う。追加による覆われた長さの増分と削除による減分の
        和が、その x の直前・直後の被覆の対称差の長さ（縦の辺の長さ）になり、接して始まる・
        終わる長方形の共有辺を誤って数えない。横の辺は「覆われた区間の個数 × 2 × 幅」。
        PyPy で N = 2×10^5（座標 10^9 まで）が約 2 秒（以前の再帰版は約 9 秒）。
        面積だけなら rectangle_union_area の方が速い。
        """
        rects = self.rectangles
        n = len(rects)
        if n == 0:
            return RectangleUnionResult(0, 0)
        ys = sorted({v for r in rects for v in (r[1], r[3])})
        yid = {v: i for i, v in enumerate(ys)}
        m = len(ys) - 1
        size = 1
        while size < m:
            size *= 2
        full = [0] * (2 * size)
        for i in range(m):
            full[size + i] = ys[i + 1] - ys[i]
        for i in range(size - 1, 0, -1):
            full[i] = full[2 * i] + full[2 * i + 1]
        cov = [0] * (2 * size)
        ln = [0] * (2 * size)
        cp = [0] * (2 * size)
        lf = [0] * (2 * size)
        rf = [0] * (2 * size)
        n2 = 2 * n
        L = [0] * n
        R = [0] * n
        ev = [0] * n2
        for k in range(n):
            x1, y1, x2, y2 = rects[k]
            L[k] = yid[y1] + size
            R[k] = yid[y2] + size
            ev[2 * k] = x1 * n2 + k          # 追加（同じ x では先）
            ev[2 * k + 1] = x2 * n2 + n + k  # 削除
        ev.sort()
        area = 0
        per = 0
        px = ev[0] // n2
        for e in ev:
            x, k = divmod(e, n2)
            if x != px:
                dx = x - px
                area += ln[1] * dx
                per += 2 * cp[1] * dx
                px = x
            if k < n:
                d = 1
            else:
                k -= n
                d = -1
            before = ln[1]
            l = L[k]
            r = R[k]
            l0 = l
            r0 = r - 1
            while l < r:
                if l & 1:
                    cov[l] += d
                    if cov[l]:
                        ln[l] = full[l]; cp[l] = 1; lf[l] = 1; rf[l] = 1
                    elif l >= size:
                        ln[l] = 0; cp[l] = 0; lf[l] = 0; rf[l] = 0
                    else:
                        a = 2 * l
                        b = a + 1
                        ln[l] = ln[a] + ln[b]
                        cp[l] = cp[a] + cp[b] - (rf[a] & lf[b])
                        lf[l] = lf[a]
                        rf[l] = rf[b]
                    l += 1
                if r & 1:
                    r -= 1
                    cov[r] += d
                    if cov[r]:
                        ln[r] = full[r]; cp[r] = 1; lf[r] = 1; rf[r] = 1
                    elif r >= size:
                        ln[r] = 0; cp[r] = 0; lf[r] = 0; rf[r] = 0
                    else:
                        a = 2 * r
                        b = a + 1
                        ln[r] = ln[a] + ln[b]
                        cp[r] = cp[a] + cp[b] - (rf[a] & lf[b])
                        lf[r] = lf[a]
                        rf[r] = rf[b]
                l >>= 1
                r >>= 1
            for v in (l0 >> 1, r0 >> 1):
                while v:
                    if cov[v]:
                        ln[v] = full[v]; cp[v] = 1; lf[v] = 1; rf[v] = 1
                    else:
                        a = 2 * v
                        b = a + 1
                        ln[v] = ln[a] + ln[b]
                        cp[v] = cp[a] + cp[b] - (rf[a] & lf[b])
                        lf[v] = lf[a]
                        rf[v] = rf[b]
                    v >>= 1
            c = ln[1] - before
            per += c if c >= 0 else -c
        return RectangleUnionResult(area, per)

    def area_perimeter(self):
        """measureのtuple互換alias。O(N log N)。"""
        return self.measure()


def rectangle_union_measure(rectangles):
    """軸に平行な長方形の和集合の ``(面積, 全周長)`` を返す（RectangleUnionResult。.area / .perimeter でも読める）。

    引数: rectangles = [(x1, y1, x2, y2), ...]（整数座標。端点の順は任意で、幅か高さが 0 の長方形は無視）
    返り値: RectangleUnionResult(area, perimeter)。全周長は穴の周りも含めた境界の長さの合計。
    計算量: O(N log N)（y の座標圧縮 + 反復版セグメント木の平面走査）。
    PyPy で N = 2×10^5 が約 2 秒。面積だけなら rectangle_union_area（約 2 倍速い）。
    注意: 座標は int のみ（float は TypeError）。マスの集合の面積ではなく連続の面積
    （マス目なら [x, x+1) × [y, y+1) の長方形として渡す）。

    使用例:
        >>> rectangle_union_measure([(0, 0, 2, 2), (1, 1, 3, 3)])
        (7, 12)
        >>> rectangle_union_measure([(0, 0, 1, 1), (1, 0, 2, 1)])   # 接する辺は数えない
        (2, 6)
    """
    return RectangleUnionMeasure(rectangles).measure()


def rectangle_union_area_perimeter(rectangles):
    """rectangle_union_measureの検索しやすい別名。"""
    return rectangle_union_measure(rectangles)


# ==================================================
# Exact bounded rational convex clipping
# ==================================================

def _as_rational_point_key_exact(point):
    if isinstance(point, RationalPointKey):
        return point
    if len(point) == 2:
        return RationalPointKey(point[0], point[1], 1)
    if len(point) == 3:
        return RationalPointKey(point[0], point[1], point[2])
    raise ValueError("a rational 2D point must have length 2 or 3")


def _rational_orientation_numerator_exact(a, b, c):
    """有理3点のorientation符号を持つhomogeneous determinant。"""
    ax, ay, aw = a
    bx, by, bw = b
    cx, cy, cw = c
    return (
        ax * (by * cw - bw * cy)
        - ay * (bx * cw - bw * cx)
        + aw * (bx * cy - by * cx)
    )


def rational_polygon_area2_exact(polygon):
    """有理polygonのsigned 2倍面積を既約 ``(num,den)`` で返す。O(V)。

    各項を都度gcd正規化するが、clipを重ねると座標分母のbit長は増大し得る。
    Python bigint exactで上限は設けず、計算量は頂点数に加え整数bit長にも依存する。
    """
    vertices = (
        polygon.vertices
        if isinstance(polygon, RationalConvexPolygonExact)
        else tuple(_as_rational_point_key_exact(point) for point in polygon)
    )
    n = len(vertices)
    if n < 3:
        return (0, 1)
    total = (0, 1)
    for index in range(n):
        first = vertices[index]
        second = vertices[(index + 1) % n]
        term = fraction_normalize_exact(
            first.x_num * second.y_num - first.y_num * second.x_num,
            first.denominator * second.denominator,
        )
        total = _fraction_add_exact(total, term)
    return total


class RationalConvexPolygonExact:
    """cyclic convex有理点列をcanonical化したbounded intersection結果。

    ``vertices`` はRationalPointKey tuple。空=-1、点=0、線分=1、正面積=2。
    連続重複とcollinear中間点を除き、dimension 1は辞書順端点、dimension 2は
    CCWかつ辞書順最小点始まり。任意点集合のhullを作るclassではない。
    """

    __slots__ = ("vertices", "dimension")

    def __init__(self, vertices=()):
        points = []
        for point in vertices:
            point = _as_rational_point_key_exact(point)
            if not points or point != points[-1]:
                points.append(point)
        if len(points) > 1 and points[0] == points[-1]:
            points.pop()
        if not points:
            self.vertices = ()
            self.dimension = -1
            return
        if len(points) == 1:
            self.vertices = (points[0],)
            self.dimension = 0
            return

        area = rational_polygon_area2_exact(points)
        if area[0] == 0:
            low = min(points)
            high = max(points)
            self.vertices = (low,) if low == high else (low, high)
            self.dimension = 0 if low == high else 1
            return
        if area[0] < 0:
            points.reverse()

        reduced = []
        for point in points:
            while len(reduced) >= 2 and _rational_orientation_numerator_exact(
                reduced[-2], reduced[-1], point
            ) == 0:
                reduced.pop()
            reduced.append(point)
        cyclic = deque(reduced)
        while len(cyclic) >= 3:
            if _rational_orientation_numerator_exact(
                cyclic[-2], cyclic[-1], cyclic[0]
            ) == 0:
                cyclic.pop()
            elif _rational_orientation_numerator_exact(
                cyclic[-1], cyclic[0], cyclic[1]
            ) == 0:
                cyclic.popleft()
            else:
                break
        points = list(cyclic)
        if len(points) < 3:
            low = min(points)
            high = max(points)
            self.vertices = (low,) if low == high else (low, high)
            self.dimension = 0 if low == high else 1
            return
        start = min(range(len(points)), key=points.__getitem__)
        self.vertices = tuple(points[start:] + points[:start])
        self.dimension = 2

    def __len__(self):
        return len(self.vertices)

    def __iter__(self):
        return iter(self.vertices)

    def __getitem__(self, index):
        return self.vertices[index]

    def area2_exact(self):
        """signed 2倍面積の既約分数。canonicalなので非負。O(V)。"""
        return rational_polygon_area2_exact(self.vertices)

    def to_float_vertices(self):
        """最終出力用float座標。topology判定には使わない。"""
        return tuple(point.to_float() for point in self.vertices)

    def max_denominator_bits(self):
        """現在の座標分母最大bit長。空なら0。"""
        return max((point.denominator.bit_length() for point in self.vertices), default=0)


def _rational_halfplane_side_exact(point, halfplane):
    coefficient_x, coefficient_y, constant = halfplane
    return (
        coefficient_x * point.x_num
        + coefficient_y * point.y_num
        + constant * point.denominator
    )


def _rational_segment_halfplane_crossing_exact(first, second, first_side, second_side):
    """符号が異なる有理線分とinteger halfplane境界の交点。"""
    return RationalPointKey(
        first_side * second.x_num - second_side * first.x_num,
        first_side * second.y_num - second_side * first.y_num,
        first_side * second.denominator - second_side * first.denominator,
    )


def convex_polygon_clip_halfplane_exact(polygon, halfplane):
    """bounded convex polygonを閉半平面 ``Ax+By+C>=0`` でexact clip。

    RationalPointKey/整数点のcyclic列を受け、RationalConvexPolygonExactを返す。
    parallel/coincident/touch/point/segmentを含めO(V) bigint演算。一般HPIではなく、
    分母bit長は交点生成を重ねるほど増え得る。
    """
    halfplane = tuple(halfplane)
    if len(halfplane) != 3:
        raise ValueError("halfplane must be (A,B,C)")
    for index, value in enumerate(halfplane):
        _require_integer_value_exact(value, f"halfplane[{index}]")
    result = (
        polygon
        if isinstance(polygon, RationalConvexPolygonExact)
        else RationalConvexPolygonExact(polygon)
    )
    vertices = result.vertices
    if not vertices:
        return RationalConvexPolygonExact()
    if halfplane[0] == 0 and halfplane[1] == 0:
        return result if halfplane[2] >= 0 else RationalConvexPolygonExact()

    output = []
    previous = vertices[-1]
    previous_side = _rational_halfplane_side_exact(previous, halfplane)
    for current in vertices:
        current_side = _rational_halfplane_side_exact(current, halfplane)
        if current_side >= 0:
            if previous_side < 0:
                output.append(_rational_segment_halfplane_crossing_exact(
                    previous, current, previous_side, current_side
                ))
            output.append(current)
        elif previous_side > 0:
            output.append(_rational_segment_halfplane_crossing_exact(
                previous, current, previous_side, current_side
            ))
        previous = current
        previous_side = current_side
    return RationalConvexPolygonExact(output)


def convex_polygon_clip_halfplanes_exact(polygon, halfplanes):
    """integer閉半平面列でbounded convex polygonを順次clipする安全版。

    O(sum current_vertices)、``V_max``を途中最大頂点数としてworst O(H*V_max)。
    unbounded領域を構成するhalf-plane intersection APIではない。
    """
    result = (
        polygon
        if isinstance(polygon, RationalConvexPolygonExact)
        else RationalConvexPolygonExact(polygon)
    )
    for halfplane in halfplanes:
        result = convex_polygon_clip_halfplane_exact(result, halfplane)
        if result.dimension < 0:
            break
    return result


def _rational_line_coeff_exact(first, second):
    """有理2点の直線をinteger homogeneous係数へclear-denominator化。"""
    return (
        first.y_num * second.denominator - second.y_num * first.denominator,
        second.x_num * first.denominator - first.x_num * second.denominator,
        first.x_num * second.y_num - first.y_num * second.x_num,
    )


def _rational_segment_intersection_result_exact(first, second, third, fourth):
    """有理線分2本の共通部分をRationalConvexPolygonExactで返す。"""
    if first == second and third == fourth:
        return RationalConvexPolygonExact((first,)) if first == third else RationalConvexPolygonExact()

    def on_segment_exact(left, right, point):
        if left == right:
            return point == left
        if _rational_orientation_numerator_exact(left, right, point) != 0:
            return False
        return min(left, right) <= point <= max(left, right)

    if first == second:
        return RationalConvexPolygonExact((first,)) if on_segment_exact(third, fourth, first) else RationalConvexPolygonExact()
    if third == fourth:
        return RationalConvexPolygonExact((third,)) if on_segment_exact(first, second, third) else RationalConvexPolygonExact()
    first_orientation = _rational_orientation_numerator_exact(first, second, third)
    second_orientation = _rational_orientation_numerator_exact(first, second, fourth)
    third_orientation = _rational_orientation_numerator_exact(third, fourth, first)
    fourth_orientation = _rational_orientation_numerator_exact(third, fourth, second)
    if first_orientation == 0 and second_orientation == 0:
        low = max(min(first, second), min(third, fourth))
        high = min(max(first, second), max(third, fourth))
        if low > high:
            return RationalConvexPolygonExact()
        return RationalConvexPolygonExact((low,)) if low == high else RationalConvexPolygonExact((low, high))
    if ((first_orientation > 0 and second_orientation > 0)
            or (first_orientation < 0 and second_orientation < 0)
            or (third_orientation > 0 and fourth_orientation > 0)
            or (third_orientation < 0 and fourth_orientation < 0)):
        return RationalConvexPolygonExact()
    first_line = _rational_line_coeff_exact(first, second)
    second_line = _rational_line_coeff_exact(third, fourth)
    point = RationalPointKey(
        first_line[1] * second_line[2] - first_line[2] * second_line[1],
        first_line[2] * second_line[0] - first_line[0] * second_line[2],
        first_line[0] * second_line[1] - first_line[1] * second_line[0],
    )
    return RationalConvexPolygonExact((point,))


def convex_polygon_intersection_exact(first, second):
    """bounded convex有理polygon 2個の共通部分をexactに返す。

    closed Sutherland-Hodgman。返り値はvertices/dimensionを持つ
    RationalConvexPolygonExact。point/segment/touch/parallel/coincidentを含む。
    dimension 2同士のworst O(N*M)で、高速convex intersectionやHPIを装わない。
    """
    first = (
        first
        if isinstance(first, RationalConvexPolygonExact)
        else RationalConvexPolygonExact(first)
    )
    second = (
        second
        if isinstance(second, RationalConvexPolygonExact)
        else RationalConvexPolygonExact(second)
    )
    if first.dimension < 0 or second.dimension < 0:
        return RationalConvexPolygonExact()
    if first.dimension < 2 and second.dimension < 2:
        if first.dimension == 0:
            first_segment = (first.vertices[0], first.vertices[0])
        else:
            first_segment = first.vertices
        if second.dimension == 0:
            second_segment = (second.vertices[0], second.vertices[0])
        else:
            second_segment = second.vertices
        return _rational_segment_intersection_result_exact(
            first_segment[0], first_segment[1],
            second_segment[0], second_segment[1],
        )
    if first.dimension == 2:
        clippee = second if second.dimension < 2 else first
        clipper = first if second.dimension < 2 else second
    else:
        clippee = first
        clipper = second
    halfplanes = [
        _rational_line_coeff_exact(
            clipper.vertices[index],
            clipper.vertices[(index + 1) % len(clipper.vertices)],
        )
        for index in range(len(clipper.vertices))
    ]
    return convex_polygon_clip_halfplanes_exact(clippee, halfplanes)


# ==================================================
# Exact 3D foundation / segment-triangle intersection
# ==================================================

GEO_3D_NONE = "NONE"
GEO_3D_POINT = "POINT"
GEO_3D_SEGMENT = "SEGMENT"


def add3d(first, second):
    first = _require_integer_point_exact(first, 3, "first 3D vector")
    second = _require_integer_point_exact(second, 3, "second 3D vector")
    return (
        first[0] + second[0],
        first[1] + second[1],
        first[2] + second[2],
    )


def sub3d(first, second):
    first = _require_integer_point_exact(first, 3, "first 3D vector")
    second = _require_integer_point_exact(second, 3, "second 3D vector")
    return (
        first[0] - second[0],
        first[1] - second[1],
        first[2] - second[2],
    )


def neg3d(vector):
    vector = _require_integer_point_exact(vector, 3, "3D vector")
    return (-vector[0], -vector[1], -vector[2])


def mul3d(vector, scalar):
    vector = _require_integer_point_exact(vector, 3, "3D vector")
    _require_integer_value_exact(scalar, "3D integer scale")
    return (vector[0] * scalar, vector[1] * scalar, vector[2] * scalar)


def dot3d(first, second):
    first = _require_integer_point_exact(first, 3, "first 3D vector")
    second = _require_integer_point_exact(second, 3, "second 3D vector")
    return (
        first[0] * second[0]
        + first[1] * second[1]
        + first[2] * second[2]
    )


def cross3d(first, second):
    first = _require_integer_point_exact(first, 3, "first 3D vector")
    second = _require_integer_point_exact(second, 3, "second 3D vector")
    return (
        first[1] * second[2] - first[2] * second[1],
        first[2] * second[0] - first[0] * second[2],
        first[0] * second[1] - first[1] * second[0],
    )


def norm2_3d(vector):
    return dot3d(vector, vector)


def dist2_3d(first, second):
    return norm2_3d(sub3d(first, second))


def scalar_triple3d(first, second, third):
    """``dot(first, cross(second, third))``。整数入力ならbigint exact。"""
    return dot3d(first, cross3d(second, third))


def orient3d(a, b, c, d):
    """tetrahedron ``ABCD`` のsigned 6倍体積。整数bigint exact。"""
    a = _require_integer_point_exact(a, 3, "orient3d a")
    b = _require_integer_point_exact(b, 3, "orient3d b")
    c = _require_integer_point_exact(c, 3, "orient3d c")
    d = _require_integer_point_exact(d, 3, "orient3d d")
    return scalar_triple3d(sub3d(b, a), sub3d(c, a), sub3d(d, a))


def plane_side3d(a, b, c, point):
    """有向平面ABCに対するpointのside。orient3dと同値。"""
    return orient3d(a, b, c, point)


class RationalPoint3Key(tuple):
    """canonical・hashableな3D有理同次座標 ``(X,Y,Z,W>0)``。"""

    __slots__ = ()

    def __new__(cls, x_num, y_num, z_num, denominator=1):
        _require_integer_value_exact(x_num, "homogeneous x numerator")
        _require_integer_value_exact(y_num, "homogeneous y numerator")
        _require_integer_value_exact(z_num, "homogeneous z numerator")
        _require_integer_value_exact(denominator, "homogeneous denominator")
        if denominator == 0:
            raise ZeroDivisionError("homogeneous denominator must be nonzero")
        if denominator < 0:
            x_num = -x_num
            y_num = -y_num
            z_num = -z_num
            denominator = -denominator
        gcd = math.gcd(
            math.gcd(math.gcd(abs(x_num), abs(y_num)), abs(z_num)),
            denominator,
        )
        return tuple.__new__(
            cls,
            (
                x_num // gcd,
                y_num // gcd,
                z_num // gcd,
                denominator // gcd,
            ),
        )

    @property
    def x_num(self):
        return self[0]

    @property
    def y_num(self):
        return self[1]

    @property
    def z_num(self):
        return self[2]

    @property
    def denominator(self):
        return self[3]

    def as_fractions(self):
        denominator = self[3]
        return (
            (self[0], denominator),
            (self[1], denominator),
            (self[2], denominator),
        )

    def to_float(self):
        return (
            self[0] / self[3],
            self[1] / self[3],
            self[2] / self[3],
        )

    @staticmethod
    def _compare(first, second):
        try:
            bx, by, bz, bw = second
        except (TypeError, ValueError):
            return NotImplemented
        if not all(isinstance(value, int) for value in (bx, by, bz, bw)):
            raise TypeError("exact rational 3D point comparison requires integers")
        if bw == 0:
            raise ZeroDivisionError("homogeneous denominator must be nonzero")
        if bw < 0:
            bx, by, bz, bw = -bx, -by, -bz, -bw
        ax, ay, az, aw = first
        for left, right in (
            (ax * bw, bx * aw),
            (ay * bw, by * aw),
            (az * bw, bz * aw),
        ):
            if left != right:
                return (left > right) - (left < right)
        return 0

    def __lt__(self, other):
        comparison = self._compare(self, other)
        return NotImplemented if comparison is NotImplemented else comparison < 0

    def __le__(self, other):
        comparison = self._compare(self, other)
        return NotImplemented if comparison is NotImplemented else comparison <= 0

    def __gt__(self, other):
        comparison = self._compare(self, other)
        return NotImplemented if comparison is NotImplemented else comparison > 0

    def __ge__(self, other):
        comparison = self._compare(self, other)
        return NotImplemented if comparison is NotImplemented else comparison >= 0


def rational_point3_key(x_num, y_num, z_num, denominator=1):
    return RationalPoint3Key(x_num, y_num, z_num, denominator)


def rational_point3_from_integer(point):
    return RationalPoint3Key(point[0], point[1], point[2], 1)


def _rational_point3_on_segment_parameter_exact(first, second, parameter):
    numerator, denominator = parameter
    direction = sub3d(second, first)
    return RationalPoint3Key(
        first[0] * denominator + direction[0] * numerator,
        first[1] * denominator + direction[1] * numerator,
        first[2] * denominator + direction[2] * numerator,
        denominator,
    )


def _point_on_segment3d_exact(first, second, point):
    if first == second:
        return point == first
    direction = sub3d(second, first)
    offset = sub3d(point, first)
    if cross3d(direction, offset) != (0, 0, 0):
        return False
    parameter_num = dot3d(offset, direction)
    return 0 <= parameter_num <= norm2_3d(direction)


def _segment_segment_intersection3d_exact(first, second, third, fourth):
    """整数3D線分2本をNONE/POINT/SEGMENTとRationalPoint3Keyで返す。"""
    if first == second:
        if _point_on_segment3d_exact(third, fourth, first):
            return (GEO_3D_POINT, (rational_point3_from_integer(first),))
        return (GEO_3D_NONE, ())
    if third == fourth:
        if _point_on_segment3d_exact(first, second, third):
            return (GEO_3D_POINT, (rational_point3_from_integer(third),))
        return (GEO_3D_NONE, ())
    first_direction = sub3d(second, first)
    second_direction = sub3d(fourth, third)
    normal = cross3d(first_direction, second_direction)
    offset = sub3d(third, first)
    if normal == (0, 0, 0):
        if cross3d(first_direction, offset) != (0, 0, 0):
            return (GEO_3D_NONE, ())
        low = max(min(first, second), min(third, fourth))
        high = min(max(first, second), max(third, fourth))
        if low > high:
            return (GEO_3D_NONE, ())
        low_key = rational_point3_from_integer(low)
        if low == high:
            return (GEO_3D_POINT, (low_key,))
        return (GEO_3D_SEGMENT, (low_key, rational_point3_from_integer(high)))
    if dot3d(offset, normal) != 0:
        return (GEO_3D_NONE, ())
    dropped_axis = max(range(3), key=lambda axis: abs(normal[axis]))
    axes = [axis for axis in range(3) if axis != dropped_axis]
    first_2d = (first_direction[axes[0]], first_direction[axes[1]])
    second_2d = (second_direction[axes[0]], second_direction[axes[1]])
    offset_2d = (offset[axes[0]], offset[axes[1]])
    denominator = cross(first_2d, second_2d)
    first_num = cross(offset_2d, second_2d)
    second_num = cross(offset_2d, first_2d)
    if denominator < 0:
        denominator = -denominator
        first_num = -first_num
        second_num = -second_num
    if not (0 <= first_num <= denominator and 0 <= second_num <= denominator):
        return (GEO_3D_NONE, ())
    parameter = fraction_normalize_exact(first_num, denominator)
    point = _rational_point3_on_segment_parameter_exact(first, second, parameter)
    return (GEO_3D_POINT, (point,))


def _point_in_nondegenerate_triangle3d_exact(point, a, b, c, normal):
    """triangle plane上のRationalPoint3Keyをclosed triangle判定。"""
    x_num, y_num, z_num, denominator = point
    for first, second in ((a, b), (b, c), (c, a)):
        edge = sub3d(second, first)
        offset_num = (
            x_num - first[0] * denominator,
            y_num - first[1] * denominator,
            z_num - first[2] * denominator,
        )
        if dot3d(cross3d(edge, offset_num), normal) < 0:
            return False
    return True


def _clip_segment_parameter_by_triangle3d_exact(first, second, a, b, c, normal):
    """coplanar segment parameter [0,1]をtriangle 3 halfplanesでclip。"""
    low = (0, 1)
    high = (1, 1)
    direction = sub3d(second, first)
    for edge_start, edge_end in ((a, b), (b, c), (c, a)):
        edge = sub3d(edge_end, edge_start)
        start_value = dot3d(
            cross3d(edge, sub3d(first, edge_start)), normal
        )
        slope = dot3d(cross3d(edge, direction), normal)
        if slope == 0:
            if start_value < 0:
                return None
            continue
        boundary = fraction_normalize_exact(-start_value, slope)
        if slope > 0:
            low = _fraction_max_exact(low, boundary)
        else:
            high = _fraction_min_exact(high, boundary)
        if fraction_compare_exact(low, high) > 0:
            return None
    return (low, high)


def segment_triangle_intersection_exact(segment_start, segment_end, a, b, c):
    """整数3D線分とclosed triangleの共通部分を厳密に返す。

    Returns ``(NONE,()) / (POINT,(RationalPoint3Key,)) /
    (SEGMENT,(endpoint1,endpoint2))``。triangle/segment退化、coplanar crossing、
    edge overlapを含み、witnessは辞書順canonical。O(1) bigint演算。
    """
    segment_start = _require_integer_point_exact(
        segment_start, 3, "segment start"
    )
    segment_end = _require_integer_point_exact(segment_end, 3, "segment end")
    a = _require_integer_point_exact(a, 3, "triangle a")
    b = _require_integer_point_exact(b, 3, "triangle b")
    c = _require_integer_point_exact(c, 3, "triangle c")
    normal = cross3d(sub3d(b, a), sub3d(c, a))
    if normal == (0, 0, 0):
        triangle_low = min(a, b, c)
        triangle_high = max(a, b, c)
        return _segment_segment_intersection3d_exact(
            segment_start, segment_end, triangle_low, triangle_high
        )

    start_side = dot3d(normal, sub3d(segment_start, a))
    end_side = dot3d(normal, sub3d(segment_end, a))
    if ((start_side > 0 and end_side > 0)
            or (start_side < 0 and end_side < 0)):
        return (GEO_3D_NONE, ())
    if start_side == 0 and end_side == 0:
        interval = _clip_segment_parameter_by_triangle3d_exact(
            segment_start, segment_end, a, b, c, normal
        )
        if interval is None:
            return (GEO_3D_NONE, ())
        low, high = interval
        low_point = _rational_point3_on_segment_parameter_exact(
            segment_start, segment_end, low
        )
        high_point = _rational_point3_on_segment_parameter_exact(
            segment_start, segment_end, high
        )
        if low_point == high_point:
            return (GEO_3D_POINT, (low_point,))
        return (GEO_3D_SEGMENT, tuple(sorted((low_point, high_point))))

    denominator = start_side - end_side
    parameter = fraction_normalize_exact(start_side, denominator)
    point = _rational_point3_on_segment_parameter_exact(
        segment_start, segment_end, parameter
    )
    if _point_in_nondegenerate_triangle3d_exact(point, a, b, c, normal):
        return (GEO_3D_POINT, (point,))
    return (GEO_3D_NONE, ())


GEO_CLOSEST3_POINT = "POINT"
GEO_CLOSEST3_PARALLEL = "PARALLEL"
GEO_CLOSEST3_OVERLAP = "OVERLAP"
GEO_CLOSEST3_SKEW = "SKEW"


class ClosestSegments3Exact(tuple):
    """3D線分最近点result。

    tuple内容は ``(kind, (s,t), (point_on_first,point_on_second), distance2)``。
    s,tは各線分の[0,1]既約parameter。最短pair非一意時は(s,t)辞書順最小。
    """

    __slots__ = ()

    def __new__(cls, kind, parameters, points, distance2_value):
        return tuple.__new__(
            cls, (kind, tuple(parameters), tuple(points), distance2_value)
        )

    @property
    def kind(self):
        return self[0]

    @property
    def parameters(self):
        return self[1]

    @property
    def points(self):
        return self[2]

    @property
    def distance2(self):
        return self[3]


def _clamp_unit_fraction_exact(numerator, denominator):
    if denominator < 0:
        numerator = -numerator
        denominator = -denominator
    if numerator <= 0:
        return (0, 1)
    if numerator >= denominator:
        return (1, 1)
    return fraction_normalize_exact(numerator, denominator)


def _rational_point3_distance2_exact(first, second):
    denominator = first.denominator * second.denominator
    differences = (
        first.x_num * second.denominator - second.x_num * first.denominator,
        first.y_num * second.denominator - second.y_num * first.denominator,
        first.z_num * second.denominator - second.z_num * first.denominator,
    )
    return fraction_normalize_exact(
        sum(value * value for value in differences),
        denominator * denominator,
    )


def closest_points_segments3_exact(first_start, first_end, second_start, second_end):
    """整数3D線分2本のcanonical closest pairとdistance²。O(1) bigint exact。

    unconstrained interior stationary pointと4 boundary active-setを全列挙する。
    point/parallel/collinear overlap/skewを含み、Fraction/SymPyを使わない。
    """
    first_start = _require_integer_point_exact(
        first_start, 3, "first segment start"
    )
    first_end = _require_integer_point_exact(
        first_end, 3, "first segment end"
    )
    second_start = _require_integer_point_exact(
        second_start, 3, "second segment start"
    )
    second_end = _require_integer_point_exact(
        second_end, 3, "second segment end"
    )
    first_direction = sub3d(first_end, first_start)
    second_direction = sub3d(second_end, second_start)
    offset = sub3d(first_start, second_start)
    first_length2 = norm2_3d(first_direction)
    second_length2 = norm2_3d(second_direction)
    mixed = dot3d(first_direction, second_direction)
    first_offset = dot3d(first_direction, offset)
    second_offset = dot3d(second_direction, offset)
    candidates = []

    def add_candidate(first_parameter, second_parameter):
        first_point = _rational_point3_on_segment_parameter_exact(
            first_start, first_end, first_parameter
        )
        second_point = _rational_point3_on_segment_parameter_exact(
            second_start, second_end, second_parameter
        )
        distance2_value = _rational_point3_distance2_exact(
            first_point, second_point
        )
        candidates.append((
            distance2_value,
            first_parameter,
            second_parameter,
            first_point,
            second_point,
        ))

    if first_length2 == 0 and second_length2 == 0:
        add_candidate((0, 1), (0, 1))
    elif first_length2 == 0:
        add_candidate(
            (0, 1),
            _clamp_unit_fraction_exact(second_offset, second_length2),
        )
    elif second_length2 == 0:
        add_candidate(
            _clamp_unit_fraction_exact(-first_offset, first_length2),
            (0, 1),
        )
    else:
        denominator = first_length2 * second_length2 - mixed * mixed
        if denominator > 0:
            first_num = mixed * second_offset - second_length2 * first_offset
            second_num = first_length2 * second_offset - mixed * first_offset
            if (0 <= first_num <= denominator
                    and 0 <= second_num <= denominator):
                add_candidate(
                    fraction_normalize_exact(first_num, denominator),
                    fraction_normalize_exact(second_num, denominator),
                )
        add_candidate(
            (0, 1),
            _clamp_unit_fraction_exact(second_offset, second_length2),
        )
        add_candidate(
            (1, 1),
            _clamp_unit_fraction_exact(
                second_offset + mixed, second_length2
            ),
        )
        add_candidate(
            _clamp_unit_fraction_exact(-first_offset, first_length2),
            (0, 1),
        )
        add_candidate(
            _clamp_unit_fraction_exact(
                mixed - first_offset, first_length2
            ),
            (1, 1),
        )

    def candidate_compare(first, second):
        comparison = fraction_compare_exact(first[0], second[0])
        if comparison:
            return comparison
        comparison = fraction_compare_exact(first[1], second[1])
        if comparison:
            return comparison
        return fraction_compare_exact(first[2], second[2])

    best = min(candidates, key=cmp_to_key(candidate_compare))
    first_point, second_point = best[3], best[4]
    if first_length2 == 0 or second_length2 == 0:
        kind = GEO_CLOSEST3_POINT
    elif cross3d(first_direction, second_direction) == (0, 0, 0):
        intersection_kind = _segment_segment_intersection3d_exact(
            first_start, first_end, second_start, second_end
        )[0]
        kind = (
            GEO_CLOSEST3_OVERLAP
            if intersection_kind == GEO_3D_SEGMENT
            else GEO_CLOSEST3_POINT
            if intersection_kind == GEO_3D_POINT
            else GEO_CLOSEST3_PARALLEL
        )
    elif best[0][0] == 0:
        kind = GEO_CLOSEST3_POINT
    else:
        kind = GEO_CLOSEST3_SKEW
    return ClosestSegments3Exact(
        kind,
        (best[1], best[2]),
        (first_point, second_point),
        best[0],
    )


class TetrahedronExact:
    """整数4点のtetrahedron/degenerate convex hull exact query class。

    ``dimension`` は0/1/2/3。dimension 3ではhomogeneous barycentric weights、
    全dimensionでrelative closed hull containmentを提供する。
    """

    __slots__ = (
        "vertices", "volume6", "dimension", "status", "_line_endpoints",
        "_plane_origin", "_plane_normal", "_projection_axis",
        "_projected_hull",
    )

    def __init__(self, a, b, c, d):
        self.vertices = (
            _require_integer_point_exact(a, 3, "tetrahedron a"),
            _require_integer_point_exact(b, 3, "tetrahedron b"),
            _require_integer_point_exact(c, 3, "tetrahedron c"),
            _require_integer_point_exact(d, 3, "tetrahedron d"),
        )
        a, b, c, d = self.vertices
        self.volume6 = orient3d(a, b, c, d)
        self._line_endpoints = None
        self._plane_origin = None
        self._plane_normal = None
        self._projection_axis = None
        self._projected_hull = None
        if self.volume6 != 0:
            self.dimension = 3
            self.status = "NONDEGENERATE"
            return
        unique = list(dict.fromkeys(self.vertices))
        if len(unique) == 1:
            self.dimension = 0
            self.status = "DEGENERATE"
            self._line_endpoints = (unique[0], unique[0])
            return
        origin = unique[0]
        base_direction = sub3d(unique[1], origin)
        normal = None
        for point in unique[2:]:
            candidate = cross3d(base_direction, sub3d(point, origin))
            if candidate != (0, 0, 0):
                normal = candidate
                break
        if normal is None:
            self.dimension = 1
            self.status = "DEGENERATE"
            self._line_endpoints = (min(unique), max(unique))
            return
        self.dimension = 2
        self.status = "DEGENERATE"
        self._plane_origin = origin
        self._plane_normal = normal
        self._projection_axis = max(
            range(3), key=lambda axis: abs(normal[axis])
        )
        axes = [axis for axis in range(3) if axis != self._projection_axis]
        self._projected_hull = ConvexPolygonExact([
            (point[axes[0]], point[axes[1]]) for point in unique
        ])

    def signed_volume6(self):
        return self.volume6

    def barycentric_homogeneous_exact(self, point):
        """``(wa,wb,wc,wd,den>0)``。lambda_i=wi/den。degenerateならNone。"""
        point = _require_integer_point_exact(point, 3, "query point")
        if self.dimension != 3:
            return None
        a, b, c, d = self.vertices
        weights = [
            orient3d(point, b, c, d),
            orient3d(a, point, c, d),
            orient3d(a, b, point, d),
            orient3d(a, b, c, point),
        ]
        denominator = self.volume6
        if denominator < 0:
            weights = [-value for value in weights]
            denominator = -denominator
        gcd = denominator
        for value in weights:
            gcd = math.gcd(gcd, abs(value))
        return tuple(value // gcd for value in weights) + (denominator // gcd,)

    def barycentric_weights_exact(self, point):
        """4つの既約fraction weight。degenerateならNone。"""
        homogeneous = self.barycentric_homogeneous_exact(point)
        if homogeneous is None:
            return None
        denominator = homogeneous[4]
        return tuple(
            fraction_normalize_exact(homogeneous[index], denominator)
            for index in range(4)
        )

    def contains_closed(self, point):
        """4点のrelative closed convex hullにpointが属するか。"""
        point = _require_integer_point_exact(point, 3, "query point")
        if self.dimension == 3:
            homogeneous = self.barycentric_homogeneous_exact(point)
            return all(weight >= 0 for weight in homogeneous[:4])
        if self.dimension == 0:
            return point == self._line_endpoints[0]
        if self.dimension == 1:
            return _point_on_segment3d_exact(
                self._line_endpoints[0], self._line_endpoints[1], point
            )
        if dot3d(
            self._plane_normal, sub3d(point, self._plane_origin)
        ) != 0:
            return False
        axes = [axis for axis in range(3) if axis != self._projection_axis]
        projected = (point[axes[0]], point[axes[1]])
        return self._projected_hull.contains(projected) != GEO_OUT


def tetrahedron_signed_volume6(a, b, c, d):
    return orient3d(a, b, c, d)


def tetrahedron_contains_closed_exact(a, b, c, d, point):
    return TetrahedronExact(a, b, c, d).contains_closed(point)


# ==================================================
# Exact integer affine transforms in 2D
# ==================================================

class Affine2Exact:
    """整数行列 ``[[a,b],[c,d]]`` と整数translationの2D affine変換。

    ``apply`` は整数点を整数tupleへ、RationalPointKeyを同型へ写す。
    ``compose(after,before)`` の順序は必ず ``after(before(point))``。
    determinant 0も許し、topologyや面積倍率はfloatを使わない。
    """

    __slots__ = ("a", "b", "c", "d", "tx", "ty")

    def __init__(self, a=1, b=0, c=0, d=1, tx=0, ty=0):
        for value, label in (
            (a, "a"), (b, "b"), (c, "c"), (d, "d"),
            (tx, "tx"), (ty, "ty"),
        ):
            _require_integer_value_exact(value, f"affine coefficient {label}")
        self.a = a
        self.b = b
        self.c = c
        self.d = d
        self.tx = tx
        self.ty = ty

    @classmethod
    def identity(cls):
        return cls()

    @classmethod
    def translation(cls, dx, dy):
        return cls(1, 0, 0, 1, dx, dy)

    @classmethod
    def scale(cls, scale_x, scale_y=None):
        if scale_y is None:
            scale_y = scale_x
        return cls(scale_x, 0, 0, scale_y, 0, 0)

    @classmethod
    def rotation90(cls, quarter_turns=1):
        turns = quarter_turns % 4
        if turns == 0:
            return cls.identity()
        if turns == 1:
            return cls(0, -1, 1, 0)
        if turns == 2:
            return cls(-1, 0, 0, -1)
        return cls(0, 1, -1, 0)

    def coefficients(self):
        return (self.a, self.b, self.c, self.d, self.tx, self.ty)

    def apply(self, point):
        """pointへ変換を1回適用。O(1) exact。"""
        if isinstance(point, RationalPointKey) or len(point) == 3:
            point = _as_rational_point_key_exact(point)
            return RationalPointKey(
                self.a * point.x_num
                + self.b * point.y_num
                + self.tx * point.denominator,
                self.c * point.x_num
                + self.d * point.y_num
                + self.ty * point.denominator,
                point.denominator,
            )
        x, y = _require_integer_point_exact(point, 2, "affine point")
        return (
            self.a * x + self.b * y + self.tx,
            self.c * x + self.d * y + self.ty,
        )

    def apply_vector(self, vector):
        """translationを除いたlinear partだけをvectorへ適用。"""
        x, y = _require_integer_point_exact(vector, 2, "affine vector")
        return (self.a * x + self.b * y, self.c * x + self.d * y)

    def apply_polygon(self, polygon):
        """point列を同じ順序で変換したtuple。O(N)。"""
        return tuple(self.apply(point) for point in polygon)

    def determinant(self):
        """linear partのsigned determinant。"""
        return self.a * self.d - self.b * self.c

    def det(self):
        """determinantの短いalias。"""
        return self.determinant()

    def signed_area2_scale(self):
        """signed area2の倍率。determinantと同値。"""
        return self.determinant()

    def area2_scale(self):
        """absolute area2の非負倍率 ``abs(det)``。"""
        return abs(self.determinant())

    @staticmethod
    def compose(after, before):
        """``after(before(point))`` を表す変換を返す。O(1)。"""
        if not isinstance(after, Affine2Exact) or not isinstance(
            before, Affine2Exact
        ):
            raise TypeError("affine composition requires Affine2Exact operands")
        return Affine2Exact(
            after.a * before.a + after.b * before.c,
            after.a * before.b + after.b * before.d,
            after.c * before.a + after.d * before.c,
            after.c * before.b + after.d * before.d,
            after.a * before.tx + after.b * before.ty + after.tx,
            after.c * before.tx + after.d * before.ty + after.ty,
        )

    def then(self, after):
        """self適用後にafterを適用するcompose shortcut。"""
        return Affine2Exact.compose(after, self)

    def power(self, exponent):
        """非負整数回の反復合成。O(log exponent)。"""
        _require_integer_value_exact(exponent, "affine exponent")
        if exponent < 0:
            raise ValueError("Affine2Exact.power requires a nonnegative exponent")
        result = Affine2Exact.identity()
        base = self
        while exponent:
            if exponent & 1:
                result = Affine2Exact.compose(base, result)
            base = Affine2Exact.compose(base, base)
            exponent >>= 1
        return result

    def __matmul__(self, before):
        """``after @ before`` はcompose(after,before)。"""
        return Affine2Exact.compose(self, before)

    def __repr__(self):
        return f"Affine2Exact{self.coefficients()!r}"


def affine2_compose_exact(after, before):
    """``after(before(point))``。Affine2Exact.composeの関数版。"""
    return Affine2Exact.compose(after, before)


# ==================================================
# Fraction-free determinants / exact predicates
# ==================================================

def determinant_bareiss(matrix):
    """正方整数行列のdeterminantをfraction-free Bareiss法で返す。

    row pivoting込みO(N^3) bigint演算、空行列det=1。途中除算は常にexactで
    Fraction/SymPyを生成しない。
    """
    values = [list(row) for row in matrix]
    size = len(values)
    if any(len(row) != size for row in values):
        raise ValueError("determinant requires a square matrix")
    for row_index, row in enumerate(values):
        for column_index, value in enumerate(row):
            _require_integer_value_exact(
                value, f"matrix[{row_index}][{column_index}]"
            )
    if size == 0:
        return 1
    sign_value = 1
    previous_pivot = 1
    for column in range(size - 1):
        pivot_row = column
        while pivot_row < size and values[pivot_row][column] == 0:
            pivot_row += 1
        if pivot_row == size:
            return 0
        if pivot_row != column:
            values[column], values[pivot_row] = values[pivot_row], values[column]
            sign_value = -sign_value
        pivot = values[column][column]
        for row in range(column + 1, size):
            row_factor = values[row][column]
            for next_column in range(column + 1, size):
                numerator = (
                    values[row][next_column] * pivot
                    - row_factor * values[column][next_column]
                )
                if previous_pivot != 1:
                    numerator //= previous_pivot
                values[row][next_column] = numerator
            values[row][column] = 0
        previous_pivot = pivot
    return sign_value * values[-1][-1]


def orient_nd_exact(points):
    """d次元d+1点のsigned ``d! * volume``。O(d^3) Bareiss exact。"""
    points = [tuple(point) for point in points]
    if not points:
        raise ValueError("orient_nd_exact requires d+1 points")
    dimension = len(points[0])
    if len(points) != dimension + 1:
        raise ValueError("d-dimensional orientation requires d+1 points")
    if any(len(point) != dimension for point in points):
        raise ValueError("orientation points must share one dimension")
    origin = points[0]
    matrix = [
        [point[axis] - origin[axis] for axis in range(dimension)]
        for point in points[1:]
    ]
    return determinant_bareiss(matrix)


def incircle_determinant_exact(a, b, c, point):
    """2D in-circle 4x4 raw determinant。orientation補正なし。"""
    return determinant_bareiss([
        [vertex[0], vertex[1], norm2(vertex), 1]
        for vertex in (a, b, c, point)
    ])


def incircle_exact(a, b, c, point):
    """triangle向きに依存しないcircumcircle relationの符号付き値。

    非退化triangleで正=inside、0=on、負=outside、退化triangleは0。返り値は±1に
    丸めず、向きを補正した行列式の値そのもの（96 や -160 など）なので、
    ``> 0`` / ``< 0`` / ``== 0`` で判定する。向き補正前の値はincircle_determinant_exact。
    """
    a = _require_integer_point_exact(a, 2, "triangle a")
    b = _require_integer_point_exact(b, 2, "triangle b")
    c = _require_integer_point_exact(c, 2, "triangle c")
    point = _require_integer_point_exact(point, 2, "query point")
    triangle_orientation = orientation(a, b, c)
    if triangle_orientation == 0:
        return 0
    return triangle_orientation * incircle_determinant_exact(a, b, c, point)


def insphere3d_determinant_exact(a, b, c, d, point):
    """3D in-sphere 5x5 raw determinant。orientation補正なし。"""
    return determinant_bareiss([
        [vertex[0], vertex[1], vertex[2], norm2_3d(vertex), 1]
        for vertex in (a, b, c, d, point)
    ])


def insphere3d_exact(a, b, c, d, point):
    """tetrahedron向きに依存しないcircumsphere relationの符号付き値。

    非退化tetrahedronで正=inside、0=on、負=outside、退化時は0。返り値は±1に
    丸めず、向きを補正した行列式の値そのものなので ``> 0`` などで判定する。
    向き補正前の値はinsphere3d_determinant_exact。
    """
    a = _require_integer_point_exact(a, 3, "tetrahedron a")
    b = _require_integer_point_exact(b, 3, "tetrahedron b")
    c = _require_integer_point_exact(c, 3, "tetrahedron c")
    d = _require_integer_point_exact(d, 3, "tetrahedron d")
    point = _require_integer_point_exact(point, 3, "query point")
    tetrahedron_orientation = sign(orient3d(a, b, c, d))
    if tetrahedron_orientation == 0:
        return 0
    return -tetrahedron_orientation * insphere3d_determinant_exact(
        a, b, c, d, point
    )


# ==================================================
# Exact spherical directions / minor great-circle arcs
# ==================================================

class SphericalDirectionExact(tuple):
    """原点からのoriented rayをprimitive整数3-vectorでcanonical化する。

    正倍率だけを同一視し、antipodeは別方向。zero vectorは拒否する。
    """

    __slots__ = ()

    def __new__(cls, x, y=None, z=None):
        if y is None and z is None:
            x, y, z = x
        for value, label in ((x, "x"), (y, "y"), (z, "z")):
            _require_integer_value_exact(value, f"spherical direction {label}")
        gcd = math.gcd(math.gcd(abs(x), abs(y)), abs(z))
        if gcd == 0:
            raise ValueError("spherical direction must be nonzero")
        return tuple.__new__(cls, (x // gcd, y // gcd, z // gcd))

    def antipode(self):
        return SphericalDirectionExact(-self[0], -self[1], -self[2])

    def serialize(self):
        return tuple(self)


class GreatCircleArcExact:
    """非antipodal 2方向を結ぶclosed minor great-circle arc。

    同一endpointはpoint arcとして許す。antipodal endpointではminor arcが一意で
    ないためValueError。contains/intersectionは整数dot/crossだけを使う。
    """

    __slots__ = ("start", "end", "normal", "is_point")

    def __init__(self, start, end):
        self.start = (
            start
            if isinstance(start, SphericalDirectionExact)
            else SphericalDirectionExact(start)
        )
        self.end = (
            end
            if isinstance(end, SphericalDirectionExact)
            else SphericalDirectionExact(end)
        )
        self.is_point = self.start == self.end
        if self.is_point:
            self.normal = (0, 0, 0)
            return
        normal = cross3d(self.start, self.end)
        if normal == (0, 0, 0):
            raise ValueError("antipodal endpoints do not define a unique minor arc")
        self.normal = normal

    def contains(self, direction):
        """directionがclosed minor arc上か。O(1) bigint exact。"""
        direction = (
            direction
            if isinstance(direction, SphericalDirectionExact)
            else SphericalDirectionExact(direction)
        )
        if self.is_point:
            return direction == self.start
        if dot3d(self.normal, direction) != 0:
            return False
        return (
            dot3d(cross3d(self.start, direction), self.normal) >= 0
            and dot3d(cross3d(direction, self.end), self.normal) >= 0
        )

    def intersection_exact(self, other):
        """別minor arcとの ``(NONE/POINT/OVERLAP, directions)``。O(1)。"""
        if not isinstance(other, GreatCircleArcExact):
            other = GreatCircleArcExact(*other)
        if self.is_point:
            if other.contains(self.start):
                return (GEO_SEG_POINT, (self.start,))
            return (GEO_SEG_NONE, ())
        if other.is_point:
            if self.contains(other.start):
                return (GEO_SEG_POINT, (other.start,))
            return (GEO_SEG_NONE, ())

        great_circle_cross = cross3d(self.normal, other.normal)
        if great_circle_cross != (0, 0, 0):
            candidate = SphericalDirectionExact(great_circle_cross)
            common = []
            for direction in (candidate, candidate.antipode()):
                if self.contains(direction) and other.contains(direction):
                    common.append(direction)
            if not common:
                return (GEO_SEG_NONE, ())
            if len(common) == 1:
                return (GEO_SEG_POINT, (common[0],))
            raise ArithmeticError("two minor arcs cannot contain antipodal intersections")

        common = []
        seen = set()
        for direction, opposite in (
            (self.start, other),
            (self.end, other),
            (other.start, self),
            (other.end, self),
        ):
            if direction not in seen and opposite.contains(direction):
                seen.add(direction)
                common.append(direction)
        if not common:
            return (GEO_SEG_NONE, ())
        if len(common) == 1:
            return (GEO_SEG_POINT, (common[0],))
        if len(common) != 2:
            raise ArithmeticError("same-circle minor arc overlap has invalid endpoints")
        return (GEO_SEG_OVERLAP, tuple(sorted(common)))

    def intersection_kind_exact(self, other):
        return self.intersection_exact(other)[0]

    def serialize(self):
        return (tuple(self.start), tuple(self.end))

    def __repr__(self):
        return f"GreatCircleArcExact{self.serialize()!r}"


def great_circle_arc_intersection_exact(first, second):
    """GreatCircleArcExact.intersection_exactの関数版。"""
    if not isinstance(first, GreatCircleArcExact):
        first = GreatCircleArcExact(*first)
    return first.intersection_exact(second)


# ==================================================
# Oriented generalized circles / lines
# ==================================================

class GeneralizedCircleExact:
    """oriented equation ``a(x²+y²)+b*x+c*y+d=0`` のprimitive整数表現。

    coefficient gcdだけを除き符号は保持する。したがって正倍率は同一objectへ
    canonical化され、負倍率は同じzero locusだがeval signが反転する別orientation。
    a!=0はgeneralized circle、a==0かつ(b,c)!=0はline。定数式は拒否する。
    """

    __slots__ = ("a", "b", "c", "d", "kind")

    def __init__(self, a, b, c, d):
        if not all(isinstance(value, int) for value in (a, b, c, d)):
            raise TypeError("GeneralizedCircleExact coefficients must be integers")
        gcd = math.gcd(
            math.gcd(math.gcd(abs(a), abs(b)), abs(c)), abs(d)
        )
        if gcd == 0 or (a == 0 and b == 0 and c == 0):
            raise ValueError("constant equation is not a generalized circle")
        self.a = a // gcd
        self.b = b // gcd
        self.c = c // gcd
        self.d = d // gcd
        self.kind = "CIRCLE" if self.a else "LINE"

    def coefficients(self):
        return (self.a, self.b, self.c, self.d)

    def serialize(self):
        return self.coefficients()

    def evaluate(self, point):
        """整数点でのoriented polynomial値。"""
        x, y = _require_integer_point_exact(point, 2, "evaluation point")
        return self.a * (x * x + y * y) + self.b * x + self.c * y + self.d

    def evaluate_rational_exact(self, point):
        """有理点での値に正分母²を掛けたinteger numerator。符号は同じ。"""
        point = _as_rational_point_key_exact(point)
        x_num, y_num, denominator = point
        return (
            self.a * (x_num * x_num + y_num * y_num)
            + self.b * x_num * denominator
            + self.c * y_num * denominator
            + self.d * denominator * denominator
        )

    def sign_at(self, point):
        if isinstance(point, RationalPointKey) or len(point) == 3:
            return sign(self.evaluate_rational_exact(point))
        return sign(self.evaluate(point))

    def translated(self, dx, dy):
        """zero locusを(dx,dy)だけ平行移動する。つまりG(x,y)=F(x-dx,y-dy)。"""
        if not isinstance(dx, int) or not isinstance(dy, int):
            raise TypeError("exact translation requires integer offsets")
        return GeneralizedCircleExact(
            self.a,
            self.b - 2 * self.a * dx,
            self.c - 2 * self.a * dy,
            self.a * (dx * dx + dy * dy)
            - self.b * dx
            - self.c * dy
            + self.d,
        )

    def translate(self, dx, dy):
        """translatedの短いalias。"""
        return self.translated(dx, dy)

    def invert_exact(self, power=1):
        """原点中心 ``p -> power*p/|p|²`` によるimage equation。

        powerは非zero整数。結果係数は ``(d,b*k,c*k,a*k²)``。原点通過円は
        lineへ、lineは原点通過円へ移り、oriented signは正因子を除き保存される。
        """
        if not isinstance(power, int) or power == 0:
            raise ValueError("inversion power must be a nonzero integer")
        return GeneralizedCircleExact(
            self.d,
            self.b * power,
            self.c * power,
            self.a * power * power,
        )

    def same_locus(self, other):
        """orientationを無視して同じzero locusか。"""
        if not isinstance(other, GeneralizedCircleExact):
            other = GeneralizedCircleExact(*other)
        coefficients = self.coefficients()
        other_coefficients = other.coefficients()
        return (
            coefficients == other_coefficients
            or coefficients == tuple(-value for value in other_coefficients)
        )

    def orientation_scale_to(self, other):
        """同orientationなら1、逆なら-1、異なるlocusならNone。"""
        if not isinstance(other, GeneralizedCircleExact):
            other = GeneralizedCircleExact(*other)
        if self.coefficients() == other.coefficients():
            return 1
        if self.coefficients() == tuple(-value for value in other.coefficients()):
            return -1
        return None

    def __eq__(self, other):
        if not isinstance(other, GeneralizedCircleExact):
            return NotImplemented
        return self.coefficients() == other.coefficients()

    def __hash__(self):
        return hash(self.coefficients())

    def __repr__(self):
        return f"GeneralizedCircleExact{self.coefficients()!r}"


# ==================================================
# Exact oriented polygon moments
# ==================================================

GEO_MOMENTS_OK = "OK"
GEO_MOMENTS_ZERO_AREA = "ZERO_AREA"


class PolygonMomentsExact:
    """oriented integer ringsのarea/centroid/second moments accumulator。

    CCW outerは正、CW holeは負としてそのまま加算する。内部では整数和だけを
    保持し、area・centroid・原点/重心まわり二次momentを既約分数で返す。
    ``origin_second_moments_exact`` の順は ``(∫x²dA, ∫y²dA, ∫xy dA)``。
    """

    __slots__ = (
        "area2", "_centroid_x_sum", "_centroid_y_sum",
        "_moment_xx_sum", "_moment_yy_sum", "_moment_xy_sum",
    )

    def __init__(self, rings=()):
        self.area2 = 0
        self._centroid_x_sum = 0
        self._centroid_y_sum = 0
        self._moment_xx_sum = 0
        self._moment_yy_sum = 0
        self._moment_xy_sum = 0
        for ring in rings:
            self.add_ring(ring)

    @classmethod
    def from_outer_holes(cls, outer, holes=()):
        """outerをCCW、holesをCWへ補正してaccumulateする。O(total vertices)。"""
        result = cls()
        outer = list(outer)
        if polygon_area2(outer) < 0:
            outer.reverse()
        result.add_ring(outer)
        for hole in holes:
            hole = list(hole)
            if polygon_area2(hole) > 0:
                hole.reverse()
            result.add_ring(hole)
        return result

    @property
    def status(self):
        return GEO_MOMENTS_OK if self.area2 != 0 else GEO_MOMENTS_ZERO_AREA

    def add_ring(self, ring, weight=1):
        """oriented ringをinteger weight倍して加算。O(V)。"""
        _require_integer_value_exact(weight, "ring weight")
        vertices = list(_require_integer_points_exact(ring, 2, "ring"))
        n = len(vertices)
        if n == 0 or weight == 0:
            return self
        for index in range(n):
            x1, y1 = vertices[index]
            x2, y2 = vertices[(index + 1) % n]
            edge_cross = (x1 * y2 - y1 * x2) * weight
            self.area2 += edge_cross
            self._centroid_x_sum += (x1 + x2) * edge_cross
            self._centroid_y_sum += (y1 + y2) * edge_cross
            self._moment_xx_sum += (
                x1 * x1 + x1 * x2 + x2 * x2
            ) * edge_cross
            self._moment_yy_sum += (
                y1 * y1 + y1 * y2 + y2 * y2
            ) * edge_cross
            self._moment_xy_sum += (
                2 * x1 * y1
                + x1 * y2
                + x2 * y1
                + 2 * x2 * y2
            ) * edge_cross
        return self

    def signed_area_exact(self):
        return fraction_normalize_exact(self.area2, 2)

    def area_exact(self):
        return fraction_normalize_exact(abs(self.area2), 2)

    def centroid_exact(self):
        """``(x_fraction,y_fraction)``。net signed area 0ならNone。"""
        if self.area2 == 0:
            return None
        denominator = 3 * self.area2
        return (
            fraction_normalize_exact(self._centroid_x_sum, denominator),
            fraction_normalize_exact(self._centroid_y_sum, denominator),
        )

    def origin_second_moments_exact(self):
        """signed ``(∫x²dA, ∫y²dA, ∫xy dA)``。"""
        return (
            fraction_normalize_exact(self._moment_xx_sum, 12),
            fraction_normalize_exact(self._moment_yy_sum, 12),
            fraction_normalize_exact(self._moment_xy_sum, 24),
        )

    def centroid_second_moments_exact(self):
        """signed centroidal second moments。zero net areaならNone。"""
        centroid = self.centroid_exact()
        if centroid is None:
            return None
        origin_xx, origin_yy, origin_xy = self.origin_second_moments_exact()
        centroid_x, centroid_y = centroid
        signed_area = self.signed_area_exact()

        def subtract_shift(origin_moment, first_coordinate, second_coordinate):
            shift = _fraction_mul_exact(
                signed_area,
                _fraction_mul_exact(first_coordinate, second_coordinate),
            )
            return _fraction_sub_exact(origin_moment, shift)

        return (
            subtract_shift(origin_xx, centroid_x, centroid_x),
            subtract_shift(origin_yy, centroid_y, centroid_y),
            subtract_shift(origin_xy, centroid_x, centroid_y),
        )

    def summary_exact(self):
        return {
            "status": self.status,
            "signed_area": self.signed_area_exact(),
            "centroid": self.centroid_exact(),
            "origin_second_moments": self.origin_second_moments_exact(),
            "centroid_second_moments": self.centroid_second_moments_exact(),
        }


def convex_diameter2(poly):
    n = len(poly)
    if n <= 1:
        return 0
    if n == 2:
        return dist2(poly[0], poly[1])

    p = normalize_polygon_ccw(poly)
    n = len(p)
    j = 1
    best = 0

    for i in range(n):
        ni = (i + 1) % n
        while True:
            nj = (j + 1) % n
            if cross(sub(p[ni], p[i]), sub(p[nj], p[j])) > 0:
                j = nj
            else:
                break
        best = max(best, dist2(p[i], p[j]))
        best = max(best, dist2(p[ni], p[j]))

    return best


convex_diameter2_i = convex_diameter2


def convex_diameter(poly):
    return math.sqrt(convex_diameter2(poly))


def contains_convex(poly, p):
    n = len(poly)
    if n == 0:
        return 0
    if n == 1:
        return 1 if same_point(poly[0], p) else 0
    if n == 2:
        return 1 if on_segment(poly[0], poly[1], p) else 0

    q = normalize_polygon_ccw(poly)
    p0 = q[0]

    c1 = sign(cross3(p0, q[1], p))
    c2 = sign(cross3(p0, q[-1], p))

    if c1 < 0 or c2 > 0:
        return 0
    if c1 == 0:
        return 1 if on_segment(p0, q[1], p) else 0
    if c2 == 0:
        return 1 if on_segment(p0, q[-1], p) else 0

    left = 1
    right = n - 1
    while right - left > 1:
        mid = (left + right) // 2
        if cross3(p0, q[mid], p) >= 0:
            left = mid
        else:
            right = mid

    c = sign(cross3(q[left], q[left + 1], p))
    if c < 0:
        return 0
    if c == 0:
        return 1
    return 2


contains_convex_i = contains_convex
contains_convex_ccw = contains_convex


def contains_convex_f(poly, p, tol=FLOAT_TOL):
    n = len(poly)
    if n == 0:
        return 0
    if n == 1:
        return 1 if dist2(poly[0], p) <= tol * tol else 0
    if n == 2:
        return 1 if fsign(cross3(poly[0], poly[1], p), tol) == 0 and dot(sub(p, poly[0]), sub(p, poly[1])) <= tol else 0

    q = list(poly)
    if polygon_area2(q) < 0:
        q.reverse()
    p0 = q[0]

    c1 = fsign(cross3(p0, q[1], p), tol)
    c2 = fsign(cross3(p0, q[-1], p), tol)
    if c1 < 0 or c2 > 0:
        return 0
    if c1 == 0:
        return 1 if dot(sub(p, p0), sub(p, q[1])) <= tol else 0
    if c2 == 0:
        return 1 if dot(sub(p, p0), sub(p, q[-1])) <= tol else 0

    left = 1
    right = n - 1
    while right - left > 1:
        mid = (left + right) // 2
        if fsign(cross3(p0, q[mid], p), tol) >= 0:
            left = mid
        else:
            right = mid

    c = fsign(cross3(q[left], q[left + 1], p), tol)
    if c < 0:
        return 0
    if c == 0:
        return 1
    return 2


def convex_cut(poly, a, b, tol=FLOAT_TOL):
    res = []
    n = len(poly)
    for i in range(n):
        p = poly[i]
        q = poly[(i + 1) % n]
        cp = cross3(a, b, p)
        cq = cross3(a, b, q)

        if cp >= -tol:
            res.append(p)

        if (cp > tol and cq < -tol) or (cp < -tol and cq > tol):
            if abs(cp) <= abs(cq):
                t = cp / (cp - cq)
                res.append((p[0] + (q[0] - p[0]) * t, p[1] + (q[1] - p[1]) * t))
            else:
                t = cq / (cq - cp)
                res.append((q[0] + (p[0] - q[0]) * t, q[1] + (p[1] - q[1]) * t))

    out = []
    for p in res:
        if not out or dist2(out[-1], p) > tol * tol:
            out.append(p)
    if len(out) > 1 and dist2(out[0], out[-1]) <= tol * tol:
        out.pop()
    return out


def convex_intersection(poly1, poly2, tol=FLOAT_TOL):
    res = list(poly1)
    clip = list(poly2)
    if not res or not clip:
        return []
    if polygon_area2(res) < 0:
        res.reverse()
    if polygon_area2(clip) < 0:
        clip.reverse()
    for i in range(len(clip)):
        res = convex_cut(res, clip[i], clip[(i + 1) % len(clip)], tol)
        if not res:
            break
    return res


def halfplane_intersection_by_cut(lines, box=10**18):
    """半平面（各 ``(a, c)`` は a から c へ向かう有向直線の左側）の共通部分を返す。

    一辺 ``2*box`` の正方形を各直線で順に切る。結果は反時計回りの頂点列で、空なら ``[]``。
    領域が非有界なら、box の正方形で切られた頂点（座標が ±box）が入る。a と c が同じ点の
    直線は何も制限しない。座標と box がすべて int のときは有理数で厳密に切るので、
    box が大きくても精度は落ちない（頂点は整数なら int、そうでなければ float）。
    float を含むときは許容誤差 1e-12 の float で切るので、box は答えの座標の10倍程度に絞る。
    """
    b = box
    lines = list(lines)
    exact = type(b) is int
    if exact:
        for a, c in lines:
            if not (type(a[0]) is int and type(a[1]) is int and type(c[0]) is int and type(c[1]) is int):
                exact = False
                break
    if not exact:
        poly = [(-b, -b), (b, -b), (b, b), (-b, b)]
        for a, c in lines:
            poly = convex_cut(poly, a, c)
            if not poly:
                break
        return poly
    poly = [(-b, -b, 1), (b, -b, 1), (b, b, 1), (-b, b, 1)]
    for a, c in lines:
        ax, ay = a
        dx = c[0] - ax
        dy = c[1] - ay
        if dx == 0 and dy == 0:
            continue
        n = len(poly)
        s = [dx * (y - ay * w) - dy * (x - ax * w) for x, y, w in poly]
        res = []
        for i in range(n):
            sp = s[i]
            p = poly[i]
            if sp >= 0:
                res.append(p)
            j = i + 1 if i + 1 < n else 0
            sq = s[j]
            if (sp > 0 and sq < 0) or (sp < 0 and sq > 0):
                q = poly[j]
                x = q[0] * sp - p[0] * sq
                y = q[1] * sp - p[1] * sq
                w = sp * q[2] - sq * p[2]
                if w < 0:
                    x, y, w = -x, -y, -w
                g = math.gcd(math.gcd(x, y), w)
                res.append((x // g, y // g, w // g))
        poly = []
        for v in res:
            if not poly or poly[-1] != v:
                poly.append(v)
        if len(poly) > 1 and poly[0] == poly[-1]:
            poly.pop()
        if not poly:
            break
    return [(x, y) if w == 1 else (x / w, y / w) for x, y, w in poly]


# ==================================================
# Closest pair
# ==================================================

def closest_pair_dist2(points):
    pts = sorted(points)
    n = len(pts)
    if n < 2:
        return INF

    tmp = [None] * n

    def rec(l, r):
        if r - l <= 1:
            return INF

        m = (l + r) // 2
        mid_x = pts[m][0]
        d = min(rec(l, m), rec(m, r))

        i = l
        j = m
        k = l
        while i < m and j < r:
            if pts[i][1] <= pts[j][1]:
                tmp[k] = pts[i]
                i += 1
            else:
                tmp[k] = pts[j]
                j += 1
            k += 1
        while i < m:
            tmp[k] = pts[i]
            i += 1
            k += 1
        while j < r:
            tmp[k] = pts[j]
            j += 1
            k += 1
        pts[l:r] = tmp[l:r]

        strip = []
        for i in range(l, r):
            p = pts[i]
            dx = p[0] - mid_x
            if dx * dx >= d:
                continue
            for q in reversed(strip):
                dy = p[1] - q[1]
                if dy * dy >= d:
                    break
                dd = dist2(p, q)
                if dd < d:
                    d = dd
            strip.append(p)
        return d

    return rec(0, n)


def closest_pair_dist(points):
    return math.sqrt(closest_pair_dist2(points))


# ==================================================
# Triangle
# ==================================================

def triangle_area2(a, b, c):
    return abs(cross3(a, b, c))


def triangle_area(a, b, c):
    return triangle_area2(a, b, c) / 2.0


def triangle_perimeter(a, b, c):
    return dist(a, b) + dist(b, c) + dist(c, a)


def triangle_centroid(a, b, c):
    return ((a[0] + b[0] + c[0]) / 3.0, (a[1] + b[1] + c[1]) / 3.0)


def triangle_side_lengths(a, b, c):
    return (dist(b, c), dist(c, a), dist(a, b))


def triangle_side_lengths2(a, b, c):
    return (dist2(b, c), dist2(c, a), dist2(a, b))


def is_valid_triangle(a, b, c, strict=True):
    area2 = abs(cross3(a, b, c))
    if strict:
        return area2 > 0
    return area2 >= 0


def contains_triangle(a, b, c, p):
    if abs(cross3(a, b, c)) == 0:
        if on_segment(a, b, p) or on_segment(b, c, p) or on_segment(c, a, p):
            return 1
        return 0

    s1 = sign(cross3(a, b, p))
    s2 = sign(cross3(b, c, p))
    s3 = sign(cross3(c, a, p))
    has_pos = s1 > 0 or s2 > 0 or s3 > 0
    has_neg = s1 < 0 or s2 < 0 or s3 < 0
    if has_pos and has_neg:
        return 0
    if s1 == 0 or s2 == 0 or s3 == 0:
        return 1
    return 2


def point_in_triangle_exact(p, a, b, c):
    """整数三角形のconvex hullに対するpの位置を厳密に返す。

    ``GEO_OUT=0, GEO_BOUNDARY=1, GEO_IN=2``。3頂点が共線・重複する
    場合のhullは線分または点なので内部は存在せず、hull上だけBOUNDARY。
    O(1) bigint演算。
    """
    p = _require_integer_point_exact(p, 2, "query point")
    a = _require_integer_point_exact(a, 2, "triangle a")
    b = _require_integer_point_exact(b, 2, "triangle b")
    c = _require_integer_point_exact(c, 2, "triangle c")
    area = cross3(a, b, c)
    if area == 0:
        low = min(a, b, c)
        high = max(a, b, c)
        return GEO_BOUNDARY if on_segment(low, high, p) else GEO_OUT

    s1 = cross3(a, b, p)
    s2 = cross3(b, c, p)
    s3 = cross3(c, a, p)
    has_positive = s1 > 0 or s2 > 0 or s3 > 0
    has_negative = s1 < 0 or s2 < 0 or s3 < 0
    if has_positive and has_negative:
        return GEO_OUT
    if s1 == 0 or s2 == 0 or s3 == 0:
        return GEO_BOUNDARY
    return GEO_IN


def triangle_angle_type(a, b, c):
    if not is_valid_triangle(a, b, c):
        return "degenerate"
    x, y, z = sorted(triangle_side_lengths2(a, b, c))
    if z == x + y:
        return "right"
    if z < x + y:
        return "acute"
    return "obtuse"


def circumcenter(a, b, c):
    """3点 a, b, c の外心 ``(x, y)``（float）。一直線上（面積が0に近い）なら None。

    a を原点に取り直して計算するので、座標が大きくても三角形が小さければ精度が落ちない。
    一直線の判定は外積の絶対値が ``FLOAT_TOL * min(1, 最長辺の2乗)`` 以下かで行い、
    座標の単位が小さい三角形も外心が求まる。
    """
    ax, ay = a
    bx = b[0] - ax
    by = b[1] - ay
    cx = c[0] - ax
    cy = c[1] - ay
    d = 2.0 * (bx * cy - by * cx)
    bb = bx * bx + by * by
    cc = cx * cx + cy * cy
    ee = (bx - cx) * (bx - cx) + (by - cy) * (by - cy)
    m = max(bb, cc, ee)
    if abs(d) <= FLOAT_TOL * (m if m < 1.0 else 1.0):
        return None
    return (ax + (cy * bb - by * cc) / d, ay + (bx * cc - cx * bb) / d)


def incenter(a, b, c):
    la = dist(b, c)
    lb = dist(c, a)
    lc = dist(a, b)
    s = la + lb + lc
    if s == 0:
        return (float(a[0]), float(a[1]))
    return ((la * a[0] + lb * b[0] + lc * c[0]) / s, (la * a[1] + lb * b[1] + lc * c[1]) / s)


def triangle_circumcircle(a, b, c):
    o = circumcenter(a, b, c)
    if o is None:
        return None
    return (o, dist(o, a))


def triangle_incircle(a, b, c):
    area2 = abs(cross3(a, b, c))
    if area2 == 0:
        return None
    la = dist(b, c)
    lb = dist(c, a)
    lc = dist(a, b)
    s = la + lb + lc
    if s == 0:
        return None
    center = ((la * a[0] + lb * b[0] + lc * c[0]) / s, (la * a[1] + lb * b[1] + lc * c[1]) / s)
    radius = area2 / s
    return (center, radius)


def triangle_orthocenter(a, b, c):
    o = circumcenter(a, b, c)
    if o is None:
        return None
    return (a[0] + b[0] + c[0] - 2.0 * o[0], a[1] + b[1] + c[1] - 2.0 * o[1])


def triangle_altitudes(a, b, c):
    area2 = abs(cross3(a, b, c))
    la = dist(b, c)
    lb = dist(c, a)
    lc = dist(a, b)
    ha = area2 / la if la != 0 else 0.0
    hb = area2 / lb if lb != 0 else 0.0
    hc = area2 / lc if lc != 0 else 0.0
    return (ha, hb, hc)


def count_points_in_triangle(points, a, b, c, include_boundary=True):
    cnt = 0
    for p in points:
        res = contains_triangle(a, b, c, p)
        if include_boundary:
            if res > 0:
                cnt += 1
        else:
            if res == 2:
                cnt += 1
    return cnt


def min_perimeter_triangle_bruteforce(points):
    pts = list(points)
    n = len(pts)
    if n < 3:
        return (INF, None)
    best = INF
    best_tri = None
    for i in range(n):
        for j in range(i + 1, n):
            dij = dist(pts[i], pts[j])
            for k in range(j + 1, n):
                per = dij + dist(pts[j], pts[k]) + dist(pts[k], pts[i])
                if per < best:
                    best = per
                    best_tri = (pts[i], pts[j], pts[k])
    return (best, best_tri)


def min_area_triangle_bruteforce(points):
    pts = list(points)
    n = len(pts)
    best2 = None
    best_tri = None
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                a2 = abs(cross3(pts[i], pts[j], pts[k]))
                if a2 > 0 and (best2 is None or a2 < best2):
                    best2 = a2
                    best_tri = (pts[i], pts[j], pts[k])
    if best2 is None:
        return (INF, None)
    return (best2 / 2.0, best_tri)


# ==================================================
# Quadrilateral / Rectangle
# ==================================================

def sort_points_around_centroid(points):
    pts = list(points)
    n = len(pts)
    if n == 0:
        return []
    sx = sum(p[0] for p in pts)
    sy = sum(p[1] for p in pts)

    def cmp_p(p, q):
        vp = (p[0] * n - sx, p[1] * n - sy)
        vq = (q[0] * n - sx, q[1] * n - sy)
        return polar_cmp(vp, vq)

    pts.sort(key=cmp_to_key(cmp_p))
    if len(pts) >= 3 and polygon_area2(pts) < 0:
        pts.reverse()
    return pts


def order_quad(points):
    pts = sort_points_around_centroid(points)
    if len(pts) != 4:
        raise ValueError("order_quad requires exactly 4 points")
    return pts


def quad_area2(a, b, c, d):
    return abs(polygon_area2([a, b, c, d]))


def quad_area(a, b, c, d):
    return quad_area2(a, b, c, d) / 2.0


def quad_perimeter(a, b, c, d):
    return polygon_perimeter([a, b, c, d])


def is_convex_quad(q, strict=True):
    return len(q) == 4 and is_convex(q, strict=strict)


def is_parallelogram_quad(q):
    return len(q) == 4 and add(q[0], q[2]) == add(q[1], q[3])


def is_rectangle_quad(q):
    return is_parallelogram_quad(q) and dot(sub(q[1], q[0]), sub(q[2], q[1])) == 0


def is_rhombus_quad(q):
    if not is_parallelogram_quad(q):
        return False
    d0 = dist2(q[0], q[1])
    d1 = dist2(q[1], q[2])
    d2 = dist2(q[2], q[3])
    d3 = dist2(q[3], q[0])
    return d0 == d1 == d2 == d3


def is_square_quad(q):
    return is_rectangle_quad(q) and is_rhombus_quad(q)


def is_trapezoid_quad(q):
    if len(q) != 4:
        return False
    return is_parallel(q[0], q[1], q[2], q[3]) or is_parallel(q[1], q[2], q[3], q[0])


def is_kite_quad(q):
    if len(q) != 4:
        return False
    d0 = dist2(q[0], q[1])
    d1 = dist2(q[1], q[2])
    d2 = dist2(q[2], q[3])
    d3 = dist2(q[3], q[0])
    return (d0 == d1 and d2 == d3) or (d1 == d2 and d3 == d0)


def classify_quadrilateral(points, already_ordered=False):
    if len(points) != 4:
        return "not_quadrilateral"
    q = list(points) if already_ordered else order_quad(points)
    if len(set(q)) != 4:
        return "concave_or_degenerate"
    if not is_convex_quad(q, strict=True):
        return "concave_or_degenerate"
    if is_square_quad(q):
        return "square"
    if is_rectangle_quad(q):
        return "rectangle"
    if is_rhombus_quad(q):
        return "rhombus"
    if is_parallelogram_quad(q):
        return "parallelogram"
    if is_kite_quad(q):
        return "kite"
    if is_trapezoid_quad(q):
        return "trapezoid"
    return "convex_quadrilateral"


def rectangle_vertices(center, width, height, theta=0.0):
    cx, cy = center
    c = math.cos(theta)
    s = math.sin(theta)
    ux, uy = c, s
    vx, vy = -s, c
    hw = width / 2.0
    hh = height / 2.0
    return [
        (cx - ux * hw - vx * hh, cy - uy * hw - vy * hh),
        (cx + ux * hw - vx * hh, cy + uy * hw - vy * hh),
        (cx + ux * hw + vx * hh, cy + uy * hw + vy * hh),
        (cx - ux * hw + vx * hh, cy - uy * hw + vy * hh),
    ]


def contains_rectangle(rect, p):
    return contains_convex_f(rect, p)


def count_points_in_rectangle(points, rect, include_boundary=True):
    cnt = 0
    for p in points:
        res = contains_rectangle(rect, p)
        if include_boundary:
            if res > 0:
                cnt += 1
        else:
            if res == 2:
                cnt += 1
    return cnt


# ==================================================
# Axis-aligned bounding box
# ==================================================

def bounding_box(points):
    pts = list(points)
    if not pts:
        return None
    min_x = min(p[0] for p in pts)
    max_x = max(p[0] for p in pts)
    min_y = min(p[1] for p in pts)
    max_y = max(p[1] for p in pts)
    return (min_x, min_y, max_x, max_y)


def bbox_width_height(points):
    box = bounding_box(points)
    if box is None:
        return (0, 0)
    min_x, min_y, max_x, max_y = box
    return (max_x - min_x, max_y - min_y)


def bbox_area(points):
    w, h = bbox_width_height(points)
    return w * h


def bbox_perimeter(points):
    w, h = bbox_width_height(points)
    if w == 0 and h == 0:
        return 0
    return 2 * (w + h)


def bbox_contains(box, p, include_boundary=True):
    min_x, min_y, max_x, max_y = box
    x, y = p
    if include_boundary:
        return min_x <= x <= max_x and min_y <= y <= max_y
    return min_x < x < max_x and min_y < y < max_y


def count_points_in_bbox(points, box, include_boundary=True):
    cnt = 0
    for p in points:
        if bbox_contains(box, p, include_boundary):
            cnt += 1
    return cnt


def can_cover_by_axis_aligned_rectangle(points, width, height, allow_swap=True):
    w, h = bbox_width_height(points)
    if w <= width and h <= height:
        return True
    if allow_swap and w <= height and h <= width:
        return True
    return False


# ==================================================
# Circle
# ==================================================

GEO_CIRCLE_COINCIDENT = "COINCIDENT"
GEO_CIRCLE_DISJOINT_EXTERNAL = "DISJOINT_EXTERNAL"
GEO_CIRCLE_TANGENT_EXTERNAL = "TANGENT_EXTERNAL"
GEO_CIRCLE_INTERSECT_2 = "INTERSECT_2"
GEO_CIRCLE_TANGENT_INTERNAL = "TANGENT_INTERNAL"
GEO_CIRCLE_CONTAINED = "CONTAINED"


def circle_relation_exact(c1, r1, c2, r2):
    """整数中心・非負整数半径の2円をEPS/sqrtなしで厳密分類する。

    COINCIDENT / DISJOINT_EXTERNAL / TANGENT_EXTERNAL / INTERSECT_2 /
    TANGENT_INTERNAL / CONTAINED のいずれか。O(1) bigint演算。
    """
    c1 = _require_integer_point_exact(c1, 2, "first circle center")
    c2 = _require_integer_point_exact(c2, 2, "second circle center")
    _require_integer_value_exact(r1, "first circle radius")
    _require_integer_value_exact(r2, "second circle radius")
    if r1 < 0 or r2 < 0:
        raise ValueError("circle radius must be non-negative")
    distance2 = dist2(c1, c2)
    if distance2 == 0 and r1 == r2:
        return GEO_CIRCLE_COINCIDENT
    sum2 = (r1 + r2) * (r1 + r2)
    difference2 = (r1 - r2) * (r1 - r2)
    if distance2 > sum2:
        return GEO_CIRCLE_DISJOINT_EXTERNAL
    if distance2 == sum2:
        return GEO_CIRCLE_TANGENT_EXTERNAL
    if distance2 < difference2:
        return GEO_CIRCLE_CONTAINED
    if distance2 == difference2:
        return GEO_CIRCLE_TANGENT_INTERNAL
    return GEO_CIRCLE_INTERSECT_2


def circle_circle_intersection_kind_exact(c1, r1, c2, r2):
    """circle_relation_exactの明示的なcircle-circle別名。"""
    return circle_relation_exact(c1, r1, c2, r2)


def circle_circle_intersection_count_exact(c1, r1, c2, r2):
    """2円周の相異なる共有点数。正半径の同一円は無限を表す-1。

    同じzero-circleは集合として1点なので1。O(1) bigint演算。
    """
    kind = circle_relation_exact(c1, r1, c2, r2)
    if kind == GEO_CIRCLE_COINCIDENT:
        return 1 if r1 == 0 else -1
    if kind in (GEO_CIRCLE_TANGENT_EXTERNAL, GEO_CIRCLE_TANGENT_INTERNAL):
        return 1
    if kind == GEO_CIRCLE_INTERSECT_2:
        return 2
    return 0


def circle_line_intersection_count_exact(c, radius, a, b):
    """整数円周と非退化整数無限直線の共有点数0/1/2。a==bならNone。

    ``cross²`` と ``r²*|b-a|²`` の比較だけを使う。O(1) bigint演算。
    """
    c = _require_integer_point_exact(c, 2, "circle center")
    a = _require_integer_point_exact(a, 2, "line start")
    b = _require_integer_point_exact(b, 2, "line end")
    _require_integer_value_exact(radius, "circle radius")
    if radius < 0:
        raise ValueError("circle radius must be non-negative")
    vx = b[0] - a[0]
    vy = b[1] - a[1]
    length2 = vx * vx + vy * vy
    if length2 == 0:
        return None
    area = vx * (c[1] - a[1]) - vy * (c[0] - a[0])
    left = area * area
    right = radius * radius * length2
    if left > right:
        return 0
    if left == right:
        return 1
    return 2


def point_circle_tangent_count_exact(c, radius, p):
    """整数点pから整数円へ引ける相異なる接線数。

    正半径は内0/円周1/外2。zero-circleはp==cで無数(-1)、それ以外は
    両点を通る1直線、と明示的に定義する。O(1) bigint演算。
    """
    c = _require_integer_point_exact(c, 2, "circle center")
    p = _require_integer_point_exact(p, 2, "query point")
    _require_integer_value_exact(radius, "circle radius")
    if radius < 0:
        raise ValueError("circle radius must be non-negative")
    distance2 = dist2(c, p)
    if radius == 0:
        return -1 if distance2 == 0 else 1
    radius2 = radius * radius
    if distance2 < radius2:
        return 0
    if distance2 == radius2:
        return 1
    return 2


def common_tangent_family_counts_exact(c1, r1, c2, r2):
    """``(direct_family, transverse_family)`` の接線本数を厳密に返す。

    両方が同じ正円なら各family無限を表す(-1,-1)。zero-circleでは2familyが
    同じ幾何直線を表し得るため、相異なる直線総数には
    common_tangent_count_exactを使う。O(1) bigint演算。
    """
    c1 = _require_integer_point_exact(c1, 2, "first circle center")
    c2 = _require_integer_point_exact(c2, 2, "second circle center")
    _require_integer_value_exact(r1, "first circle radius")
    _require_integer_value_exact(r2, "second circle radius")
    if r1 < 0 or r2 < 0:
        raise ValueError("circle radius must be non-negative")
    distance2 = dist2(c1, c2)
    if distance2 == 0 and r1 == r2 and r1 > 0:
        return (-1, -1)
    difference2 = (r1 - r2) * (r1 - r2)
    sum2 = (r1 + r2) * (r1 + r2)
    direct = 0 if distance2 < difference2 else (1 if distance2 == difference2 else 2)
    transverse = 0 if distance2 < sum2 else (1 if distance2 == sum2 else 2)
    return (direct, transverse)


def common_tangent_count_exact(c1, r1, c2, r2):
    """2円の相異なる共通接線数。同一正円は-1。O(1) bigint演算。

    zero-circle同士は同一点なら-1、異なる点なら両点を通る1直線。
    一方だけzeroなら、その中心点から他方の円への接線数0/1/2。
    """
    c1 = _require_integer_point_exact(c1, 2, "first circle center")
    c2 = _require_integer_point_exact(c2, 2, "second circle center")
    _require_integer_value_exact(r1, "first circle radius")
    _require_integer_value_exact(r2, "second circle radius")
    if r1 < 0 or r2 < 0:
        raise ValueError("circle radius must be non-negative")
    if r1 == 0 and r2 == 0:
        return -1 if c1 == c2 else 1
    if r1 == 0:
        return point_circle_tangent_count_exact(c2, r2, c1)
    if r2 == 0:
        return point_circle_tangent_count_exact(c1, r1, c2)
    direct, transverse = common_tangent_family_counts_exact(c1, r1, c2, r2)
    if direct == -1:
        return -1
    return direct + transverse


GEO_APPROX_INVALID = "INVALID"
GEO_APPROX_NONE = "NONE"
GEO_APPROX_TANGENT = "TANGENT"
GEO_APPROX_TWO_POINTS = "TWO_POINTS"
GEO_APPROX_INFINITE = "INFINITE"


class CircleConstructionApprox(tuple):
    """exact topology tag/countと最終出力用float pointsの組。

    tuple内容は ``(kind, count, points)``。count=-1は無限、Noneはinvalid。
    points数は有限countと必ず一致し、EPSによるdedupを行わない。
    """

    __slots__ = ()

    def __new__(cls, kind, count, points=()):
        return tuple.__new__(cls, (kind, count, tuple(points)))

    @property
    def kind(self):
        return self[0]

    @property
    def count(self):
        return self[1]

    @property
    def points(self):
        return self[2]


def circle_line_intersections_tagged_approx(c, radius, a, b):
    """exact個数で分岐後、円周×無限直線のfloat交点を構成する。

    2点時はdirected line a->bの正方向側、負方向側の順。topologyは
    circle_line_intersection_count_exactだけで決め、EPS dedupしない。
    """
    count = circle_line_intersection_count_exact(c, radius, a, b)
    if count is None:
        return CircleConstructionApprox(GEO_APPROX_INVALID, None)
    if count == 0:
        return CircleConstructionApprox(GEO_APPROX_NONE, 0)
    direction = sub(b, a)
    length2 = norm2(direction)
    parameter_num = dot(sub(c, a), direction)
    foot = (
        a[0] + direction[0] * parameter_num / length2,
        a[1] + direction[1] * parameter_num / length2,
    )
    if count == 1:
        return CircleConstructionApprox(GEO_APPROX_TANGENT, 1, (foot,))
    area = cross(direction, sub(c, a))
    height_numerator = radius * radius * length2 - area * area
    coefficient = math.sqrt(height_numerator) / length2
    first = add(foot, mul(direction, coefficient))
    second = sub(foot, mul(direction, coefficient))
    return CircleConstructionApprox(
        GEO_APPROX_TWO_POINTS, 2, (first, second)
    )


def circle_circle_intersections_tagged_approx(c1, r1, c2, r2):
    """exact relation/countで分岐後、2円周のfloat交点を構成する。

    2点時はdirected center c1->c2の左側、右側の順。COINCIDENT正円は
    count=-1・points空。同一zero-circleはその中心1点。EPS dedupなし。
    """
    kind = circle_relation_exact(c1, r1, c2, r2)
    count = circle_circle_intersection_count_exact(c1, r1, c2, r2)
    if count == -1:
        return CircleConstructionApprox(kind, -1)
    if count == 0:
        return CircleConstructionApprox(kind, 0)
    if kind == GEO_CIRCLE_COINCIDENT:
        return CircleConstructionApprox(
            kind, 1, ((float(c1[0]), float(c1[1])),)
        )
    direction = sub(c2, c1)
    distance2 = norm2(direction)
    along_numerator = r1 * r1 - r2 * r2 + distance2
    base = (
        c1[0] + direction[0] * along_numerator / (2 * distance2),
        c1[1] + direction[1] * along_numerator / (2 * distance2),
    )
    if count == 1:
        return CircleConstructionApprox(kind, 1, (base,))
    discriminant = 4 * r1 * r1 * distance2 - along_numerator * along_numerator
    coefficient = math.sqrt(discriminant) / (2 * distance2)
    normal = rotate90(direction)
    first = add(base, mul(normal, coefficient))
    second = sub(base, mul(normal, coefficient))
    return CircleConstructionApprox(kind, 2, (first, second))


def tangent_points_from_point_tagged_approx(c, radius, point):
    """exact個数で分岐後、pointから円へのfloat接点を構成する。

    2点時はdirected vector c->pointの左法線寄り、右法線寄りの順。
    zero-circleも既存exact契約に従い、異なるpointからは中心1点、同一点なら
    count=-1とする。EPS dedupなし。
    """
    count = point_circle_tangent_count_exact(c, radius, point)
    if count == -1:
        return CircleConstructionApprox(GEO_APPROX_INFINITE, -1)
    if count == 0:
        return CircleConstructionApprox(GEO_APPROX_NONE, 0)
    if radius == 0:
        center = (float(c[0]), float(c[1]))
        return CircleConstructionApprox(GEO_APPROX_TANGENT, 1, (center,))
    if count == 1:
        return CircleConstructionApprox(
            GEO_APPROX_TANGENT,
            1,
            ((float(point[0]), float(point[1])),),
        )
    vector = sub(point, c)
    distance2 = norm2(vector)
    radius2 = radius * radius
    base = add(c, mul(vector, radius2 / distance2))
    coefficient = radius * math.sqrt(distance2 - radius2) / distance2
    normal = rotate90(vector)
    first = add(base, mul(normal, coefficient))
    second = sub(base, mul(normal, coefficient))
    return CircleConstructionApprox(
        GEO_APPROX_TWO_POINTS, 2, (first, second)
    )

def circle_line_intersections(c, r, a, b):
    if same_point(a, b):
        return []
    p = projection(a, b, c)
    d2 = dist2(p, c)
    r2 = r * r
    if d2 > r2 + FLOAT_TOL:
        return []
    if abs(d2 - r2) <= FLOAT_TOL:
        return [p]
    h = math.sqrt(max(0.0, r2 - d2))
    v = unit(sub(b, a))
    return [add(p, mul(v, h)), sub(p, mul(v, h))]


def circle_segment_intersections(c, r, a, b):
    if same_point(a, b):
        if abs(dist2(a, c) - r * r) <= FLOAT_TOL:
            return [(float(a[0]), float(a[1]))]
        return []
    res = []
    for p in circle_line_intersections(c, r, a, b):
        if dist2(p, a) <= dist2(a, b) + FLOAT_TOL and dist2(p, b) <= dist2(a, b) + FLOAT_TOL:
            res.append(p)
    return res


def circle_circle_relation(c1, r1, c2, r2):
    d = dist(c1, c2)
    if d <= FLOAT_TOL and abs(r1 - r2) <= FLOAT_TOL:
        return -1
    if d > r1 + r2 + FLOAT_TOL:
        return 4
    if abs(d - (r1 + r2)) <= FLOAT_TOL:
        return 3
    if d + min(r1, r2) < max(r1, r2) - FLOAT_TOL:
        return 0
    if abs(d + min(r1, r2) - max(r1, r2)) <= FLOAT_TOL:
        return 1
    return 2


def circle_circle_intersections(c1, r1, c2, r2):
    d = dist(c1, c2)
    if d <= FLOAT_TOL:
        return []
    if d > r1 + r2 + FLOAT_TOL:
        return []
    if d < abs(r1 - r2) - FLOAT_TOL:
        return []
    a = (r1 * r1 - r2 * r2 + d * d) / (2.0 * d)
    h2 = r1 * r1 - a * a
    if h2 < -FLOAT_TOL:
        return []
    v = div(sub(c2, c1), d)
    p = add(c1, mul(v, a))
    if abs(h2) <= FLOAT_TOL:
        return [p]
    h = math.sqrt(max(0.0, h2))
    nv = rotate90(v)
    return [add(p, mul(nv, h)), sub(p, mul(nv, h))]


def circle_circle_intersection_area(c1, r1, c2, r2):
    d = dist(c1, c2)
    if d >= r1 + r2 - FLOAT_TOL:
        return 0.0
    if d <= abs(r1 - r2) + FLOAT_TOL:
        r = min(r1, r2)
        return math.pi * r * r
    a = math.acos(clamp((d * d + r1 * r1 - r2 * r2) / (2.0 * d * r1), -1.0, 1.0))
    b = math.acos(clamp((d * d + r2 * r2 - r1 * r1) / (2.0 * d * r2), -1.0, 1.0))
    return r1 * r1 * a + r2 * r2 * b - d * r1 * math.sin(a)


def tangent_points_from_point(c, r, p):
    v = sub(p, c)
    d2 = norm2(v)
    r2 = r * r
    if d2 < r2 - FLOAT_TOL:
        return []
    if abs(d2 - r2) <= FLOAT_TOL:
        return [p]
    base = add(c, mul(v, r2 / d2))
    if r == 0:
        return [base]
    h = r * math.sqrt(max(0.0, d2 - r2)) / d2
    pv = rotate90(v)
    return [add(base, mul(pv, h)), sub(base, mul(pv, h))]


def common_tangents(c1, r1, c2, r2):
    res = []
    dx = c2[0] - c1[0]
    dy = c2[1] - c1[1]
    z = dx * dx + dy * dy
    if z <= FLOAT_TOL:
        return res

    for s in (-1, 1):
        rr = r1 - s * r2
        h2 = z - rr * rr
        if h2 < -FLOAT_TOL:
            continue
        h = math.sqrt(max(0.0, h2))
        for sign2 in (-1, 1):
            nx = (dx * rr - dy * h * sign2) / z
            ny = (dy * rr + dx * h * sign2) / z
            p1 = (c1[0] + r1 * nx, c1[1] + r1 * ny)
            p2 = (c2[0] + s * r2 * nx, c2[1] + s * r2 * ny)
            res.append((p1, p2))
            if h <= FLOAT_TOL:
                break
    if r1 <= FLOAT_TOL or r2 <= FLOAT_TOL:
        tolerance = 1e-18 * (1.0 + z)
        unique = []
        for tangent in res:
            for other in unique:
                if dist2(tangent[0], other[0]) <= tolerance and dist2(tangent[1], other[1]) <= tolerance:
                    break
            else:
                unique.append(tangent)
        res = unique
    return res


def circle_polygon_intersection_area(c, r, poly):
    def sector_area(a, b):
        return r * r * math.atan2(cross(a, b), dot(a, b)) / 2.0

    def segment_circle_params(a, b):
        d = sub(b, a)
        A = norm2(d)
        B = 2.0 * dot(a, d)
        C = norm2(a) - r * r
        D = B * B - 4.0 * A * C
        if A <= FLOAT_TOL or D <= FLOAT_TOL:
            return None
        sq = math.sqrt(max(0.0, D))
        t1 = (-B - sq) / (2.0 * A)
        t2 = (-B + sq) / (2.0 * A)
        res = []
        if FLOAT_TOL < t1 < 1.0 - FLOAT_TOL:
            res.append(t1)
        if FLOAT_TOL < t2 < 1.0 - FLOAT_TOL:
            res.append(t2)
        return res

    total = 0.0
    n = len(poly)
    for i in range(n):
        a = sub(poly[i], c)
        b = sub(poly[(i + 1) % n], c)
        ts = segment_circle_params(a, b)
        if ts is None:
            if norm2(a) <= r * r + FLOAT_TOL and norm2(b) <= r * r + FLOAT_TOL:
                total += cross(a, b) / 2.0
            else:
                total += sector_area(a, b)
            continue
        pts = [a]
        d = sub(b, a)
        for t in sorted(ts):
            pts.append(add(a, mul(d, t)))
        pts.append(b)
        for j in range(len(pts) - 1):
            p = pts[j]
            q = pts[j + 1]
            mid = mul(add(p, q), 0.5)
            if norm2(mid) <= r * r + FLOAT_TOL:
                total += cross(p, q) / 2.0
            else:
                total += sector_area(p, q)
    return abs(total)


def in_circle(c, r, p):
    return dist2(c, p) <= (r + FLOAT_TOL) * (r + FLOAT_TOL)


def in_circle2(c, r2, p, include_boundary=True):
    d2 = dist2(c, p)
    if include_boundary:
        return d2 <= r2
    return d2 < r2


def count_points_in_circle(points, center, radius, include_boundary=True):
    r2 = radius * radius
    cnt = 0
    for p in points:
        d2 = dist2(center, p)
        if include_boundary:
            if d2 <= r2 + FLOAT_TOL:
                cnt += 1
        else:
            if d2 < r2 - FLOAT_TOL:
                cnt += 1
    return cnt


def count_points_in_circle2(points, center, radius2, include_boundary=True):
    cnt = 0
    for p in points:
        if in_circle2(center, radius2, p, include_boundary):
            cnt += 1
    return cnt


def circle_from2(a, b):
    c = div(add(a, b), 2.0)
    r = dist(a, b) / 2.0
    return (c, r)


def circle_from3(a, b, c):
    o = circumcenter(a, b, c)
    if o is None:
        return None
    return (o, dist(o, a))


def circle_from3_safe(a, b, c):
    res = circle_from3(a, b, c)
    if res is not None:
        return res
    best = circle_from2(a, b)
    for cand in (circle_from2(b, c), circle_from2(c, a)):
        if cand[1] > best[1]:
            best = cand
    return best


_MEC_RNG = random.Random(20240601)

def minimum_enclosing_circle(points):
    """点集合を囲む最小の円（最小包含円）を返す。乱択の逐次構成（Welzl 法の反復版）、期待 O(N)。

    同じ座標の点は最初に 1 つにまとめ、最初の点を原点に平行移動してから計算する
    （座標が 10^9 でも、点どうしの距離に対する相対誤差で判定する）。
    「円の中」の判定は 距離 <= r + 1e-10 × (点の広がり) で、結果の円は全点を
    この程度の誤差の範囲で含む（整数座標 10^9 なら 0.2 程度の絶対誤差、半径に対して 1e-10 程度）。

    引数: points = [(x, y), ...]
    返り値: ((cx, cy), r)（float）。点が空なら ((0.0, 0.0), 0.0)、1 点なら半径 0.0。
    計算量: 期待 O(N)。PyPy で N = 2×10^5 が約 0.2 秒（重複を除く分、以前より 0.1 秒ほど遅い）。

    使用例:
        >>> minimum_enclosing_circle([(0, 0), (2, 0), (1, 1)])
        ((1.0, 0.0), 1.0)
        >>> minimum_enclosing_circle([(5, 5), (5, 5)])
        ((5.0, 5.0), 0.0)
    """
    pts = list(dict.fromkeys((p[0], p[1]) for p in points))   # 重複を除く（入力の順を保つ）
    if not pts:
        return ((0.0, 0.0), 0.0)
    ox, oy = pts[0]
    P = [(x - ox, y - oy) for x, y in pts]
    _MEC_RNG.shuffle(P)
    S = 0
    for x, y in P:
        if abs(x) > S:
            S = abs(x)
        if abs(y) > S:
            S = abs(y)
    eps = 1e-10 * S
    sqrt = math.sqrt

    def c2(p, q):
        return ((p[0] + q[0]) / 2.0, (p[1] + q[1]) / 2.0,
                sqrt((p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2) / 2.0)

    def c3(p, q, t):
        ax, ay = p
        bx = q[0] - ax
        by = q[1] - ay
        cx = t[0] - ax
        cy = t[1] - ay
        dd = 2 * (bx * cy - by * cx)
        bb = bx * bx + by * by
        cc = cx * cx + cy * cy
        ee = (bx - cx) ** 2 + (by - cy) ** 2
        if dd == 0 or abs(dd) <= 1e-12 * max(bb, cc, ee):
            best = c2(p, q)
            for cand in (c2(q, t), c2(t, p)):
                if cand[2] > best[2]:
                    best = cand
            return best
        ux = (cy * bb - by * cc) / dd
        uy = (bx * cc - cx * bb) / dd
        return (ax + ux, ay + uy, sqrt(ux * ux + uy * uy))

    cx, cy = float(P[0][0]), float(P[0][1])
    r = 0.0
    lim = eps * eps
    for i in range(len(P)):
        p = P[i]
        dx = p[0] - cx
        dy = p[1] - cy
        if dx * dx + dy * dy <= lim:
            continue
        cx, cy, r = float(p[0]), float(p[1]), 0.0
        lim = eps * eps
        for j in range(i):
            q = P[j]
            dx = q[0] - cx
            dy = q[1] - cy
            if dx * dx + dy * dy <= lim:
                continue
            cx, cy, r = c2(p, q)
            lim = (r + eps) * (r + eps)
            for k in range(j):
                t = P[k]
                dx = t[0] - cx
                dy = t[1] - cy
                if dx * dx + dy * dy <= lim:
                    continue
                cx, cy, r = c3(p, q, t)
                lim = (r + eps) * (r + eps)
    return ((cx + ox, cy + oy), r)


def min_enclosing_circle_info(points):
    center, r = minimum_enclosing_circle(points)
    return (center, r, math.pi * r * r, 2.0 * math.pi * r)


def can_cover_by_circle(points, radius):
    center, r = minimum_enclosing_circle(points)
    return r <= radius + FLOAT_TOL


# ==================================================
# Point counting and polygon distances
# ==================================================

def count_points_in_polygon(points, poly, include_boundary=True, convex=False):
    cnt = 0
    if convex:
        for p in points:
            res = contains_convex(poly, p)
            if include_boundary:
                if res > 0:
                    cnt += 1
            else:
                if res == 2:
                    cnt += 1
        return cnt

    for p in points:
        res = contains_polygon(poly, p)
        if include_boundary:
            if res > 0:
                cnt += 1
        else:
            if res == 2:
                cnt += 1
    return cnt


def dist_point_polygon(poly, p):
    if contains_polygon(poly, p) > 0:
        return 0.0
    best = INF
    for a, b in polygon_edges(poly):
        best = min(best, dist_sp(a, b, p))
    return best


def dist_polygon_polygon(poly1, poly2):
    n = len(poly1)
    m = len(poly2)
    if n == 0 or m == 0:
        return INF

    for a, b in polygon_edges(poly1):
        for c, d in polygon_edges(poly2):
            if intersect_ss(a, b, c, d):
                return 0.0

    if contains_polygon(poly1, poly2[0]) > 0:
        return 0.0
    if contains_polygon(poly2, poly1[0]) > 0:
        return 0.0

    best = INF
    for a, b in polygon_edges(poly1):
        for c, d in polygon_edges(poly2):
            best = min(best, dist_ss(a, b, c, d))
    return best


# ==================================================
# Enclosing figures
# ==================================================

def convex_hull_perimeter(points):
    return polygon_perimeter(convex_hull(points))


def convex_hull_area(points):
    return polygon_area(convex_hull(points))


def _advance_max_index(poly, idx, value_func):
    n = len(poly)
    while True:
        nxt = (idx + 1) % n
        if value_func(nxt) > value_func(idx):
            idx = nxt
        else:
            break
    return idx


def _advance_min_index(poly, idx, value_func):
    n = len(poly)
    while True:
        nxt = (idx + 1) % n
        if value_func(nxt) < value_func(idx):
            idx = nxt
        else:
            break
    return idx


def minimum_bounding_rectangle(points, minimize="area"):
    if minimize != "area" and minimize != "perimeter":
        raise ValueError("minimize must be 'area' or 'perimeter'")
    hull = convex_hull(points)
    n = len(hull)

    if n == 0:
        return (0.0, 0.0, 0.0, 0.0, [])
    if n == 1:
        p = hull[0]
        return (0.0, 0.0, 0.0, 0.0, [p, p, p, p])
    if n == 2:
        w = dist(hull[0], hull[1])
        rect = [hull[0], hull[1], hull[1], hull[0]]
        return (0.0, 2.0 * w, w, 0.0, rect)

    hull = normalize_polygon_ccw(hull)
    n = len(hull)
    e0 = sub(hull[1], hull[0])

    imax_dot = max(range(n), key=lambda k: dot(e0, hull[k]))
    imin_dot = min(range(n), key=lambda k: dot(e0, hull[k]))
    imax_crs = max(range(n), key=lambda k: cross(e0, hull[k]))
    imin_crs = min(range(n), key=lambda k: cross(e0, hull[k]))

    best_key = INF
    best = None

    for i in range(n):
        e = sub(hull[(i + 1) % n], hull[i])
        length2 = norm2(e)
        if length2 == 0:
            continue
        length = math.sqrt(length2)

        def f_dot(k):
            return dot(e, hull[k])

        def f_crs(k):
            return cross(e, hull[k])

        imax_dot = _advance_max_index(hull, imax_dot, f_dot)
        imin_dot = _advance_min_index(hull, imin_dot, f_dot)
        imax_crs = _advance_max_index(hull, imax_crs, f_crs)
        imin_crs = _advance_min_index(hull, imin_crs, f_crs)

        min_s = f_dot(imin_dot) / length
        max_s = f_dot(imax_dot) / length
        min_t = f_crs(imin_crs) / length
        max_t = f_crs(imax_crs) / length

        width = max_s - min_s
        height = max_t - min_t
        area = width * height
        perimeter = 2.0 * (width + height)

        key = area if minimize == "area" else perimeter

        if key < best_key:
            best_key = key
            ux = e[0] / length
            uy = e[1] / length
            vx = -uy
            vy = ux

            def make_point(s, t):
                return (ux * s + vx * t, uy * s + vy * t)

            rect = [
                make_point(min_s, min_t),
                make_point(max_s, min_t),
                make_point(max_s, max_t),
                make_point(min_s, max_t),
            ]
            best = (area, perimeter, width, height, rect)

    return best


def minimum_area_enclosing_rectangle(points):
    return minimum_bounding_rectangle(points, minimize="area")


def minimum_perimeter_enclosing_rectangle(points):
    return minimum_bounding_rectangle(points, minimize="perimeter")


def minimum_width(points):
    hull = convex_hull(points)
    n = len(hull)
    if n <= 2:
        return 0.0
    hull = normalize_polygon_ccw(hull)
    n = len(hull)
    j = 1
    best = INF

    for i in range(n):
        e = sub(hull[(i + 1) % n], hull[i])
        length2 = norm2(e)
        if length2 == 0:
            continue
        base = cross(e, hull[i])

        def f(k):
            return cross(e, hull[k])

        j = _advance_max_index(hull, j, f)
        width = (f(j) - base) / math.sqrt(length2)
        if width < best:
            best = width
    return best


def enclosing_summary(points):
    pts = list(points)
    hull = convex_hull(pts)
    cp2 = closest_pair_dist2(pts) if len(pts) >= 2 else INF
    center, radius = minimum_enclosing_circle(pts)
    return {
        "hull": hull,
        "hull_area": polygon_area(hull),
        "hull_perimeter": polygon_perimeter(hull),
        "diameter2": convex_diameter2(hull),
        "closest_pair_dist2": cp2,
        "minimum_width": minimum_width(pts),
        "min_circle": (center, radius),
        "min_area_rect": minimum_area_enclosing_rectangle(pts),
        "min_perimeter_rect": minimum_perimeter_enclosing_rectangle(pts),
        "bbox": bounding_box(pts),
    }


# ==================================================
# Integer / lattice geometry
# ==================================================

def line_coeff(a, b):
    x1, y1 = a
    x2, y2 = b
    A = y1 - y2
    B = x2 - x1
    C = x1 * y2 - x2 * y1
    g = math.gcd(math.gcd(abs(A), abs(B)), abs(C))
    if g:
        A //= g
        B //= g
        C //= g
    if A < 0 or (A == 0 and B < 0) or (A == 0 and B == 0 and C < 0):
        A = -A
        B = -B
        C = -C
    return (A, B, C)


line_coeff_i = line_coeff
line_coeff_int = line_coeff


def direction(a, b, directed=False):
    dx = b[0] - a[0]
    dy = b[1] - a[1]
    g = math.gcd(abs(dx), abs(dy))
    if g:
        dx //= g
        dy //= g
    if not directed:
        if dx < 0 or (dx == 0 and dy < 0):
            dx = -dx
            dy = -dy
    return (dx, dy)


direction_i = direction
direction_int = direction


def lattice_points_on_segment(a, b):
    return math.gcd(abs(a[0] - b[0]), abs(a[1] - b[1])) + 1


# ==================================================
# Manhattan geometry
# ==================================================

def transform45(p):
    x, y = p
    return (x + y, x - y)


def max_manhattan_dist(points):
    pts = list(points)
    if not pts:
        return 0
    vals1 = [x + y for x, y in pts]
    vals2 = [x - y for x, y in pts]
    return max(max(vals1) - min(vals1), max(vals2) - min(vals2))


# ==================================================
# Minkowski sum
# ==================================================

def _polygon_lowest_left(poly):
    i = min(range(len(poly)), key=lambda k: (poly[k][1], poly[k][0]))
    return poly[i:] + poly[:i]


def minkowski_sum_convex(poly1, poly2):
    if not poly1 or not poly2:
        return []

    p = convex_hull(poly1)
    q = convex_hull(poly2)

    if len(p) == 1 and len(q) == 1:
        return [add(p[0], q[0])]

    p = _polygon_lowest_left(p)
    q = _polygon_lowest_left(q)

    ep = [sub(p[(i + 1) % len(p)], p[i]) for i in range(len(p))]
    eq = [sub(q[(i + 1) % len(q)], q[i]) for i in range(len(q))]

    res = [add(p[0], q[0])]
    i = 0
    j = 0

    while i < len(ep) or j < len(eq):
        if j == len(eq):
            v = ep[i]
            i += 1
        elif i == len(ep):
            v = eq[j]
            j += 1
        else:
            cr = cross(ep[i], eq[j])
            if cr > 0:
                v = ep[i]
                i += 1
            elif cr < 0:
                v = eq[j]
                j += 1
            else:
                v = add(ep[i], eq[j])
                i += 1
                j += 1
        res.append(add(res[-1], v))

    res.pop()
    return convex_hull(res)


