# Additional compatibility aliases
# ==================================================
polygon_area_abs2_i = polygon_area_abs2
contains_convex_i = contains_convex
boundary_lattice_points_i = boundary_lattice_points
interior_lattice_points_i = interior_lattice_points


# ============================================================
# Ultimate Extension: General Graph Algorithms (0-indexed)
# ============================================================

def _graph_edge_to(edge):
    """隣接リスト要素が頂点番号でも (to, ...) でも行き先を返す。"""
    return edge if isinstance(edge, int) else edge[0]


def bfs_dist(graph, start, goal=None, *, return_prev=False):
    """
    重みなしグラフの最短距離。到達不能は -1。O(V+E)。
    graph[v] は to または (to, ...) のどちらでもよい。
    """
    n = len(graph)
    if not 0 <= start < n:
        raise IndexError(f"start {start} is outside the range [0, {n})")
    dist = [-1] * n
    prev = [-1] * n
    dist[start] = 0
    que = deque([start])
    while que:
        v = que.popleft()
        if v == goal:
            break
        nd = dist[v] + 1
        for edge in graph[v]:
            to = _graph_edge_to(edge)
            if dist[to] < 0:
                dist[to] = nd
                prev[to] = v
                que.append(to)
    return (dist, prev) if return_prev else dist


def multi_source_bfs(graph, starts, *, return_prev=False):
    """複数始点 BFS。各始点の距離を 0 とする。O(V+E)。"""
    n = len(graph)
    dist = [-1] * n
    prev = [-1] * n
    que = deque()
    for s in starts:
        if not 0 <= s < n:
            raise IndexError(f"start {s} is outside the range [0, {n})")
        if dist[s] < 0:
            dist[s] = 0
            que.append(s)
    while que:
        v = que.popleft()
        for edge in graph[v]:
            to = _graph_edge_to(edge)
            if dist[to] < 0:
                dist[to] = dist[v] + 1
                prev[to] = v
                que.append(to)
    return (dist, prev) if return_prev else dist


def restore_path(prev, goal, start=None):
    """
    prev 配列から start→goal を復元する。到達不能なら []。
    start=None では親が -1 の頂点まで遡るため、到達不能かどうかは判定できない。
    親値が範囲外、整数でない、または親鎖が循環している場合は ValueError。
    """
    if not isinstance(goal, int):
        try:
            goal = goal.__index__()
        except AttributeError:
            raise TypeError("goal must be an integer") from None
    if not (0 <= goal < len(prev)):
        return []
    path = []
    seen = set()
    v = goal
    while v != -1:
        if not isinstance(v, int):
            try:
                v = v.__index__()
            except AttributeError:
                raise ValueError("predecessors must be -1 or valid vertex indices") from None
        if not 0 <= v < len(prev):
            raise ValueError("predecessors must be -1 or valid vertex indices")
        if v in seen:
            raise ValueError("the predecessor chain contains a cycle")
        seen.add(v)
        path.append(v)
        if v == start:
            break
        v = prev[v]
    if start is not None and path[-1] != start:
        return []
    path.reverse()
    return path


def zero_one_bfs(graph, start, goal=None, *, return_prev=False):
    """辺重みが 0/1 の最短路。graph[v] = [(to, cost), ...]。O(V+E)。"""
    n = len(graph)
    if not 0 <= start < n:
        raise IndexError(f"start {start} is outside the range [0, {n})")
    dist = [math.inf] * n
    prev = [-1] * n
    dist[start] = 0
    que = deque([start])
    while que:
        v = que.popleft()
        if v == goal:
            # 古い要素を積まない実装なので、取り出した時点で確定している。
            break
        dv = dist[v]
        for to, cost in graph[v]:
            if cost not in (0, 1):
                raise ValueError("zero_one_bfs requires edge costs 0 or 1")
            nd = dv + cost
            if nd < dist[to]:
                dist[to] = nd
                prev[to] = v
                (que.appendleft if cost == 0 else que.append)(to)
    return (dist, prev) if return_prev else dist


def dijkstra(graph, start, goal=None, *, return_prev=False):
    """
    非負辺重みの単一始点最短路。graph[v] = [(to, cost), ...]。
    到達不能は math.inf。O((V+E) log V)。
    """
    n = len(graph)
    if not 0 <= start < n:
        raise IndexError(f"start {start} is outside the range [0, {n})")
    dist = [math.inf] * n
    prev = [-1] * n
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, v = heappop(pq)
        if d != dist[v]:
            continue
        if v == goal:
            break
        for to, cost in graph[v]:
            if cost < 0:
                raise ValueError("dijkstra requires non-negative edge costs")
            nd = d + cost
            if nd < dist[to]:
                dist[to] = nd
                prev[to] = v
                heappush(pq, (nd, to))
    return (dist, prev) if return_prev else dist


def multi_source_dijkstra(graph, starts, *, return_prev=False):
    """複数始点 Dijkstra。starts は頂点、または (初期距離, 頂点) の列。"""
    n = len(graph)
    dist = [math.inf] * n
    prev = [-1] * n
    pq = []
    for item in starts:
        if isinstance(item, int):
            d, s = 0, item
        else:
            d, s = item
        if not 0 <= s < n:
            raise IndexError(f"start {s} is outside the range [0, {n})")
        if d < dist[s]:
            dist[s] = d
            heappush(pq, (d, s))
    while pq:
        d, v = heappop(pq)
        if d != dist[v]:
            continue
        for to, cost in graph[v]:
            if cost < 0:
                raise ValueError("multi_source_dijkstra requires non-negative costs")
            nd = d + cost
            if nd < dist[to]:
                dist[to] = nd
                prev[to] = v
                heappush(pq, (nd, to))
    return (dist, prev) if return_prev else dist


def bellman_ford(n, edges, start):
    """
    負辺を許す最短路。edges=(from,to,cost)。O(VE)。
    戻り値 (dist, negative): 負閉路から到達できる頂点は dist=-inf, negative[v]=True。
    edges はジェネレータでもよい（内部で list にする）。
    """
    if not 0 <= start < n:
        raise IndexError(f"start {start} is outside the range [0, {n})")
    if not isinstance(edges, (list, tuple)):
        edges = list(edges)
    dist = [math.inf] * n
    dist[start] = 0
    for _ in range(n - 1):
        updated = False
        for u, v, cost in edges:
            if dist[u] != math.inf and dist[u] + cost < dist[v]:
                dist[v] = dist[u] + cost
                updated = True
        if not updated:
            break
    negative = [False] * n
    for _ in range(n):
        updated = False
        for u, v, cost in edges:
            if dist[u] == math.inf or negative[v]:
                continue
            if negative[u] or dist[u] + cost < dist[v]:
                dist[v] = -math.inf
                negative[v] = True
                updated = True
        if not updated:
            break
    return dist, negative


def warshall_floyd(matrix):
    """
    全点対最短路。matrix[i][j] は辺重み、辺なしは math.inf。O(N^3)。
    入力を破壊せず距離行列を返す。対角が負なら負閉路が存在する。
    """
    dist = [row[:] for row in matrix]
    n = len(dist)
    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == math.inf:
                continue
            di = dist[i]
            for j in range(n):
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd
    return dist


def topological_sort(graph, *, lexicographical=False):
    """DAG のトポロジカル順を返す。閉路があれば []。O(V+E)（辞書順は log V）。"""
    n = len(graph)
    indeg = [0] * n
    for edges in graph:
        for edge in edges:
            indeg[_graph_edge_to(edge)] += 1
    if lexicographical:
        que = [v for v in range(n) if indeg[v] == 0]
        heapq.heapify(que)
        pop, push = lambda: heappop(que), lambda x: heappush(que, x)
    else:
        que = deque(v for v in range(n) if indeg[v] == 0)
        pop, push = que.popleft, que.append
    order = []
    while que:
        v = pop()
        order.append(v)
        for edge in graph[v]:
            to = _graph_edge_to(edge)
            indeg[to] -= 1
            if indeg[to] == 0:
                push(to)
    return order if len(order) == n else []


class SCC:
    """強連結成分分解（反復 Kosaraju）。成分番号は縮約 DAG のトポロジカル順。"""

    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.reverse_graph = [[] for _ in range(n)]
        self.ids = None
        self.group_count = 0

    def add_edge(self, u, v):
        adj_u = self.graph[u]
        adj_v = self.reverse_graph[v]
        if u < 0 or v < 0:
            raise IndexError(f"vertex out of range [0, {self.n})")
        adj_u.append(v)
        adj_v.append(u)
        self.ids = None

    def build(self):
        n, graph = self.n, self.graph
        seen = [False] * n
        order = []
        for root in range(n):
            if seen[root]:
                continue
            seen[root] = True
            stack = [(root, 0)]
            while stack:
                v, i = stack[-1]
                if i < len(graph[v]):
                    to = graph[v][i]
                    stack[-1] = (v, i + 1)
                    if not seen[to]:
                        seen[to] = True
                        stack.append((to, 0))
                else:
                    order.append(v)
                    stack.pop()

        ids = [-1] * n
        group_count = 0
        for root in reversed(order):
            if ids[root] != -1:
                continue
            ids[root] = group_count
            stack = [root]
            while stack:
                v = stack.pop()
                for to in self.reverse_graph[v]:
                    if ids[to] == -1:
                        ids[to] = group_count
                        stack.append(to)
            group_count += 1
        self.ids = ids
        self.group_count = group_count
        return group_count, ids

    def groups(self):
        if self.ids is None:
            self.build()
        result = [[] for _ in range(self.group_count)]
        for v, cid in enumerate(self.ids):
            result[cid].append(v)
        return result

    def dag(self, *, deduplicate=True):
        if self.ids is None:
            self.build()
        dag = [set() if deduplicate else [] for _ in range(self.group_count)]
        for v in range(self.n):
            cv = self.ids[v]
            for to in self.graph[v]:
                ct = self.ids[to]
                if cv != ct:
                    dag[cv].add(ct) if deduplicate else dag[cv].append(ct)
        return [sorted(edges) if deduplicate else edges for edges in dag]


class TwoSAT:
    """2-SAT。add_clause(i,f,j,g) は (x_i==f) OR (x_j==g) を追加する。
    変数番号は 0..n-1（範囲外は IndexError）。条件を追加すると前回の答えは破棄され、
    satisfiable() / values() は次の呼び出しで計算し直す。"""

    def __init__(self, n):
        self.n = n
        self.scc = SCC(2 * n)
        self.answer = None
        self._sat = None

    @staticmethod
    def _literal(i, value):
        return 2 * i + int(bool(value))

    def add_clause(self, i, value_i, j, value_j):
        a = self._literal(i, value_i)
        b = self._literal(j, value_j)
        self.scc.add_edge(a ^ 1, b)
        self.scc.add_edge(b ^ 1, a)
        self.answer = None
        self._sat = None

    def add_implication(self, i, value_i, j, value_j):
        """(x_i==value_i) => (x_j==value_j)。"""
        a = self._literal(i, value_i)
        b = self._literal(j, value_j)
        self.scc.add_edge(a, b)
        self.scc.add_edge(b ^ 1, a ^ 1)
        self.answer = None
        self._sat = None

    def set_value(self, i, value):
        self.add_clause(i, value, i, value)

    def satisfiable(self):
        if self._sat is not None:
            return self._sat
        _, ids = self.scc.build()
        answer = [False] * self.n
        for i in range(self.n):
            if ids[2 * i] == ids[2 * i + 1]:
                self.answer = None
                self._sat = False
                return False
            answer[i] = ids[2 * i] < ids[2 * i + 1]
        self.answer = answer
        self._sat = True
        return True

    def values(self):
        if not self.satisfiable():
            return None
        return self.answer[:]


class LowLink:
    """
    無向多重グラフの橋・関節点を反復 DFS で列挙する。O(V+E)。
    bridges は辺 ID、bridge_edges は入力時の (u,v) を返す。
    bridges / articulation / bridge_edges は、未計算または辺の追加後なら参照時に
    自動で build() する。頂点番号は 0..n-1（範囲外は add_edge が IndexError）。
    """

    def __init__(self, n, edges=()):
        self.n = n
        self.edges = []
        self.graph = [[] for _ in range(n)]
        for u, v in edges:
            self.add_edge(u, v)
        self.ord = self.low = None
        self._bridges = []
        self._articulation = []

    def add_edge(self, u, v):
        adj_u = self.graph[u]
        adj_v = self.graph[v]
        if u < 0 or v < 0:
            raise IndexError(f"vertex out of range [0, {self.n})")
        eid = len(self.edges)
        self.edges.append((u, v))
        adj_u.append((v, eid))
        adj_v.append((u, eid))
        self.ord = self.low = None
        return eid

    @property
    def bridges(self):
        """橋の辺 ID（昇順）。未計算・辺追加後なら自動で build() する。"""
        if self.ord is None:
            self.build()
        return self._bridges

    @property
    def articulation(self):
        """関節点（昇順）。未計算・辺追加後なら自動で build() する。"""
        if self.ord is None:
            self.build()
        return self._articulation

    def build(self):
        n = self.n
        order = [-1] * n
        low = [0] * n
        parent = [-1] * n
        parent_edge = [-1] * n
        child_count = [0] * n
        is_articulation = [False] * n
        bridges = []
        timer = 0
        for root in range(n):
            if order[root] != -1:
                continue
            order[root] = low[root] = timer
            timer += 1
            stack = [(root, 0)]
            while stack:
                v, i = stack[-1]
                if i < len(self.graph[v]):
                    to, eid = self.graph[v][i]
                    stack[-1] = (v, i + 1)
                    if eid == parent_edge[v]:
                        continue
                    if order[to] == -1:
                        parent[to] = v
                        parent_edge[to] = eid
                        child_count[v] += 1
                        order[to] = low[to] = timer
                        timer += 1
                        stack.append((to, 0))
                    else:
                        low[v] = min(low[v], order[to])
                else:
                    stack.pop()
                    p = parent[v]
                    if p == -1:
                        is_articulation[v] = child_count[v] >= 2
                    else:
                        low[p] = min(low[p], low[v])
                        if order[p] < low[v]:
                            bridges.append(parent_edge[v])
                        if parent[p] != -1 and order[p] <= low[v]:
                            is_articulation[p] = True
        self.ord, self.low = order, low
        self._bridges = sorted(bridges)
        self._articulation = [v for v in range(n) if is_articulation[v]]
        return self

    @property
    def bridge_edges(self):
        if self.ord is None:
            self.build()
        return [self.edges[eid] for eid in self.bridges]


# Tab 補完で一般グラフ関数をまとめて探すための g_ API。
g_bfs_dist = bfs_dist
g_bfs_multi = multi_source_bfs
g_restore_path = restore_path
g_01bfs = zero_one_bfs
g_dijkstra = dijkstra
g_dijkstra_multi = multi_source_dijkstra
g_bellman_ford = bellman_ford
g_warshall_floyd = warshall_floyd
g_topological_sort = topological_sort


# ============================================================
# Ultimate Extension: Flow / Matching / Eulerian Trail
# ============================================================

class Dinic:
    """
    最大流。add_edge(fr,to,cap) 後に flow(s,t) を呼ぶ。
    一般に O(V^2 E)、二部マッチング等の単位容量ではより高速。
    DFS は反復で書いてあるので、経路が長くても再帰の深さ制限に当たらない。
    頂点番号は 0..n-1。範囲外（負を含む）は IndexError。
    """

    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self._pos = []

    def add_edge(self, fr, to, cap):
        if cap < 0:
            raise ValueError("capacity must be non-negative")
        graph = self.graph
        to_rev = len(graph[fr])
        fr_rev = len(graph[to]) + (fr == to)
        if fr < 0 or to < 0:
            raise IndexError(f"vertex out of range [0, {self.n})")
        edge_id = len(self._pos)
        self._pos.append((fr, to_rev))
        graph[fr].append([to, fr_rev, cap])
        graph[to].append([fr, to_rev, 0])
        return edge_id

    def get_edge(self, edge_id):
        if not 0 <= edge_id < len(self._pos):
            raise IndexError("edge id out of range")
        fr, index = self._pos[edge_id]
        edge = self.graph[fr][index]
        reverse = self.graph[edge[0]][edge[1]]
        return (fr, edge[0], edge[2] + reverse[2], reverse[2])  # from,to,cap,flow

    edge = get_edge

    def edges(self):
        return [self.get_edge(i) for i in range(len(self._pos))]

    def change_edge(self, edge_id, new_cap, new_flow):
        if not 0 <= new_flow <= new_cap:
            raise ValueError("require 0 <= flow <= capacity")
        if not 0 <= edge_id < len(self._pos):
            raise IndexError("edge id out of range")
        fr, index = self._pos[edge_id]
        edge = self.graph[fr][index]
        reverse = self.graph[edge[0]][edge[1]]
        edge[2] = new_cap - new_flow
        reverse[2] = new_flow

    def flow(self, source, sink, flow_limit=None):
        if source == sink:
            raise ValueError("source and sink must differ")
        n, graph = self.n, self.graph
        if not (0 <= source < n and 0 <= sink < n):
            raise IndexError(f"vertex out of range [0, {n})")
        limit = math.inf if flow_limit is None else flow_limit
        total = 0
        while total < limit:
            level = [-1] * n
            level[source] = 0
            que = deque([source])
            while que:
                v = que.popleft()
                nl = level[v] + 1
                for to, rev, cap in graph[v]:
                    if cap > 0 and level[to] < 0:
                        level[to] = nl
                        que.append(to)
            if level[sink] < 0:
                break
            it = [0] * n
            path_e = []
            path_v = [source]
            v = source
            while True:
                if v == sink:
                    f = limit - total
                    for e in path_e:
                        if e[2] < f:
                            f = e[2]
                    for e in path_e:
                        e[2] -= f
                        graph[e[0]][e[1]][2] += f
                    total += f
                    if total >= limit:
                        break
                    k = 0
                    while path_e[k][2]:
                        k += 1
                    del path_e[k:]
                    del path_v[k + 1:]
                    v = path_v[k]
                    continue
                adj = graph[v]
                i = it[v]
                m = len(adj)
                nl = level[v] + 1
                while i < m:
                    e = adj[i]
                    if e[2] > 0 and level[e[0]] == nl:
                        break
                    i += 1
                it[v] = i
                if i < m:
                    path_e.append(e)
                    v = e[0]
                    path_v.append(v)
                elif v == source:
                    break
                else:
                    path_e.pop()
                    path_v.pop()
                    v = path_v[-1]
                    it[v] += 1
        return total

    max_flow = flow

    def min_cut(self, source):
        """flow 後の残余グラフで source 側に残る頂点を bool 配列で返す。"""
        if not 0 <= source < self.n:
            raise IndexError(f"vertex out of range [0, {self.n})")
        visited = [False] * self.n
        visited[source] = True
        stack = [source]
        while stack:
            v = stack.pop()
            for to, rev, cap in self.graph[v]:
                if cap > 0 and not visited[to]:
                    visited[to] = True
                    stack.append(to)
        return visited

    min_cut_reachable = min_cut

    def residual_graph(self, *, include_zero=False):
        """
        現在の残余グラフを graph[v]=[(to,residual_capacity),...] で複製する。
        include_zero=False で容量0の弧を除く。O(V+E)。
        """
        return [[(to, cap) for to, rev, cap in edges if include_zero or cap > 0]
                for edges in self.graph]


MaxFlow = Dinic


class MinCostFlow:
    """
    最小費用流（ポテンシャル + Dijkstra）。負費用辺にも対応、負閉路は不可。
    flow(s,t,limit) -> (実際に流れた量, 最小費用)。
    頂点番号は 0..n-1。範囲外（負を含む）は IndexError。
    """

    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self._pos = []

    def add_edge(self, fr, to, cap, cost):
        if cap < 0:
            raise ValueError("capacity must be non-negative")
        graph = self.graph
        to_rev = len(graph[fr])
        fr_rev = len(graph[to]) + (fr == to)
        if fr < 0 or to < 0:
            raise IndexError(f"vertex out of range [0, {self.n})")
        edge_id = len(self._pos)
        self._pos.append((fr, to_rev))
        graph[fr].append([to, fr_rev, cap, cost])
        graph[to].append([fr, to_rev, 0, -cost])
        return edge_id

    def get_edge(self, edge_id):
        if not 0 <= edge_id < len(self._pos):
            raise IndexError("edge id out of range")
        fr, index = self._pos[edge_id]
        edge = self.graph[fr][index]
        reverse = self.graph[edge[0]][edge[1]]
        return (fr, edge[0], edge[2] + reverse[2], reverse[2], edge[3])

    def edges(self):
        return [self.get_edge(i) for i in range(len(self._pos))]

    def _initial_potential(self, source):
        n, graph = self.n, self.graph
        if not any(cap > 0 and cost < 0 for edges in graph for to, rev, cap, cost in edges):
            return [0] * n
        dist = [math.inf] * n
        in_queue = [False] * n
        path_length = [0] * n
        dist[source] = 0
        que = deque([source])
        in_queue[source] = True
        while que:
            v = que.popleft()
            in_queue[v] = False
            for to, rev, cap, cost in graph[v]:
                if cap <= 0 or dist[v] + cost >= dist[to]:
                    continue
                dist[to] = dist[v] + cost
                path_length[to] = path_length[v] + 1
                if path_length[to] >= n:
                    raise ValueError("reachable negative-cost cycle")
                if not in_queue[to]:
                    in_queue[to] = True
                    que.append(to)
        return [0 if d == math.inf else d for d in dist]

    def flow(self, source, sink, flow_limit=None):
        if source == sink:
            raise ValueError("source and sink must differ")
        n, graph = self.n, self.graph
        if not (0 <= source < n and 0 <= sink < n):
            raise IndexError(f"vertex out of range [0, {n})")
        limit = math.inf if flow_limit is None else flow_limit
        potential = self._initial_potential(source)
        total_flow = total_cost = 0
        while total_flow < limit:
            dist = [math.inf] * n
            prev_v = [-1] * n
            prev_e = [-1] * n
            dist[source] = 0
            pq = [(0, source)]
            while pq:
                d, v = heappop(pq)
                if d != dist[v]:
                    continue
                for i, edge in enumerate(graph[v]):
                    to, rev, cap, cost = edge
                    if cap <= 0:
                        continue
                    nd = d + cost + potential[v] - potential[to]
                    if nd < dist[to]:
                        dist[to] = nd
                        prev_v[to] = v
                        prev_e[to] = i
                        heappush(pq, (nd, to))
            if dist[sink] == math.inf:
                break
            for v in range(n):
                if dist[v] != math.inf:
                    potential[v] += dist[v]
            add_flow = limit - total_flow
            v = sink
            while v != source:
                pv, pe = prev_v[v], prev_e[v]
                add_flow = min(add_flow, graph[pv][pe][2])
                v = pv
            unit_cost = potential[sink] - potential[source]
            total_flow += add_flow
            total_cost += add_flow * unit_cost
            v = sink
            while v != source:
                pv, pe = prev_v[v], prev_e[v]
                edge = graph[pv][pe]
                edge[2] -= add_flow
                graph[v][edge[1]][2] += add_flow
                v = pv
        return total_flow, total_cost

    min_cost_flow = flow


class LowerBoundFlow:
    """
    辺流量 lower <= flow <= upper を持つ circulation / s-t 最大流。
    add_edge 後、feasible_circulation() または max_flow(s,t) を呼ぶ。
    """

    def __init__(self, n):
        self.n = n
        self.edges = []

    def add_edge(self, fr, to, lower, upper):
        if not 0 <= lower <= upper:
            raise ValueError("require 0 <= lower <= upper")
        if not (0 <= fr < self.n and 0 <= to < self.n):
            raise IndexError(f"vertex out of range [0, {self.n})")
        self.edges.append((fr, to, lower, upper))
        return len(self.edges) - 1

    def _build(self, source=None, sink=None):
        n = self.n
        super_source, super_sink = n, n + 1
        network = Dinic(n + 2)
        balance = [0] * n
        edge_ids = []
        upper_sum = 0
        for fr, to, lower, upper in self.edges:
            edge_ids.append(network.add_edge(fr, to, upper - lower))
            balance[fr] -= lower
            balance[to] += lower
            upper_sum += upper
        extra_id = None
        if source is not None:
            if sink is None or source == sink:
                raise ValueError("source and sink must be distinct")
            extra_id = network.add_edge(sink, source, upper_sum + 1)
        required = 0
        auxiliary_ids = []
        for v, value in enumerate(balance):
            if value > 0:
                auxiliary_ids.append(network.add_edge(super_source, v, value))
                required += value
            elif value < 0:
                auxiliary_ids.append(network.add_edge(v, super_sink, -value))
        feasible = network.flow(super_source, super_sink) == required
        return network, edge_ids, extra_id, auxiliary_ids, feasible

    def _original_flows(self, network, edge_ids):
        return [lower + network.get_edge(edge_id)[3]
                for edge_id, (fr, to, lower, upper) in zip(edge_ids, self.edges)]

    def feasible_circulation(self):
        """実行可能なら (True, edge_flows)、不可能なら (False, None)。"""
        network, edge_ids, extra_id, auxiliary_ids, feasible = self._build()
        if not feasible:
            return False, None
        return True, self._original_flows(network, edge_ids)

    def feasible_flow(self, source, sink):
        """非負値の実行可能 s-t flow を1つ返す。(ok, value, edge_flows)。"""
        network, edge_ids, extra_id, auxiliary_ids, feasible = self._build(source, sink)
        if not feasible:
            return False, None, None
        value = network.get_edge(extra_id)[3]
        return True, value, self._original_flows(network, edge_ids)

    def max_flow(self, source, sink):
        """下限制約付き s-t 最大流。(maximum_value, edge_flows)。不可能なら (None,None)。"""
        network, edge_ids, extra_id, auxiliary_ids, feasible = self._build(source, sink)
        if not feasible:
            return None, None
        base_flow = network.get_edge(extra_id)[3]
        # 超始点・超終点と t->s 補助辺を残余グラフから完全に除く。
        for edge_id in auxiliary_ids + [extra_id]:
            fr, index = network._pos[edge_id]
            edge = network.graph[fr][index]
            reverse = network.graph[edge[0]][edge[1]]
            edge[2] = reverse[2] = 0
        additional = network.flow(source, sink)
        return base_flow + additional, self._original_flows(network, edge_ids)


class HopcroftKarp:
    """二部グラフ最大マッチング。左 0..L-1、右 0..R-1。O(E sqrt(V))。
    add_edge は番号が範囲外（負を含む）なら IndexError。
    max_matching は呼ぶたびに現在のマッチングを引き継いで増やす。"""

    def __init__(self, left_size, right_size):
        if left_size < 0 or right_size < 0:
            raise ValueError("left_size and right_size must be non-negative")
        self.left_size = left_size
        self.right_size = right_size
        self.graph = [[] for _ in range(left_size)]
        self.match_left = [-1] * left_size
        self.match_right = [-1] * right_size

    def add_edge(self, left, right):
        adj = self.graph[left]
        if left < 0 or not 0 <= right < self.right_size:
            raise IndexError("vertex out of range")
        adj.append(right)

    def max_matching(self):
        """最大マッチングの大きさを返す（現在のマッチングを引き継いで増やす）。
        BFS で層を作り、増加路を「各左頂点の辺の走査位置 it[v]」を持つ反復 DFS で探す（再帰を使わない）。
        増加路が長くても PyPy で落ちない（左 i を右 i+1, i の順に結ぶ鎖で増加路の長さが L になる場合も、L = 10^5 で PyPy 約 0.05 秒。
        以前の再帰版は L = 2×10^4 で Segmentation fault。ランダムな L = R = 10^5、E = 3×10^5 で約 1.0 秒 → 約 0.8 秒）。
        計算量 O(E √V)。どの最大マッチングになるかは実装に依存する（大きさは一意）。"""
        L = self.left_size
        graph = self.graph
        match_left = self.match_left
        match_right = self.match_right
        while True:
            dist = [-1] * L
            que = []
            for v in range(L):
                if match_left[v] == -1:
                    dist[v] = 0
                    que.append(v)
            found = False
            head = 0
            while head < len(que):
                v = que[head]
                head += 1
                nd = dist[v] + 1
                for right in graph[v]:
                    to = match_right[right]
                    if to == -1:
                        found = True
                    elif dist[to] == -1:
                        dist[to] = nd
                        que.append(to)
            if not found:
                break
            it = [0] * L
            augmented = False
            for s in range(L):
                if match_left[s] != -1:
                    continue
                stack = [s]
                while stack:
                    v = stack[-1]
                    gv = graph[v]
                    i = it[v]
                    if i < len(gv):
                        to = match_right[gv[i]]
                        if to == -1:
                            # 増加路が見つかった：スタック上の各頂点を「いま見ている辺」の右頂点と組ませる
                            for x in stack:
                                r = graph[x][it[x]]
                                match_left[x] = r
                                match_right[r] = x
                            augmented = True
                            break
                        if dist[to] == dist[v] + 1:
                            stack.append(to)
                        else:
                            it[v] = i + 1
                    else:
                        dist[v] = -1
                        stack.pop()
                        if stack:
                            it[stack[-1]] += 1
            if not augmented:
                break
        return sum(right != -1 for right in match_left)

    def matching_edges(self):
        return [(left, right) for left, right in enumerate(self.match_left) if right != -1]

    def min_vertex_cover(self):
        """Kőnig の定理による最小頂点被覆を (左頂点, 右頂点) で返す。"""
        self.max_matching()
        seen_left = [False] * self.left_size
        seen_right = [False] * self.right_size
        que = deque()
        for left in range(self.left_size):
            if self.match_left[left] == -1:
                seen_left[left] = True
                que.append(left)
        while que:
            left = que.popleft()
            for right in self.graph[left]:
                if self.match_left[left] == right or seen_right[right]:
                    continue
                seen_right[right] = True
                nxt = self.match_right[right]
                if nxt != -1 and not seen_left[nxt]:
                    seen_left[nxt] = True
                    que.append(nxt)
        return ([i for i in range(self.left_size) if not seen_left[i]],
                [i for i in range(self.right_size) if seen_right[i]])


BipartiteMatching = HopcroftKarp


def _g_hierholzer(n, adjacency, edge_count, start, *, return_edges=False):
    used = [False] * edge_count
    index = [0] * n
    vertex_stack = [start]
    edge_stack = []
    path = []
    path_edges = []
    while vertex_stack:
        v = vertex_stack[-1]
        while index[v] < len(adjacency[v]) and used[adjacency[v][index[v]][1]]:
            index[v] += 1
        if index[v] == len(adjacency[v]):
            path.append(vertex_stack.pop())
            if edge_stack:
                path_edges.append(edge_stack.pop())
        else:
            to, eid = adjacency[v][index[v]]
            index[v] += 1
            if not used[eid]:
                used[eid] = True
                vertex_stack.append(to)
                edge_stack.append(eid)
    if len(path_edges) != edge_count:
        return ([], []) if return_edges else []
    path.reverse()
    path_edges.reverse()
    return (path, path_edges) if return_edges else path


def g_eulerian_path_directed(n, edges, start=None, *, return_edges=False):
    """有向グラフの全辺を一度ずつ通る頂点列（存在しなければ []）。O(V+E)。"""
    if n == 0:
        return ([], []) if return_edges else []
    if start is not None and not 0 <= start < n:
        raise IndexError(f"start {start} is outside the range [0, {n})")
    if not isinstance(edges, (list, tuple)):
        edges = list(edges)
    graph = [[] for _ in range(n)]
    indeg = [0] * n
    outdeg = [0] * n
    for eid, (u, v) in enumerate(edges):
        if not (0 <= u < n and 0 <= v < n):
            raise IndexError(f"edge {eid}: vertex out of range [0, {n})")
        graph[u].append((v, eid))
        outdeg[u] += 1
        indeg[v] += 1
    plus = [v for v in range(n) if outdeg[v] - indeg[v] == 1]
    minus = [v for v in range(n) if indeg[v] - outdeg[v] == 1]
    if any(abs(outdeg[v] - indeg[v]) > 1 for v in range(n)) or len(plus) != len(minus) or len(plus) > 1:
        return ([], []) if return_edges else []
    required_start = plus[0] if plus else next((v for v in range(n) if outdeg[v]), 0)
    if start is None:
        start = required_start
    elif edges and (start != required_start if plus else outdeg[start] == 0):
        return ([], []) if return_edges else []
    return _g_hierholzer(n, graph, len(edges), start, return_edges=return_edges)


def g_eulerian_path_undirected(n, edges, start=None, *, return_edges=False):
    """無向グラフの全辺を一度ずつ通る頂点列（存在しなければ []）。O(V+E)。"""
    if n == 0:
        return ([], []) if return_edges else []
    if start is not None and not 0 <= start < n:
        raise IndexError(f"start {start} is outside the range [0, {n})")
    if not isinstance(edges, (list, tuple)):
        edges = list(edges)
    graph = [[] for _ in range(n)]
    degree = [0] * n
    for eid, (u, v) in enumerate(edges):
        if not (0 <= u < n and 0 <= v < n):
            raise IndexError(f"edge {eid}: vertex out of range [0, {n})")
        graph[u].append((v, eid))
        graph[v].append((u, eid))
        degree[u] += 1
        degree[v] += 1
    odd = [v for v in range(n) if degree[v] & 1]
    if len(odd) not in (0, 2):
        return ([], []) if return_edges else []
    required_start = odd[0] if odd else next((v for v in range(n) if degree[v]), 0)
    if start is None:
        start = required_start
    elif edges and (start not in odd if odd else degree[start] == 0):
        return ([], []) if return_edges else []
    return _g_hierholzer(n, graph, len(edges), start, return_edges=return_edges)


# ============================================================
# Ultimate Extension: Advanced General Graph Helpers (g_)
# ============================================================

def g_bipartite_coloring(graph):
    """無向グラフを2彩色し 0/1 配列を返す。二部グラフでなければ None。O(V+E)。"""
    n = len(graph)
    color = [-1] * n
    for root in range(n):
        if color[root] != -1:
            continue
        color[root] = 0
        que = deque([root])
        while que:
            v = que.popleft()
            for edge in graph[v]:
                to = _graph_edge_to(edge)
                if color[to] == -1:
                    color[to] = color[v] ^ 1
                    que.append(to)
                elif color[to] == color[v]:
                    return None
    return color


def g_find_cycle_directed(graph):
    """有向グラフの閉路を [v0,v1,...,v0] で1つ返す。DAG なら []。O(V+E)。"""
    n = len(graph)
    color = [0] * n
    parent = [-1] * n
    for root in range(n):
        if color[root]:
            continue
        color[root] = 1
        stack = [(root, 0)]
        while stack:
            v, i = stack[-1]
            if i == len(graph[v]):
                color[v] = 2
                stack.pop()
                continue
            to = _graph_edge_to(graph[v][i])
            stack[-1] = (v, i + 1)
            if color[to] == 0:
                color[to] = 1
                parent[to] = v
                stack.append((to, 0))
            elif color[to] == 1:
                middle = []
                current = v
                while current != to:
                    middle.append(current)
                    current = parent[current]
                middle.reverse()
                return [to] + middle + [to]
    return []


def g_dag_longest_path(graph, start=None, *, return_prev=False):
    """
    DAG の最長路。edge は to（重み1）または (to,cost)。start=None は全始点距離0。
    閉路があれば ValueError。到達不能は -inf。
    """
    order = topological_sort(graph)
    if len(order) != len(graph):
        raise ValueError("graph is not a DAG")
    n = len(graph)
    dist = [0] * n if start is None else [-math.inf] * n
    prev = [-1] * n
    if start is not None:
        dist[start] = 0
    for v in order:
        if dist[v] == -math.inf:
            continue
        for edge in graph[v]:
            if isinstance(edge, int):
                to, cost = edge, 1
            else:
                to, cost = edge[0], edge[1]
            nd = dist[v] + cost
            if nd > dist[to]:
                dist[to] = nd
                prev[to] = v
    return (dist, prev) if return_prev else dist


def g_steiner_tree(graph, terminals):
    """
    非負重み無向グラフの最小 Steiner tree 重み（Dreyfus-Wagner）。
    K=len(terminals) として O(3^K V + 2^K E log V)。K が小さい場合向け。
    負の重みの辺があれば ValueError、terminals が範囲外なら IndexError。
    """
    terminals = list(dict.fromkeys(terminals))
    k = len(terminals)
    n = len(graph)
    if any(not 0 <= t < n for t in terminals):
        raise IndexError("terminal out of range")
    if any(cost < 0 for edges in graph for _, cost in edges):
        raise ValueError("g_steiner_tree requires non-negative costs")
    if k <= 1:
        return 0
    full = 1 << k
    dp = [[math.inf] * n for _ in range(full)]
    for i, terminal in enumerate(terminals):
        dp[1 << i][terminal] = 0
    for mask in range(1, full):
        sub = (mask - 1) & mask
        while sub:
            other = mask ^ sub
            if sub < other:
                left, right = dp[sub], dp[other]
                current = dp[mask]
                for v in range(n):
                    value = left[v] + right[v]
                    if value < current[v]:
                        current[v] = value
            sub = (sub - 1) & mask
        dist = dp[mask]
        pq = [(value, v) for v, value in enumerate(dist) if value != math.inf]
        heapq.heapify(pq)
        while pq:
            value, v = heappop(pq)
            if value != dist[v]:
                continue
            for to, cost in graph[v]:
                nd = value + cost
                if nd < dist[to]:
                    dist[to] = nd
                    heappush(pq, (nd, to))
    return min(dp[-1])


def _g_maximum_clique_from_masks(adjacency):
    n = len(adjacency)
    best_mask = 0
    best_size = 0

    def greedy_coloring(candidates):
        vertices = []
        bounds = []
        color = 0
        remaining = candidates
        while remaining:
            color += 1
            available = remaining
            while available:
                bit = available & -available
                v = bit.bit_length() - 1
                vertices.append(v)
                bounds.append(color)
                remaining ^= bit
                available ^= bit
                available &= ~adjacency[v]
        return vertices, bounds

    def expand(clique_mask, clique_size, candidates):
        nonlocal best_mask, best_size
        if not candidates:
            if clique_size > best_size:
                best_size = clique_size
                best_mask = clique_mask
            return
        vertices, bounds = greedy_coloring(candidates)
        for i in range(len(vertices) - 1, -1, -1):
            if clique_size + bounds[i] <= best_size:
                return
            v = vertices[i]
            bit = 1 << v
            if not candidates & bit:
                continue
            expand(clique_mask | bit, clique_size + 1, candidates & adjacency[v])
            candidates ^= bit

    expand(0, 0, (1 << n) - 1)
    return [v for v in range(n) if best_mask >> v & 1]


def g_maximum_clique(graph):
    """無向グラフの最大 clique を1つ返す。厳密指数時間（概ね N<=60 程度向け）。"""
    n = len(graph)
    adjacency = [0] * n
    for v in range(n):
        for edge in graph[v]:
            to = _graph_edge_to(edge)
            if to != v:
                adjacency[v] |= 1 << to
                adjacency[to] |= 1 << v
    return _g_maximum_clique_from_masks(adjacency)


def g_maximum_independent_set(graph):
    """無向グラフの最大独立集合を1つ返す。厳密指数時間。"""
    n = len(graph)
    original = [0] * n
    for v in range(n):
        for edge in graph[v]:
            to = _graph_edge_to(edge)
            if to != v:
                original[v] |= 1 << to
                original[to] |= 1 << v
    all_vertices = (1 << n) - 1
    complement = [(all_vertices ^ (1 << v)) & ~original[v] for v in range(n)]
    return _g_maximum_clique_from_masks(complement)


# ============================================================
# Ultimate Extension: Sequence / Static Range Query
# ============================================================

def l_lis_indices(a, *, strict=True):
    """最長増加部分列の index 列を1つ復元する。strict=False は広義増加。O(N log N)。"""
    n = len(a)
    if n == 0:
        return []
    tails = []
    tails_index = []
    previous = [-1] * n
    bsearch = bisect_left if strict else bisect_right
    for i, value in enumerate(a):
        pos = bsearch(tails, value)
        if pos == len(tails):
            tails.append(value)
            tails_index.append(i)
        else:
            tails[pos] = value
            tails_index[pos] = i
        if pos:
            previous[i] = tails_index[pos - 1]
    result = []
    v = tails_index[-1]
    while v != -1:
        result.append(v)
        v = previous[v]
    result.reverse()
    return result


def l_lis_restore(a, *, strict=True):
    """最長増加部分列を値のリストとして1つ返す。O(N log N)。"""
    return [a[i] for i in l_lis_indices(a, strict=strict)]


def l_lis_length(a, *, strict=True):
    """最長増加部分列の長さ。strict=False は最長広義増加部分列。O(N log N)。"""
    tails = []
    bsearch = bisect_left if strict else bisect_right
    for value in a:
        pos = bsearch(tails, value)
        if pos == len(tails):
            tails.append(value)
        else:
            tails[pos] = value
    return len(tails)


def l_inversion_count(a):
    """転倒数 |{(i,j): i<j かつ a[i]>a[j]}|。O(N log N)。"""
    a = list(a)
    values = sorted(set(a))
    bit = BIT(len(values))
    answer = 0
    for i, value in enumerate(a):
        rank = bisect_left(values, value)
        answer += i - bit.prefix_sum(rank + 1)
        bit.add(rank, 1)
    return answer


def _l_nearest_index(a, *, forward, greater, allow_equal):
    n = len(a)
    answer = [-1 if forward else n] * n
    stack = []
    indices = range(n) if forward else range(n - 1, -1, -1)
    for i in indices:
        while stack:
            top = a[stack[-1]]
            if greater:
                invalid = top < a[i] if allow_equal else top <= a[i]
            else:
                invalid = top > a[i] if allow_equal else top >= a[i]
            if not invalid:
                break
            stack.pop()
        if stack:
            answer[i] = stack[-1]
        stack.append(i)
    return answer


def l_next_greater_index(a):
    return _l_nearest_index(a, forward=False, greater=True, allow_equal=False)


def l_next_ge_index(a):
    return _l_nearest_index(a, forward=False, greater=True, allow_equal=True)


def l_next_smaller_index(a):
    return _l_nearest_index(a, forward=False, greater=False, allow_equal=False)


def l_next_le_index(a):
    return _l_nearest_index(a, forward=False, greater=False, allow_equal=True)


def l_prev_greater_index(a):
    return _l_nearest_index(a, forward=True, greater=True, allow_equal=False)


def l_prev_ge_index(a):
    return _l_nearest_index(a, forward=True, greater=True, allow_equal=True)


def l_prev_smaller_index(a):
    return _l_nearest_index(a, forward=True, greater=False, allow_equal=False)


def l_prev_le_index(a):
    return _l_nearest_index(a, forward=True, greater=False, allow_equal=True)


def l_sliding_min(a, width):
    """全ての長さ width の窓の最小値。O(N)。"""
    if not 1 <= width <= len(a):
        return []
    que = deque()
    result = []
    for i, value in enumerate(a):
        while que and a[que[-1]] >= value:
            que.pop()
        que.append(i)
        if que[0] <= i - width:
            que.popleft()
        if i + 1 >= width:
            result.append(a[que[0]])
    return result


def l_sliding_max(a, width):
    """全ての長さ width の窓の最大値。O(N)。"""
    if not 1 <= width <= len(a):
        return []
    que = deque()
    result = []
    for i, value in enumerate(a):
        while que and a[que[-1]] <= value:
            que.pop()
        que.append(i)
        if que[0] <= i - width:
            que.popleft()
        if i + 1 >= width:
            result.append(a[que[0]])
    return result


# 既存関数にも補完しやすい l_ 名を用意する。
l_compress = compress
l_prefix_sum = prefix_sum
l_suffix_sum = suffix_sum
l_flatten = flatten
l_transpose = transpose


def l_rotate90(grid, times=1):
    """2次元 list を時計回りに 90*times 度回転する。元の grid は変更しない。
    各行の長さが揃っていないときは ValueError。"""
    result = [list(row) for row in grid]
    if len({len(row) for row in result}) > 1:
        raise ValueError("all rows of grid must have the same length")
    for _ in range(times % 4):
        result = [list(row) for row in zip(*result[::-1])]
    return result


grid_rotate90 = l_rotate90
grid_transpose = transpose


class WaveletMatrix:
    """
    静的整数列の区間 k-th・頻度・値域和クエリ。任意の符号付き整数に対応。
    構築 O(N log sigma)、各クエリ O(log sigma)、区間は [l,r)（0 始まり）、k も 0 始まり。

    値は座標圧縮してから段に分けるので、段数は log2(異なる値の個数)。
    目安（PyPy）: N = 2×10^5（値の種類 2×10^5、18 段）、kth_smallest・count_less・sum_k_smallest を各 2×10^5 回で
    CPU 約 2.1 秒（旧版とほぼ同じ。段ごとの累積和の配列を毎段 2 か所ランダムに読むキャッシュミスが律速）。構築は約 0.4 秒。
    配列が変わらず「区間内の値 x の個数」だけなら、値ごとの位置リストと bisect の方が軽い。
    値の種類が少ないほど段数（log2(種類数)）が減って速い。
    """

    def __init__(self, data):
        self.data = list(data)
        self.n = n = len(self.data)
        self.values = sorted(set(self.data))
        self.sigma = len(self.values)
        self.log = max(1, (self.sigma - 1).bit_length()) if self.sigma else 0
        ps = [0] * (n + 1)
        s = 0
        for i, value in enumerate(self.data):
            s += value
            ps[i + 1] = s
        self._original_prefix_sum = ps
        self.bit_prefix = []
        self.zero_sum_prefix = []
        self.mid = []
        if not self.sigma:
            return
        rank_of = {value: i for i, value in enumerate(self.values)}
        ranks = [rank_of[value] for value in self.data]
        actual = self.data[:]
        for shift in range(self.log - 1, -1, -1):
            ones = [0] * (n + 1)
            zero_sums = [0] * (n + 1)
            zero_ranks, one_ranks = [], []
            zero_values, one_values = [], []
            o = 0
            z = 0
            for i in range(n):
                rank = ranks[i]
                value = actual[i]
                if rank >> shift & 1:
                    o += 1
                    one_ranks.append(rank)
                    one_values.append(value)
                else:
                    z += value
                    zero_ranks.append(rank)
                    zero_values.append(value)
                ones[i + 1] = o
                zero_sums[i + 1] = z
            self.bit_prefix.append(ones)
            self.zero_sum_prefix.append(zero_sums)
            self.mid.append(len(zero_ranks))
            ranks = zero_ranks + one_ranks
            actual = zero_values + one_values

    def __len__(self):
        return self.n

    def _check_range(self, l, r):
        if not 0 <= l <= r <= self.n:
            raise IndexError("require 0 <= l <= r <= n")

    def access(self, index):
        return self.data[index]

    __getitem__ = access

    def _count_rank_less(self, l, r, rank):
        """a[l:r] で圧縮後の順位が rank 未満の個数（0 < rank < sigma）。"""
        bp = self.bit_prefix
        mid = self.mid
        log = self.log
        answer = 0
        for level in range(log):
            ones = bp[level]
            ones_l = ones[l]
            ones_r = ones[r]
            if rank >> (log - 1 - level) & 1:
                answer += (r - l) - (ones_r - ones_l)
                m = mid[level]
                l = m + ones_l
                r = m + ones_r
            else:
                l -= ones_l
                r -= ones_r
        return answer

    def count_less(self, l, r, upper):
        """a[l:r] にある upper 未満の個数。O(log sigma)。"""
        if not 0 <= l <= r <= self.n:
            raise IndexError("require 0 <= l <= r <= n")
        rank = bisect_left(self.values, upper)
        if rank <= 0:
            return 0
        if rank >= self.sigma:
            return r - l
        return self._count_rank_less(l, r, rank)

    def rank(self, value, l=0, r=None):
        """a[l:r] にある value の個数。"""
        r = self.n if r is None else r
        self._check_range(l, r)
        i = bisect_left(self.values, value)
        if i == self.sigma or self.values[i] != value:
            return 0
        below = self.count_less(l, r, value)
        if i + 1 == self.sigma:
            return r - l - below
        return self.count_less(l, r, self.values[i + 1]) - below

    def range_freq(self, l, r, lower, upper):
        """lower <= a[i] < upper となる i in [l,r) の個数。"""
        if lower >= upper:
            self._check_range(l, r)
            return 0
        return self.count_less(l, r, upper) - self.count_less(l, r, lower)

    def kth_smallest(self, l, r, k):
        """a[l:r] の 0-indexed k 番目に小さい値。O(log sigma)。"""
        if not 0 <= l <= r <= self.n:
            raise IndexError("require 0 <= l <= r <= n")
        if not 0 <= k < r - l:
            raise IndexError("k is out of range")
        bp = self.bit_prefix
        mid = self.mid
        log = self.log
        rank = 0
        for level in range(log):
            ones = bp[level]
            ones_l = ones[l]
            ones_r = ones[r]
            zeros = (r - l) - (ones_r - ones_l)
            if k < zeros:
                l -= ones_l
                r -= ones_r
            else:
                k -= zeros
                rank |= 1 << (log - 1 - level)
                m = mid[level]
                l = m + ones_l
                r = m + ones_r
        return self.values[rank]

    def kth_largest(self, l, r, k):
        """a[l:r] の 0-indexed k 番目に大きい値。O(log sigma)。"""
        return self.kth_smallest(l, r, r - l - 1 - k)

    def sum_less(self, l, r, upper):
        """a[l:r] にある upper 未満の値の総和。O(log sigma)。"""
        if not 0 <= l <= r <= self.n:
            raise IndexError("require 0 <= l <= r <= n")
        rank = bisect_left(self.values, upper)
        if rank <= 0:
            return 0
        if rank >= self.sigma:
            return self._original_prefix_sum[r] - self._original_prefix_sum[l]
        bp = self.bit_prefix
        zp = self.zero_sum_prefix
        mid = self.mid
        log = self.log
        answer = 0
        for level in range(log):
            ones = bp[level]
            ones_l = ones[l]
            ones_r = ones[r]
            if rank >> (log - 1 - level) & 1:
                zero_sum = zp[level]
                answer += zero_sum[r] - zero_sum[l]
                m = mid[level]
                l = m + ones_l
                r = m + ones_r
            else:
                l -= ones_l
                r -= ones_r
        return answer

    def range_sum(self, l, r, lower=-math.inf, upper=math.inf):
        """a[l:r] 内で lower <= value < upper の値の総和。"""
        if lower >= upper:
            self._check_range(l, r)
            return 0
        return self.sum_less(l, r, upper) - self.sum_less(l, r, lower)

    def sum_k_smallest(self, l, r, k):
        """a[l:r] の小さい方から k 個の総和。0 <= k <= r-l。O(log sigma)。"""
        if not 0 <= l <= r <= self.n:
            raise IndexError("require 0 <= l <= r <= n")
        if not 0 <= k <= r - l:
            raise IndexError("k is out of range")
        bp = self.bit_prefix
        zp = self.zero_sum_prefix
        mid = self.mid
        log = self.log
        answer = 0
        rank = 0
        for level in range(log):
            if k == 0:
                break
            ones = bp[level]
            ones_l = ones[l]
            ones_r = ones[r]
            zeros = (r - l) - (ones_r - ones_l)
            if k <= zeros:
                l -= ones_l
                r -= ones_r
            else:
                zero_sum = zp[level]
                answer += zero_sum[r] - zero_sum[l]
                k -= zeros
                rank |= 1 << (log - 1 - level)
                m = mid[level]
                l = m + ones_l
                r = m + ones_r
        if k:
            answer += k * self.values[rank]
        return answer

    def sum_k_largest(self, l, r, k):
        """a[l:r] の大きい方から k 個の総和。0 <= k <= r-l。O(log sigma)。"""
        total = self._original_prefix_sum[r] - self._original_prefix_sum[l]
        return total - self.sum_k_smallest(l, r, r - l - k)

    def prev_value(self, l, r, upper):
        """a[l:r] にある upper 未満の最大値。なければ None。"""
        count = self.count_less(l, r, upper)
        return None if count == 0 else self.kth_smallest(l, r, count - 1)

    def next_value(self, l, r, lower):
        """a[l:r] にある lower 以上の最小値。なければ None。"""
        count = self.count_less(l, r, lower)
        return None if count == r - l else self.kth_smallest(l, r, count)


class XorWaveletMatrix:
    """
    非負 key と payload の静的列。(key xor mask, original_index) 順の
    k-th と先頭 k 件 payload 和を O(bit_length) で返す。

    各 bit の stable partition と branch 別 payload prefix を保持するため、
    同 key の部分取得は元 index 順。構築 O(NB)、メモリ O(NB)。
    制約級のメモリを抑えるため payload 累積和は signed 64-bit で保持する。
    区間 [left, right) と k は 0 始まり。xor_kth は key xor mask の値を返す（元の key ではない）。
    目安（PyPy）: N = 2×10^5、B = 30 で xor_kth と xor_take を各 2×10^5 回が CPU 約 2.5 秒（旧版 2.9 秒。メモリの読み出しが律速）。
    """

    def __init__(self, keys, payload=None, *, bit_length=None):
        self.keys = list(keys)
        self.n = n = len(self.keys)
        if any(key < 0 for key in self.keys):
            raise ValueError("keys must be non-negative")
        self.payload = [1] * self.n if payload is None else list(payload)
        if len(self.payload) != self.n:
            raise ValueError("keys and payload must have equal length")
        required = max(self.keys, default=0).bit_length()
        self.bit_length = max(1, required) if bit_length is None else bit_length
        if self.bit_length <= 0 or required > self.bit_length:
            raise ValueError("bit_length is too small for keys")
        current_keys = self.keys[:]
        current_payload = self.payload[:]
        self.bit_prefix = []
        self.mid = []
        self.payload_prefix = []
        for shift in range(self.bit_length - 1, -1, -1):
            ones_l = [0] * (n + 1)
            sums_l = [0] * (n + 1)
            zero_keys, one_keys = [], []
            zero_payload, one_payload = [], []
            o = 0
            s = 0
            for i in range(n):
                key = current_keys[i]
                value = current_payload[i]
                s += value
                if key >> shift & 1:
                    o += 1
                    one_keys.append(key)
                    one_payload.append(value)
                else:
                    zero_keys.append(key)
                    zero_payload.append(value)
                ones_l[i + 1] = o
                sums_l[i + 1] = s
            self.bit_prefix.append(array('I', ones_l))
            self.payload_prefix.append(array('q', sums_l))
            self.mid.append(len(zero_keys))
            current_keys = zero_keys + one_keys
            current_payload = zero_payload + one_payload
        self.leaf_keys = current_keys
        self.leaf_payload = current_payload
        lp = [0] * (n + 1)
        s = 0
        for i, value in enumerate(current_payload):
            s += value
            lp[i + 1] = s
        self.leaf_payload_prefix = array('q', lp)

    def __len__(self):
        return self.n

    def _check_range(self, left, right):
        if not 0 <= left <= right <= self.n:
            raise IndexError("require 0 <= left <= right <= n")

    def rank0(self, level, position):
        """level の先頭 position 要素にある 0-bit 数。"""
        if not 0 <= level < self.bit_length or not 0 <= position <= self.n:
            raise IndexError("level or position out of range")
        return position - self.bit_prefix[level][position]

    def map_branch(self, level, left, right, bit):
        """level の [left,right) を stable partition 後の bit branch 区間へ写す。"""
        self._check_range(left, right)
        if not 0 <= level < self.bit_length or bit not in (0, 1):
            raise ValueError("invalid level or bit")
        ones = self.bit_prefix[level]
        if bit == 0:
            return left - ones[left], right - ones[right]
        return self.mid[level] + ones[left], self.mid[level] + ones[right]

    def payload_sum(self, level, left, right):
        """level の現在順配列 [left,right) の payload 和。"""
        self._check_range(left, right)
        if not 0 <= level < self.bit_length:
            raise IndexError("level out of range")
        prefix = self.payload_prefix[level]
        return prefix[right] - prefix[left]

    def branch_payload_sum(self, level, left, right, bit):
        """level の [left,right) 内で指定 bit を持つ要素の payload 和。"""
        self._check_range(left, right)
        if not 0 <= level < self.bit_length or bit not in (0, 1):
            raise ValueError("invalid level or bit")
        mapped_left, mapped_right = self.map_branch(level, left, right, bit)
        prefix = (self.payload_prefix[level + 1]
                  if level + 1 < self.bit_length else self.leaf_payload_prefix)
        return prefix[mapped_right] - prefix[mapped_left]

    def xor_take(self, left, right, mask, k):
        """
        a[left:right] を (key xor mask, original_index) 昇順にした先頭 k 件の
        (payload_sum, last_xor_key) 。k=0 は (0,-1)。O(B)。
        """
        if not 0 <= left <= right <= self.n:
            raise IndexError("require 0 <= left <= right <= n")
        if mask < 0:
            raise ValueError("mask must be non-negative")
        if not 0 <= k <= right - left:
            raise IndexError("k is out of range")
        if k == 0:
            return 0, -1
        B = self.bit_length
        bp = self.bit_prefix
        pp = self.payload_prefix
        mid = self.mid
        leaf = self.leaf_payload_prefix
        answer = 0
        xor_key = mask & ~((1 << B) - 1)
        for level in range(B):
            shift = B - 1 - level
            ones = bp[level]
            ones_l = ones[left]
            ones_r = ones[right]
            one_count = ones_r - ones_l
            m = mid[level]
            if mask >> shift & 1:
                # 好ましい側は bit 1
                if k <= one_count:
                    left = m + ones_l
                    right = m + ones_r
                else:
                    prefix = pp[level + 1] if level + 1 < B else leaf
                    answer += prefix[m + ones_r] - prefix[m + ones_l]
                    k -= one_count
                    xor_key |= 1 << shift
                    left = left - ones_l
                    right = right - ones_r
            else:
                zero_count = (right - left) - one_count
                if k <= zero_count:
                    left = left - ones_l
                    right = right - ones_r
                else:
                    prefix = pp[level + 1] if level + 1 < B else leaf
                    answer += prefix[right - ones_r] - prefix[left - ones_l]
                    k -= zero_count
                    xor_key |= 1 << shift
                    left = m + ones_l
                    right = m + ones_r
        answer += leaf[left + k] - leaf[left]
        return answer, xor_key

    def xor_kth(self, left, right, mask, k):
        """0-indexed k 番目の key xor mask。O(B)。"""
        if not 0 <= k < right - left:
            raise IndexError("k is out of range")
        return self.xor_take(left, right, mask, k + 1)[1]

    sum_k_smallest_xor_payload = xor_take


class LiChaoTree:
    """
    事前に与えた x 座標上で y=ax+b の最小/最大を管理する Li Chao Tree。
    add_line, query は各 O(log N)。add_segment_line は 1 回 O(log^2 N)。
    """

    def __init__(self, xs, *, is_min=True):
        self.xs = sorted(set(xs))
        if not self.xs:
            raise ValueError("xs must not be empty")
        self.n = len(self.xs)
        self.size = 1 << (self.n - 1).bit_length()
        self.lines = [None] * (2 * self.size)
        self.is_min = is_min

    @staticmethod
    def _value(line, x):
        return line[0] * x + line[1]

    def _better(self, first, second, x):
        if second is None:
            return True
        a = self._value(first, x)
        b = self._value(second, x)
        return a < b if self.is_min else a > b

    def _insert(self, node, left, right, line):
        current = self.lines[node]
        if current is None:
            self.lines[node] = line
            return
        mid = (left + right) // 2
        x_left = self.xs[min(left, self.n - 1)]
        x_mid = self.xs[min(mid, self.n - 1)]
        left_better = self._better(line, current, x_left)
        mid_better = self._better(line, current, x_mid)
        if mid_better:
            self.lines[node], line = line, current
        if right - left == 1:
            return
        if left_better != mid_better:
            self._insert(node * 2, left, mid, line)
        else:
            self._insert(node * 2 + 1, mid, right, line)

    def add_line(self, a, b):
        self._insert(1, 0, self.size, (a, b))

    def _add_segment(self, ql, qr, line, node, left, right):
        if qr <= left or right <= ql:
            return
        if ql <= left and right <= qr:
            self._insert(node, left, right, line)
            return
        mid = (left + right) // 2
        self._add_segment(ql, qr, line, node * 2, left, mid)
        self._add_segment(ql, qr, line, node * 2 + 1, mid, right)

    def add_segment_line(self, a, b, x_left, x_right):
        """x_left <= x < x_right に含まれる登録済み座標だけへ直線を追加する。"""
        left = bisect_left(self.xs, x_left)
        right = bisect_left(self.xs, x_right)
        if left < right:
            self._add_segment(left, right, (a, b), 1, 0, self.size)

    add_segment = add_segment_line

    def query(self, x):
        index = bisect_left(self.xs, x)
        if index == self.n or self.xs[index] != x:
            raise KeyError("query x must be included in constructor xs")
        answer = math.inf if self.is_min else -math.inf
        node = index + self.size
        while node:
            line = self.lines[node]
            if line is not None:
                value = self._value(line, x)
                answer = min(answer, value) if self.is_min else max(answer, value)
            node //= 2
        return answer


class SWAG:
    """Sliding Window Aggregation。queue の push/pop/fold を償却 O(1) で行う。"""

    def __init__(self, op, identity):
        self.op = op
        self.identity = identity
        self.left = []
        self.right = []

    def __len__(self):
        return len(self.left) + len(self.right)

    def push(self, value):
        aggregate = value if not self.right else self.op(self.right[-1][1], value)
        self.right.append((value, aggregate))

    append = push

    def _transfer(self):
        while self.right:
            value = self.right.pop()[0]
            aggregate = value if not self.left else self.op(value, self.left[-1][1])
            self.left.append((value, aggregate))

    def pop(self):
        if not self.left:
            self._transfer()
        if not self.left:
            raise IndexError("pop from empty SWAG")
        return self.left.pop()[0]

    popleft = pop

    def fold(self):
        if not self.left:
            return self.right[-1][1] if self.right else self.identity
        if not self.right:
            return self.left[-1][1]
        return self.op(self.left[-1][1], self.right[-1][1])

    prod = fold


class Mo:
    """静的区間クエリを Mo 法で処理する。区間は 0-indexed [l,r)。"""

    def __init__(self, n):
        self.n = n
        self.queries = []

    def add_query(self, left, right):
        if not 0 <= left <= right <= self.n:
            raise IndexError("require 0 <= left <= right <= n")
        self.queries.append((left, right))
        return len(self.queries) - 1

    def run(self, add_left, add_right, remove_left, remove_right, get_answer):
        q = len(self.queries)
        if q == 0:
            return []
        block = max(1, int(self.n / max(1, math.sqrt(q))))
        order = list(range(q))
        order.sort(key=lambda i: (self.queries[i][0] // block,
                                  self.queries[i][1] if (self.queries[i][0] // block) % 2 == 0 else -self.queries[i][1]))
        answers = [None] * q
        left = right = 0
        for qi in order:
            ql, qr = self.queries[qi]
            while ql < left:
                left -= 1
                add_left(left)
            while right < qr:
                add_right(right)
                right += 1
            while left < ql:
                remove_left(left)
                left += 1
            while qr < right:
                right -= 1
                remove_right(right)
            answers[qi] = get_answer()
        return answers


# ============================================================
# Ultimate Extension: Ordered Multiset Utilities
# ============================================================

class DeletableHeap:
    """任意要素を遅延削除できる min/max heap。add/discard/pop は償却 O(log N)。

    値は hash 可能で、互いに大小比較できること。max_heap=True は内部で符号を
    反転するので数値（int・float）だけで使える。タプルや文字列は TypeError
    になる（最大値が欲しいタプルは、符号を自分で反転して min heap に入れる）。

    速さ（PyPy）: discard / remove を一度も呼ばない間は、個数の表（counts）を持たず
    heapq に近い速さで動く（add / pop 約 140 万回で CPU 約 0.4 秒。旧版 1.1 秒）。
    初めて discard を呼んだときに個数の表を O(N) で作り、以後は表も更新する。
    """

    def __init__(self, iterable=(), *, max_heap=False):
        self.sign = -1 if max_heap else 1
        if max_heap:
            self.heap = [-value for value in iterable]
        else:
            self.heap = list(iterable)
        heapq.heapify(self.heap)
        self.delayed = {}          # key -> 遅延削除待ちの個数
        self.counts = None         # key -> 個数（初めて discard するまで None）
        self.size = len(self.heap)

    def __len__(self):
        return self.size

    def __bool__(self):
        return self.size > 0

    def _key(self, value):
        return -value if self.sign < 0 else value

    def _clean(self):
        heap = self.heap
        delayed = self.delayed
        while heap and heap[0] in delayed:
            key = heappop(heap)
            d = delayed[key] - 1
            if d:
                delayed[key] = d
            else:
                del delayed[key]

    def add(self, value):
        """値を1個追加する。O(log N)。"""
        key = -value if self.sign < 0 else value
        heappush(self.heap, key)
        self.size += 1
        counts = self.counts
        if counts is not None:
            counts[key] = counts.get(key, 0) + 1

    push = add

    def discard(self, value):
        """値を1個削除する（遅延削除）。入っていなければ何もせず False。償却 O(log N)。"""
        key = -value if self.sign < 0 else value
        counts = self.counts
        if counts is None:
            counts = {}
            for k in self.heap:
                counts[k] = counts.get(k, 0) + 1
            for k, d in self.delayed.items():
                c = counts[k] - d
                if c:
                    counts[k] = c
                else:
                    del counts[k]
            self.counts = counts
        c = counts.get(key, 0)
        if c == 0:
            return False
        if c == 1:
            del counts[key]
        else:
            counts[key] = c - 1
        delayed = self.delayed
        delayed[key] = delayed.get(key, 0) + 1
        self.size -= 1
        if self.heap[0] == key:
            self._clean()
        return True

    def remove(self, value):
        """値を1個削除する。入っていなければ KeyError。"""
        if not self.discard(value):
            raise KeyError(value)

    def top(self):
        """最小値（max_heap なら最大値）を削除せずに返す。空なら IndexError。"""
        if not self.size:
            raise IndexError("top from empty DeletableHeap")
        if self.delayed:
            self._clean()
        return -self.heap[0] if self.sign < 0 else self.heap[0]

    def pop(self):
        """最小値（max_heap なら最大値）を取り出して返す。空なら IndexError。償却 O(log N)。"""
        if not self.size:
            raise IndexError("top from empty DeletableHeap")
        if self.delayed:
            self._clean()
        key = heappop(self.heap)
        self.size -= 1
        counts = self.counts
        if counts is not None:
            c = counts[key]
            if c == 1:
                del counts[key]
            else:
                counts[key] = c - 1
        return -key if self.sign < 0 else key


class KSmallestSum:
    """動的 multiset の小さい方から k 個の和を管理する。各操作 O(log N)（償却）。

    内部は 2 本のヒープ（小さい k 個の最大ヒープ・残りの最小ヒープ）と遅延削除。
    sortedcontainers を使わないので PyPy で速い（N = 2×10^5 回の add と discard で CPU 約 0.3 秒）。
    値は数値（int・float）で、hash 可能なこと。

    メソッド: add(x)、discard(x) → bool、remove(x)（なければ KeyError）、set_k(k)、
        sum()（O(1)）、values()（選ばれている値を昇順の新しいリストで。O(L log L)、L は内部ヒープの長さ）、
        len(h)、属性 k・low_sum（= sum()）。
    """

    def __init__(self, k=0, iterable=()):
        if k < 0:
            raise ValueError("k must be non-negative")
        self.k = k
        vals = sorted(iterable)
        t = min(k, len(vals))
        self._lo = [-v for v in vals[:t]]       # 小さい側（符号反転の最大ヒープ）
        heapq.heapify(self._lo)
        self._hi = vals[t:]                       # 残り（最小ヒープ。ソート済みなのでそのままヒープ）
        self._dlo = {}
        self._dhi = {}
        self._nlo = t
        self._nhi = len(vals) - t
        self.low_sum = sum(vals[:t])
        cnt = {}
        for v in vals:
            cnt[v] = cnt.get(v, 0) + 1
        self._cnt = cnt

    def __len__(self):
        return self._nlo + self._nhi

    def _clean_lo(self):
        lo = self._lo
        d = self._dlo
        while lo and lo[0] in d:
            key = heappop(lo)
            c = d[key] - 1
            if c:
                d[key] = c
            else:
                del d[key]

    def _clean_hi(self):
        hi = self._hi
        d = self._dhi
        while hi and hi[0] in d:
            key = heappop(hi)
            c = d[key] - 1
            if c:
                d[key] = c
            else:
                del d[key]

    def _rebalance(self):
        target = self.k
        n = self._nlo + self._nhi
        if target > n:
            target = n
        while self._nlo > target:
            v = -heappop(self._lo)
            self._clean_lo()
            self._nlo -= 1
            self.low_sum -= v
            heappush(self._hi, v)
            self._nhi += 1
        while self._nlo < target:
            v = heappop(self._hi)
            self._clean_hi()
            self._nhi -= 1
            heappush(self._lo, -v)
            self._nlo += 1
            self.low_sum += v

    def add(self, value):
        """値を1個追加する。O(log N)。"""
        cnt = self._cnt
        cnt[value] = cnt.get(value, 0) + 1
        if self._nlo < self.k:
            # 不変条件より、このとき残り側は空
            heappush(self._lo, -value)
            self._nlo += 1
            self.low_sum += value
            return
        if self._nlo:
            t = -self._lo[0]
            if value < t:
                heapq.heapreplace(self._lo, -value)
                self._clean_lo()
                self.low_sum += value - t
                heappush(self._hi, t)
                self._nhi += 1
                return
        heappush(self._hi, value)
        self._nhi += 1

    def discard(self, value):
        """値を1個削除する。入っていなければ何もせず False。償却 O(log N)。"""
        cnt = self._cnt
        c = cnt.get(value, 0)
        if not c:
            return False
        if c == 1:
            del cnt[value]
        else:
            cnt[value] = c - 1
        if self._nlo and value <= -self._lo[0]:
            d = self._dlo
            d[-value] = d.get(-value, 0) + 1
            self._nlo -= 1
            self.low_sum -= value
            self._clean_lo()
            if self._nhi:
                v = heappop(self._hi)
                self._clean_hi()
                self._nhi -= 1
                heappush(self._lo, -v)
                self._nlo += 1
                self.low_sum += v
        else:
            d = self._dhi
            d[value] = d.get(value, 0) + 1
            self._nhi -= 1
            self._clean_hi()
        return True

    def remove(self, value):
        if not self.discard(value):
            raise KeyError(value)

    def set_k(self, k):
        """選ぶ個数 k を変える。O(|新しい k − 古い k| log N)。"""
        if k < 0:
            raise ValueError("k must be non-negative")
        self.k = k
        self._rebalance()

    def sum(self):
        return self.low_sum

    def values(self):
        """選ばれている値（小さい方から k 個）を昇順の新しいリストで返す。"""
        d = dict(self._dlo)
        res = []
        for key in sorted(self._lo, reverse=True):
            c = d.get(key, 0)
            if c:
                d[key] = c - 1
                continue
            res.append(-key)
        return res


class KLargestSum:
    """動的 multiset の大きい方から k 個の和。各操作 O(log N)（償却）。

    値を符号反転して KSmallestSum（2 本のヒープ＋遅延削除）に入れている。
    値は数値（int・float）。PyPy で N = 2×10^5 回の add と discard が CPU 約 0.3 秒
    （旧版の SortedList 2 本では 0.9 秒）。

    メソッド: add(x)、discard(x) → bool、remove(x)、set_k(k)、sum()（O(1)）、
        values()（選ばれている値を昇順の新しいリストで）、len(h)、属性 k。
    """

    def __init__(self, k=0, iterable=()):
        self._inner = KSmallestSum(k, (-value for value in iterable))

    def __len__(self):
        return len(self._inner)

    @property
    def k(self):
        return self._inner.k

    def add(self, value):
        self._inner.add(-value)

    def discard(self, value):
        return self._inner.discard(-value)

    def remove(self, value):
        if not self._inner.discard(-value):
            raise KeyError(value)

    def set_k(self, k):
        self._inner.set_k(k)

    def sum(self):
        return -self._inner.sum()

    def values(self):
        return [-value for value in reversed(self._inner.values())]


class MedianMultiset:
    """中央値と中央値への絶対偏差和を O(1)、追加削除を O(log N)（償却）で管理する。

    内部は 2 本のヒープ（小さい側 ceil(N/2) 個の最大ヒープ・大きい側の最小ヒープ）と遅延削除。
    各操作のあとで両方のヒープの先頭を常に有効な値に保つので、median 系は O(1)。
    値は数値（int・float）で、hash 可能なこと。
    PyPy で N = 2×10^5 回の add・discard・min_abs_sum が CPU 約 0.6 秒（旧版の SortedList 2 本では 2.7 秒）。

    メソッド: add(x)、discard(x) → bool、remove(x)（なければ KeyError）、len(m)、
        median(average=False)（偶数個なら下側の中央値。average=True なら上下の平均）、
        median_pair()（(下側, 上側)。奇数個なら同じ値 2 つ）、
        min_abs_sum()（min_x Σ|a_i − x|。空なら 0）。
        属性 low_sum / high_sum（小さい側・大きい側の和）。
    """

    def __init__(self, iterable=()):
        vals = sorted(iterable)
        t = (len(vals) + 1) // 2
        self._lo = [-v for v in vals[:t]]   # 小さい側（符号反転の最大ヒープ）。奇数個なら1個多い
        heapq.heapify(self._lo)
        self._hi = vals[t:]
        self._dlo = {}
        self._dhi = {}
        self._nlo = t
        self._nhi = len(vals) - t
        self.low_sum = sum(vals[:t])
        self.high_sum = sum(vals[t:])
        cnt = {}
        for v in vals:
            cnt[v] = cnt.get(v, 0) + 1
        self._cnt = cnt

    def __len__(self):
        return self._nlo + self._nhi

    def _clean_lo(self):
        lo = self._lo
        d = self._dlo
        while lo and lo[0] in d:
            key = heappop(lo)
            c = d[key] - 1
            if c:
                d[key] = c
            else:
                del d[key]

    def _clean_hi(self):
        hi = self._hi
        d = self._dhi
        while hi and hi[0] in d:
            key = heappop(hi)
            c = d[key] - 1
            if c:
                d[key] = c
            else:
                del d[key]

    def _rebalance(self):
        target = (self._nlo + self._nhi + 1) // 2
        while self._nlo > target:
            v = -heappop(self._lo)
            self._clean_lo()
            self._nlo -= 1
            self.low_sum -= v
            heappush(self._hi, v)
            self._nhi += 1
            self.high_sum += v
        while self._nlo < target:
            v = heappop(self._hi)
            self._clean_hi()
            self._nhi -= 1
            self.high_sum -= v
            heappush(self._lo, -v)
            self._nlo += 1
            self.low_sum += v

    def add(self, value):
        """値を1個追加する。O(log N)。"""
        cnt = self._cnt
        cnt[value] = cnt.get(value, 0) + 1
        if not self._nlo or value <= -self._lo[0]:
            heappush(self._lo, -value)
            self._nlo += 1
            self.low_sum += value
        else:
            heappush(self._hi, value)
            self._nhi += 1
            self.high_sum += value
        self._rebalance()

    def discard(self, value):
        """値を1個削除する。入っていなければ何もせず False。償却 O(log N)。"""
        cnt = self._cnt
        c = cnt.get(value, 0)
        if not c:
            return False
        if c == 1:
            del cnt[value]
        else:
            cnt[value] = c - 1
        if self._nlo and value <= -self._lo[0]:
            d = self._dlo
            d[-value] = d.get(-value, 0) + 1
            self._nlo -= 1
            self.low_sum -= value
            self._clean_lo()
        else:
            d = self._dhi
            d[value] = d.get(value, 0) + 1
            self._nhi -= 1
            self.high_sum -= value
            self._clean_hi()
        self._rebalance()
        return True

    def remove(self, value):
        if not self.discard(value):
            raise KeyError(value)

    def median(self, *, average=False):
        if not self._nlo:
            raise IndexError("median of empty multiset")
        low = -self._lo[0]
        if average and self._nlo == self._nhi:
            return (low + self._hi[0]) / 2
        return low

    def median_pair(self):
        if not self._nlo:
            raise IndexError("median of empty multiset")
        low = -self._lo[0]
        return low, (self._hi[0] if self._nlo == self._nhi else low)

    def min_abs_sum(self):
        """min_x sum(|a_i-x|)。x は任意の中央値。O(1)。"""
        if not self._nlo:
            return 0
        median = -self._lo[0]
        return median * self._nlo - self.low_sum + self.high_sum - median * self._nhi


class IntervalSet:
    """互いに素な半開区間 [l,r) の union を管理する（重なる・接する区間は 1 本に併合）。

    内部は左端の順序集合（バケット分割の _g06SortedKeys）と、左端 → 右端の dict。
    sortedcontainers を使わず、位置指定アクセスもしないので PyPy で速い
    （区間数 1.6×10^4 で add / discard を 2×10^5 回と毎回 mex で CPU 約 2 秒前後。旧版は SortedList のタプルで約 6 秒）。

    属性:
        total_length : いま塗られている長さの合計（区間の長さの和）。O(1) で読める（メソッドではなく属性）
        intervals    : 全区間 [(l, r), ...] を左端の昇順に並べた新しいリスト（読むたびに O(区間数)）

    メソッド（区間はすべて半開 [left, right)）:
        add(l, r) → 新しく塗られた長さ、discard(l, r) / remove(l, r) → 実際に消えた長さ、
        contains(x) / x in s、covers(l, r)、covered_length(l, r)、mex(x) / free_ge(x)、free_le(x)、
        find(x)、left_of(x)、right_of(x)、len(s)（区間の本数）、iter(s)（(l, r) を左から）。
    計算量: add / discard は償却 O(log N)（N は区間数。消える区間は作られた回数で払う）、
        点の問い合わせは O(log N)、covered_length は O(log N + 重なる区間数)。
    """

    def __init__(self, intervals=()):
        self._keys = _g06SortedKeys()
        self._right = {}
        self.total_length = 0
        for left, right in intervals:
            self.add(left, right)

    def __len__(self):
        return len(self._keys)

    def __iter__(self):
        right = self._right
        for a in self._keys.to_list():
            yield (a, right[a])

    @property
    def intervals(self):
        """全区間 [(l, r), ...] を左端の昇順に並べた新しいリスト。O(区間数)。"""
        right = self._right
        return [(a, right[a]) for a in self._keys.to_list()]

    def __repr__(self):
        return "IntervalSet(%r)" % (self.intervals,)

    def add(self, left, right):
        """[left, right) を塗り、新しく塗られた長さを返す。接する区間とも併合する。償却 O(log N)。"""
        if left >= right:
            return 0
        keys = self._keys
        rt = self._right
        p = keys.le(left)
        start = p if (p is not None and rt[p] >= left) else left
        removed = keys.pop_range(start, right, True)
        old_total = self.total_length
        total = old_total
        if removed:
            a0 = removed[0]
            if a0 < left:
                left = a0
            for a in removed:
                b = rt.pop(a)
                total -= b - a
            if b > right:
                right = b
        keys.add(left)
        rt[left] = right
        total += right - left
        self.total_length = total
        return total - old_total

    def discard(self, left, right):
        """[left,right) を除き、実際に除かれた長さを返す。償却 O(log N)。"""
        if left >= right:
            return 0
        keys = self._keys
        rt = self._right
        old_total = self.total_length
        total = old_total
        q = keys.lt(left)
        if q is not None:
            b = rt[q]
            if b > left:
                # q の区間 [q, b) を [q, left) に縮める（右に余りがあれば [right, b) を足す）
                rt[q] = left
                total -= b - left
                if right < b:
                    keys.add(right)
                    rt[right] = b
                    total += b - right
                    self.total_length = total
                    return old_total - total
        removed = keys.pop_range(left, right)
        if removed:
            for a in removed:
                b = rt.pop(a)
                total -= b - a
            if right < b:
                keys.add(right)
                rt[right] = b
                total += b - right
        self.total_length = total
        return old_total - total

    remove = discard

    def contains(self, value):
        """点 value が塗られているか。O(log N)。"""
        p = self._keys.le(value)
        return p is not None and value < self._right[p]

    __contains__ = contains

    def covers(self, left, right):
        """[left, right) が丸ごと塗られているか（left >= right なら True）。O(log N)。"""
        if left >= right:
            return True
        p = self._keys.le(left)
        return p is not None and right <= self._right[p]

    def covered_length(self, left, right):
        """[left, right) のうち塗られている長さ。O(log N + 重なる区間数)。"""
        if left >= right:
            return 0
        keys = self._keys
        rt = self._right
        answer = 0
        q = keys.lt(left)
        if q is not None:
            b = rt[q]
            if b > left:
                answer += (b if b < right else right) - left
        for a in keys.range_keys(left, right):
            b = rt[a]
            answer += (b if b < right else right) - a
        return answer

    def mex(self, value=0):
        """value 以上で union に含まれない最小値（主に整数区間用）。O(log N)。"""
        p = self._keys.le(value)
        if p is not None:
            b = self._right[p]
            if value < b:
                return b
        return value

    def find(self, value):
        """value を含む区間 (l, r)（半開）を返す。どの区間にも含まれなければ None。O(log N)。

        何に用いるか:
            「x を含む連続した塗り区間の端」を知りたいとき。

        使用例（実際の出力）:
            s = IntervalSet([(1, 4), (6, 9)])
            print(s.find(2), s.find(4), s.find(6))   # (1, 4) None (6, 9)
        """
        p = self._keys.le(value)
        if p is not None:
            b = self._right[p]
            if value < b:
                return (p, b)
        return None

    def left_of(self, value):
        """value を含まない区間のうち、value より左で最も近いもの (l, r)（r <= value）。なければ None。O(log N)。

        value がある区間の中にあるときは、その区間の 1 つ左の区間を返す。

        使用例（実際の出力）:
            s = IntervalSet([(1, 4), (6, 9)])
            print(s.left_of(5), s.left_of(7), s.left_of(0))   # (1, 4) (1, 4) None
        """
        keys = self._keys
        p = keys.le(value)
        if p is not None and self._right[p] > value:
            p = keys.lt(p)
        return (p, self._right[p]) if p is not None else None

    def right_of(self, value):
        """l > value となる区間のうち、最も左のもの (l, r)。なければ None。O(log N)。

        value がある区間の中にあるときは、その区間の 1 つ右の区間を返す。

        使用例（実際の出力）:
            s = IntervalSet([(1, 4), (6, 9)])
            print(s.right_of(0), s.right_of(1), s.right_of(6))   # (1, 4) (6, 9) None
        """
        p = self._keys.gt(value)
        return (p, self._right[p]) if p is not None else None

    def free_le(self, value):
        """value 以下で union に含まれない最大の整数（整数区間用）。O(log N)。

        value が区間 [l, r) の中なら l - 1、外なら value そのもの。
        隣り合う区間は add でくっつくので、l - 1 は必ず含まれない。
        （value 以上で最小の含まれない整数は mex(value)。）

        使用例（実際の出力）:
            s = IntervalSet([(1, 4), (6, 9)])
            print(s.free_le(2), s.free_le(4), s.free_le(8), s.free_le(0))   # 0 4 5 0
        """
        p = self._keys.le(value)
        if p is not None and value < self._right[p]:
            return p - 1
        return value

    free_ge = mex


# ============================================================
# Ultimate Extension: Fast DP Helpers (l_ / s_)
# ============================================================

def s_lcs_len_bitset(s, t):
    """bitset による LCS 長。短い側の長さを W として概ね O(|long|*W/word)。"""
    if len(s) > len(t):
        s, t = t, s
    masks = {}
    for i, char in enumerate(s):
        masks[char] = masks.get(char, 0) | 1 << i
    row = 0
    for char in t:
        x = row | masks.get(char, 0)
        row = x & ~(x - ((row << 1) | 1))
    return _popcount(row)


def l_subset_sum_bitset(values):
    """非負整数 values で作れる和 s の bit s が立つ整数を返す。O(N*S/word)。"""
    bits = 1
    for value in values:
        if value < 0:
            raise ValueError("l_subset_sum_bitset requires non-negative values")
        bits |= bits << value
    return bits


def l_subset_sum_possible(values, target):
    """非負整数から target を作れるか。target より大きい bit は随時捨てる。"""
    if target < 0:
        return False
    bits = 1
    mask = (1 << (target + 1)) - 1
    for value in values:
        if value < 0:
            raise ValueError("l_subset_sum_possible requires non-negative values")
        if value > target:
            continue
        bits |= bits << value
        bits &= mask
    return bool(bits >> target & 1)


def l_subset_sum_values(values, limit=None):
    """作れる非負の和を昇順列挙する。limit 指定時は limit 以下のみ。"""
    bits = l_subset_sum_bitset(values)
    if limit is None:
        limit = bits.bit_length() - 1
    return [value for value in range(limit + 1) if bits >> value & 1]


def l_knapsack_01(weights, values, capacity):
    """0/1 knapsack の最大価値。重さは非負。O(N*capacity), O(capacity)。"""
    if len(weights) != len(values):
        raise ValueError("weights and values must have equal length")
    if capacity < 0 or any(weight < 0 for weight in weights):
        raise ValueError("weights and capacity must be non-negative")
    dp = [-math.inf] * (capacity + 1)
    dp[0] = 0
    for weight, value in zip(weights, values):
        for current in range(capacity - weight, -1, -1):
            if dp[current] != -math.inf:
                dp[current + weight] = max(dp[current + weight], dp[current] + value)
    return max(dp)


def l_knapsack_value_dp(weights, values, capacity):
    """価値 DP 版 0/1 knapsack。価値が非負で、総価値が小さい場合向け。"""
    if len(weights) != len(values):
        raise ValueError("weights and values must have equal length")
    if any(weight < 0 for weight in weights) or any(value < 0 for value in values):
        raise ValueError("weights and values must be non-negative")
    if capacity < 0:
        raise ValueError("capacity must be non-negative")
    total_value = sum(values)
    dp = [math.inf] * (total_value + 1)
    dp[0] = 0
    for weight, value in zip(weights, values):
        for current in range(total_value - value, -1, -1):
            if dp[current] + weight < dp[current + value]:
                dp[current + value] = dp[current] + weight
    return max(value for value, weight in enumerate(dp) if weight <= capacity)


def l_max_subarray(a, *, allow_empty=False):
    """最大部分配列を (sum,left,right) で返す。区間は [left,right)。O(N)。"""
    if not a:
        if allow_empty:
            return 0, 0, 0
        raise ValueError("a must not be empty unless allow_empty=True")
    best_sum = 0 if allow_empty else -math.inf
    best_left = best_right = 0
    current_sum = 0
    current_left = 0
    for right, value in enumerate(a, 1):
        if current_sum <= 0:
            current_sum = value
            current_left = right - 1
        else:
            current_sum += value
        if current_sum > best_sum:
            best_sum = current_sum
            best_left, best_right = current_left, right
    return best_sum, best_left, best_right


def l_max_subarray_circular(a, *, allow_empty=False):
    """巡回配列の最大部分配列和（各要素は高々1回）。O(N)。"""
    if not a:
        if allow_empty:
            return 0
        raise ValueError("a must not be empty unless allow_empty=True")
    normal = l_max_subarray(a, allow_empty=allow_empty)[0]
    total = sum(a)
    min_sum = -l_max_subarray([-value for value in a], allow_empty=False)[0]
    wrapped = -math.inf if min_sum == total else total - min_sum
    return max(normal, wrapped)


def l_partition_min_difference(values):
    """非負整数列を2組に分けたときの和の差の最小値。bitset subset sum。"""
    total = sum(values)
    if total < 0 or any(value < 0 for value in values):
        raise ValueError("values must be non-negative")
    bits = l_subset_sum_bitset(values)
    half = total // 2
    possible = bits & ((1 << (half + 1)) - 1)
    best = possible.bit_length() - 1
    return total - 2 * best


# ============================================================
# Ultimate Extension: Binary Search / Convex Optimization
# ============================================================

def bs_first_true(left, right, predicate):
    """[left,right) で predicate が初めて True になる整数。存在しなければ right。"""
    ng, ok = left - 1, right
    while ok - ng > 1:
        mid = (ok + ng) // 2
        if predicate(mid):
            ok = mid
        else:
            ng = mid
    return ok


def bs_last_true(left, right, predicate):
    """[left,right) で predicate が最後に True になる整数。存在しなければ left-1。"""
    ok, ng = left - 1, right
    while ng - ok > 1:
        mid = (ok + ng) // 2
        if predicate(mid):
            ok = mid
        else:
            ng = mid
    return ok


def bs_boundary(ng, ok, predicate):
    """predicate(ng)=False, predicate(ok)=True の境界を二分探索して ok を返す。大小順は不問。"""
    while abs(ok - ng) > 1:
        mid = (ok + ng) // 2
        if predicate(mid):
            ok = mid
        else:
            ng = mid
    return ok


def bs_float(left, right, predicate, iterations=80):
    """
    False→True 型の実数境界。iterations 回後の True 側（right）を返す。

    predicate(left) = False、predicate(right) = True で、途中で 1 回だけ切り替わること。

    反復回数の目安
    -------------------------------------------------------
        区間の幅は 1 回で半分になるので、幅 (right-left) を誤差 eps まで縮めるには
        log2((right-left)/eps) 回いる。既定の 80 回で 2^80 ≒ 1.2×10^24 分の 1。
          - 幅 10^9・誤差 10^-9 → 60 回
          - 幅 10^18・誤差 10^-6 → 80 回
        float（double）は有効桁 約 15〜16 桁なので、相対誤差 10^-16 より細かくはならない
        （それ以上回しても値が変わらないだけで害はない）。
        predicate が重い（1 回 O(N)）ときは、必要な回数を計算して減らすと速い。
        誤差の判定は絶対誤差・相対誤差のどちらかを問題文で確かめる。
    """
    for _ in range(iterations):
        mid = (left + right) / 2
        if predicate(mid):
            right = mid
        else:
            left = mid
    return right


def opt_ternary_search_int(left, right, function, *, minimize=True):
    """
    閉区間 [left,right] 上の離散単峰関数の最小/最大点を (arg,value) で返す。

    注意（平らな部分）
    -------------------------------------------------------
        function は「最小点まで狭義に減少し、その後は狭義に増加」（minimize=True のとき）であること。
        最小値以外のところで同じ値が続く（平らな部分がある）と、m1 と m2 の値が等しいときに
        どちらへ縮めるか決められず、最小点を捨てて誤った答えを返すことがある。
          例：[5, 5, 5, 5, 5, 5, 5, 5, 0, 5] のような関数。
        下に凸な関数（f(x+1) - f(x) が広義単調増加）なら、平らな部分は最小値のところにしか
        ないので正しく動く。凸なら f(x+1) - f(x) >= 0 となる最小の x を bs_boundary で
        二分探索する方法も確実。
        最小点が複数あるとき、どれを返すかは決まっていない。
    """
    if left > right:
        raise ValueError("left must be <= right")
    sign = 1 if minimize else -1
    while right - left > 6:
        m1 = (2 * left + right) // 3
        m2 = (left + 2 * right) // 3
        if sign * function(m1) <= sign * function(m2):
            right = m2 - 1
        else:
            left = m1 + 1
    arg = min(range(left, right + 1), key=lambda x: sign * function(x))
    return arg, function(arg)


def opt_ternary_search_float(left, right, function, *, minimize=True, iterations=100):
    """実数単峰関数の三分探索。返り値は (arg,value)。"""
    sign = 1 if minimize else -1
    for _ in range(iterations):
        m1 = (2 * left + right) / 3
        m2 = (left + 2 * right) / 3
        if sign * function(m1) <= sign * function(m2):
            right = m2
        else:
            left = m1
    arg = (left + right) / 2
    return arg, function(arg)


def opt_divide_conquer_dp_layer(prev, n, cost, lo=0, hi=None, *,
                                destination_left=1, destination_right=None,
                                allow_empty=False, maximize=False, tie_left=True,
                                parent_out=None, return_parent=False):
    """
    分割統治 DP 最適化で1 layer を計算する。

      dp[r] = best(prev[l] + cost(l,r))

    cost の区間規約は [l,r)。通常 l < r、allow_empty=True なら l == r も可。
    候補 l は半開 [lo,hi)、計算対象 r は destination_left 以上
    destination_right 以下。最適 l が r に対し単調非減少であることを
    呼び出し側が保証する。同値は tie_left=True なら小さい l を選ぶ。

    cost は cost(l,r) の callable、または move(l,r) 後に value() か
    get() を返す mutable interval evaluator でもよい。返り値は長さ n+1 の
    dp。return_parent=True なら (dp,parent)。parent_out にも argbest を書く。
    計算量 O(n log n * cost評価時間)、メモリ O(n)。
    """
    if n < 0 or len(prev) < n + 1:
        raise ValueError("prev must contain indices 0..n")
    destination_right = n if destination_right is None else destination_right
    hi = n + int(bool(allow_empty)) if hi is None else hi
    if not 0 <= destination_left <= destination_right <= n:
        raise ValueError("invalid destination range")
    if not 0 <= lo <= hi <= n + int(bool(allow_empty)):
        raise ValueError("invalid candidate range")

    infinity = -math.inf if maximize else math.inf
    dp = [infinity] * (n + 1)
    parent = [-1] * (n + 1)
    if callable(cost):
        evaluate = cost
    else:
        move = getattr(cost, "move", None)
        getter = getattr(cost, "value", None)
        if getter is None:
            getter = getattr(cost, "get", None)
        if move is None or getter is None:
            raise TypeError("cost must be callable or provide move(l,r) and value()/get()")

        def evaluate(left, right):
            move(left, right)
            return getter()

    def is_better(value, index, best_value, best_index):
        if best_index == -1:
            return True
        if value != best_value:
            return value > best_value if maximize else value < best_value
        return index < best_index if tie_left else index > best_index

    def solve(left_r, right_r, opt_left, opt_right):
        if left_r > right_r:
            return
        mid = (left_r + right_r) // 2
        candidate_left = max(lo, opt_left)
        endpoint = mid + int(bool(allow_empty))
        candidate_right = min(hi, opt_right + 1, endpoint)
        best_value = infinity
        best_index = -1
        for left in range(candidate_left, candidate_right):
            value = prev[left] + evaluate(left, mid)
            if is_better(value, left, best_value, best_index):
                best_value = value
                best_index = left
        dp[mid] = best_value
        parent[mid] = best_index
        if left_r == right_r:
            return
        split = opt_left if best_index == -1 else best_index
        solve(left_r, mid - 1, opt_left, split)
        solve(mid + 1, right_r, split, opt_right)

    solve(destination_left, destination_right, lo, hi - 1)
    if parent_out is not None:
        if len(parent_out) < n + 1:
            raise ValueError("parent_out must have length at least n+1")
        parent_out[:n + 1] = parent
    return (dp, parent) if return_parent else dp


class MinPlusMatrix:
    """
    min-plus semiring 上の正方行列。compose は方向を明示的に固定する:

      C = A.compose(B) = A ⊗ B
      C.apply(v) == A.apply(B.apply(v))

    すなわち右の B を先に適用する。compose O(D^3)、apply O(D^2)。
    INF 以上の値は到達不能とし、INF との加算は行わない。
    """

    def __init__(self, rows, inf=10**30):
        rows = tuple(tuple(row) for row in rows)
        n = len(rows)
        if any(len(row) != n for row in rows):
            raise ValueError("matrix must be square")
        self.rows = rows
        self.n = n
        self.inf = inf

    @classmethod
    def identity(cls, n, inf=10**30):
        if n < 0:
            raise ValueError("n must be non-negative")
        return cls([[0 if i == j else inf for j in range(n)] for i in range(n)], inf)

    def compose(self, other):
        """A.compose(B) = A ⊗ B（先に B、続けて A を適用する遷移）。C[i][j] = min_k (A[i][k] + B[k][j])。
        inf 以上の成分は到達不能として足さない。B の各行で inf 未満の列だけを持っておいて回すので、疎な行列ほど速い。O(D^3)。
        注意: PyPy では inf が 64 bit に収まらない（既定の 10^30 など）と多倍長整数との比較が入り 2〜5 割ほど遅くなる（D = 100 の power(10^9) で約 0.19 秒と約 0.16 秒）。
        値の上限が分かっていれば inf=4 * 10**18 のように 64 bit に収まる値を渡すとよい。"""
        if self.n != other.n or self.inf != other.inf:
            raise ValueError("matrix dimensions and INF must match")
        n, inf = self.n, self.inf
        a, b = self.rows, other.rows
        fin = []
        for k in range(n):
            bk = b[k]
            fin.append([(j, bk[j]) for j in range(n) if bk[j] < inf])
        result = []
        for i in range(n):
            ai = a[i]
            row = [inf] * n
            for k in range(n):
                left = ai[k]
                if left >= inf:
                    continue
                for j, right in fin[k]:
                    value = left + right
                    if value < row[j]:
                        row[j] = value
            result.append(row)
        return MinPlusMatrix(result, inf)

    __matmul__ = compose

    def apply(self, vector):
        if len(vector) != self.n:
            raise ValueError("vector length must match matrix dimension")
        inf = self.inf
        answer = [inf] * self.n
        for i, row in enumerate(self.rows):
            best = inf
            for weight, value in zip(row, vector):
                if weight < inf and value < inf and weight + value < best:
                    best = weight + value
            answer[i] = best
        return answer

    def power(self, exponent):
        if exponent < 0:
            raise ValueError("exponent must be non-negative")
        result = MinPlusMatrix.identity(self.n, self.inf)
        base = self
        while exponent:
            if exponent & 1:
                result = result.compose(base)
            base = base.compose(base)
            exponent >>= 1
        return result

    def __eq__(self, other):
        return (isinstance(other, MinPlusMatrix) and self.rows == other.rows
                and self.inf == other.inf)

    def __repr__(self):
        return f"MinPlusMatrix({self.rows!r}, inf={self.inf!r})"

    def __matmul__(self, other):
        """A @ B は A.compose(B) と同じ（先に B、続けて A を適用する遷移の行列）。"""
        return self.compose(other)


class ShortestAbsentSubsequence:
    """
    文字列の各区間に対し、alphabet 上で「部分列でない最短列」の
    長さを返す。MinPlusMatrix + BiSegTree。構築 O(N A^3)、
    query O(A^3 log N)、set O(A^3 log N)。空区間の答えは1。
    """

    def __init__(self, text, alphabet="ACGT", inf=10**30):
        if not alphabet or len(set(alphabet)) != len(alphabet):
            raise ValueError("alphabet must contain distinct symbols")
        self.text = list(text)
        self.alphabet = tuple(alphabet)
        self.index = {char: i for i, char in enumerate(self.alphabet)}
        self.inf = inf
        self.dimension = len(self.alphabet)
        identity = MinPlusMatrix.identity(self.dimension, inf)
        matrices = [self._char_matrix(char) for char in self.text]
        self.seg = BiSegTree(matrices, lambda left, right: left.compose(right), identity)

    def _char_matrix(self, char):
        if char not in self.index:
            raise ValueError("text contains a symbol outside alphabet")
        n, inf = self.dimension, self.inf
        rows = [[inf] * n for _ in range(n)]
        for i in range(n):
            rows[i][i] = 0
        rows[self.index[char]] = [1] * n
        return MinPlusMatrix(rows, inf)

    def __len__(self):
        return len(self.text)

    def set(self, position, char):
        n = len(self.text)
        if not -n <= position < n:
            raise IndexError("position out of range")
        if position < 0:
            position += n
        matrix = self._char_matrix(char)
        self.text[position] = char
        self.seg.set(position, matrix)

    def query(self, left=0, right=None):
        right = len(self.text) if right is None else right
        transform = self.seg.prod(left, right)
        return min(transform.apply([1] * self.dimension))


class SlopeTrick:
    """
    区分線形凸関数を管理する Slope Trick。
    add_abs / add_a_minus_x / add_x_minus_a / shift は O(log N)。
    """

    def __init__(self):
        self.min_value = 0
        self.left = []   # max heap: -(breakpoint-left_offset)
        self.right = []  # min heap: breakpoint-right_offset
        self.left_offset = 0
        self.right_offset = 0

    def _push_left(self, value):
        heappush(self.left, -(value - self.left_offset))

    def _push_right(self, value):
        heappush(self.right, value - self.right_offset)

    def _top_left(self):
        return -self.left[0] + self.left_offset

    def _top_right(self):
        return self.right[0] + self.right_offset

    def add_constant(self, value):
        self.min_value += value

    def add_a_minus_x(self, a):
        """max(a-x, 0) を加える。"""
        if self.right and self._top_right() < a:
            value = self._top_right()
            self.min_value += a - value
            heappop(self.right)
            self._push_right(a)
            self._push_left(value)
        else:
            self._push_left(a)

    def add_x_minus_a(self, a):
        """max(x-a, 0) を加える。"""
        if self.left and self._top_left() > a:
            value = self._top_left()
            self.min_value += value - a
            heappop(self.left)
            self._push_left(a)
            self._push_right(value)
        else:
            self._push_right(a)

    def add_abs(self, a):
        self.add_a_minus_x(a)
        self.add_x_minus_a(a)

    def shift(self, delta_left, delta_right=None):
        """
        f_new(x) = min_{x-delta_right <= y <= x-delta_left} f(y)。単純平行移動は shift(d)。

        「前の値 y から、今の値 x へ y + delta_left 以上 y + delta_right 以下だけ動ける」遷移。
        delta_left <= delta_right であること。O(1)（左右のヒープのずらし量を変えるだけ）。

        使用例
        -------------------------------------------------------
            # 時刻 1, 2, … に位置 a_i へ行けば罰金 0、ずれると |x - a_i| の罰金。
            # 1 単位時間に動ける距離は D 以下。罰金の合計の最小値は
            st = SlopeTrick()
            for i, ai in enumerate(a):
                if i:
                    st.shift(-D, D)      # 位置を -D 以上 D 以下だけ動かせる
                st.add_abs(ai)
            st.get_min()

            # 単純な平行移動 f_new(x) = f(x - 3)
            st.shift(3)
        """
        if delta_right is None:
            delta_right = delta_left
        if delta_left > delta_right:
            raise ValueError("require delta_left <= delta_right")
        self.left_offset += delta_left
        self.right_offset += delta_right

    def cumulative_min_from_left(self):
        """f_new(x)=min_{y<=x} f(y)。"""
        self.right.clear()

    def cumulative_min_from_right(self):
        """f_new(x)=min_{y>=x} f(y)。"""
        self.left.clear()

    def argmin_interval(self):
        left = self._top_left() if self.left else -math.inf
        right = self._top_right() if self.right else math.inf
        return left, right

    def get_min(self):
        return self.min_value

    def evaluate(self, x):
        """現在の f(x) を O(保持 breakpoints 数) で評価する（デバッグ向け）。"""
        value = self.min_value
        value += sum(max((-item + self.left_offset) - x, 0) for item in self.left)
        value += sum(max(x - (item + self.right_offset), 0) for item in self.right)
        return value


# ============================================================
# Ultimate Extension: String Automata / Hash
# ============================================================

class RollingHash:
    """mod 2^61-1 の固定 base 単一ローリングハッシュ。

    一般 sequence は list snapshot として固定するため、構築後に元の mutable sequence を
    変更しても hash と公開 ``sequence`` は不変。部分列 hash / 比較 / LCP は
    O(1) / 期待 O(1) / O(log N) だが、単一法なので等値判定は確率的である。

    具体的に base=911382323 では整数列 ``[0,0]`` と ``[1,-911382323]`` が同じ長さ・hash
    となり ``same`` が True になり得る。厳密一致が必須なら SuffixArray、KMP、Z 法を使う。
    """

    MOD = (1 << 61) - 1

    def __init__(self, sequence, base=911382323):
        if (not isinstance(base, int) or isinstance(base, bool) or
                not 1 < base < self.MOD):
            raise ValueError("require 1 < base < 2^61-1")
        if isinstance(sequence, (str, bytes)):
            self.sequence = sequence
        else:
            try:
                self.sequence = list(sequence)
            except TypeError as error:
                raise TypeError("sequence must be iterable") from error
        self.n = len(self.sequence)
        self.base = base
        self.power = [1] * (self.n + 1)
        self.prefix = [0] * (self.n + 1)
        for i, item in enumerate(self.sequence):
            value = ord(item) + 1 if isinstance(item, str) else int(item) % self.MOD + 1
            self.power[i + 1] = self.power[i] * base % self.MOD
            self.prefix[i + 1] = (self.prefix[i] * base + value) % self.MOD

    def _validate_range(self, left, right):
        """半開区間を検査し、型・順序・範囲違反を IndexError に統一する。"""
        if (not isinstance(left, int) or isinstance(left, bool) or
                not isinstance(right, int) or isinstance(right, bool) or
                not 0 <= left <= right <= self.n):
            raise IndexError("require 0 <= left <= right <= n")

    def get(self, left=0, right=None):
        """sequence[left:right] の hash。"""
        right = self.n if right is None else right
        self._validate_range(left, right)
        return (self.prefix[right] - self.prefix[left] * self.power[right - left]) % self.MOD

    __call__ = get

    def same(self, left1, right1, other, left2, right2):
        if self.base != other.base:
            raise ValueError("RollingHash bases must be equal")
        self._validate_range(left1, right1)
        other._validate_range(left2, right2)
        return right1 - left1 == right2 - left2 and self.get(left1, right1) == other.get(left2, right2)

    def lcp(self, other, left1=0, right1=None, left2=0, right2=None):
        """2 suffix/range の最長共通接頭辞長。O(log N)。base は同一であること。"""
        if self.base != other.base:
            raise ValueError("RollingHash bases must be equal")
        right1 = self.n if right1 is None else right1
        right2 = other.n if right2 is None else right2
        self._validate_range(left1, right1)
        other._validate_range(left2, right2)
        low, high = 0, min(right1 - left1, right2 - left2) + 1
        while high - low > 1:
            mid = (low + high) // 2
            if self.get(left1, left1 + mid) == other.get(left2, left2 + mid):
                low = mid
            else:
                high = mid
        return low

    def concat(self, left_hash, right_hash, right_length):
        """hash(left + right)。right_length <= 元列長。"""
        if (not isinstance(right_length, int) or isinstance(right_length, bool) or
                not 0 <= right_length <= self.n):
            raise IndexError("right_length is out of precomputed range")
        return (left_hash * self.power[right_length] + right_hash) % self.MOD


def s_rolling_hash(sequence, base=911382323):
    return RollingHash(sequence, base)


def s_hash_find(text, pattern, base=911382323):
    """ローリングハッシュで pattern の出現開始位置を列挙する。期待 O(N)。"""
    if (not isinstance(base, int) or isinstance(base, bool) or
            not 1 < base < RollingHash.MOD):
        raise ValueError("require 1 < base < 2^61-1")
    if len(pattern) == 0:
        return list(range(len(text) + 1))
    if len(pattern) > len(text):
        return []
    text_hash = RollingHash(text, base)
    pattern_hash = RollingHash(pattern, base).get()
    m = len(pattern)
    return [i for i in range(len(text) - m + 1) if text_hash.get(i, i + m) == pattern_hash]


class AhoCorasick:
    """複数パターンを同時検索する省メモリ Aho--Corasick automaton。

    各 state は直接終端する pattern ID だけを ``own_output`` に持ち、proper failure
    suffix の最寄り終端を ``output_link`` でたどる。failure 祖先の ID を build 時に
    全コピーしないため、pattern 総長 S、trie node 数 V、pattern 数 K に対し build は
    期待 O(S)、通常領域 O(V+K)。空 pattern がなければ走査・列挙は O(|text|+出力数)。

    互換属性 ``output`` は build 後の初回読取り時だけ従来の全出力表を展開するため、
    その明示アクセスだけは全 entry 数ぶんの時間・領域を使う。空 pattern は root の
    直接出力にだけ置き、非 root へ failure 継承しない。
    """

    def __init__(self, patterns=()):
        snapshots = [self._snapshot_pattern(pattern) for pattern in list(patterns)]
        self.next = [{}]
        self.fail = [0]
        self.own_output = [[]]
        self.output_link = [-1]
        self.patterns = []
        # pattern ID -> trie/failure-automaton 上の終端 state。空 pattern は root(0)。
        self.pattern_terminal = []
        self._order = [0]
        self._built = False
        self._prebuild_output = [[]]
        self._output_cache = None
        for pattern in snapshots:
            self.add(pattern)

    @staticmethod
    def _snapshot_pattern(pattern):
        """pattern を不変 snapshot にし、全 symbol の hashability を検査する。"""
        if isinstance(pattern, (str, bytes)):
            snapshot = pattern
        else:
            try:
                snapshot = tuple(pattern)
            except TypeError as error:
                raise TypeError("pattern must be iterable") from error
        for symbol in snapshot:
            try:
                hash(symbol)
            except TypeError as error:
                raise TypeError("pattern symbols must be hashable") from error
        return snapshot

    def _validate_state(self, state, name="state"):
        """state が automaton の有効な非負添字かを変更前に検査する。"""
        if not isinstance(state, int) or isinstance(state, bool):
            raise TypeError(f"{name} must be an integer")
        if not 0 <= state < len(self.next):
            raise IndexError(f"{name} out of range")

    def _step_built(self, state, symbol):
        """build 済み automaton で一 symbol 遷移する内部処理。"""
        while state and symbol not in self.next[state]:
            state = self.fail[state]
        return self.next[state].get(symbol, 0)

    @property
    def output(self):
        """従来互換の全 suffix 出力表を必要時だけ展開して返す。

        build 前は node 数ぶんの空 list。build 後は初回 O(全出力 entry 数) で作り、
        同じ build 期間は同一 list object を返す。外部からの変更結果は保証しない。
        """
        if not self._built:
            return self._prebuild_output
        if self._output_cache is None:
            materialized = []
            for state in range(len(self.next)):
                pattern_ids = self.own_output[state][:]
                link = self.output_link[state]
                while link != -1:
                    pattern_ids.extend(self.own_output[link])
                    link = self.output_link[link]
                materialized.append(pattern_ids)
            self._output_cache = materialized
        return self._output_cache

    def add(self, pattern):
        """pattern を snapshot 登録して ID を返す。build 後は追加不可。期待 O(len)。"""
        if self._built:
            raise RuntimeError("cannot add patterns after build")
        pattern = self._snapshot_pattern(pattern)
        pattern_id = len(self.patterns)
        # snapshot/hash 検査が全て終わってから公開状態を変更する。
        self.patterns.append(pattern)
        state = 0
        for symbol in pattern:
            if symbol not in self.next[state]:
                self.next[state][symbol] = len(self.next)
                self.next.append({})
                self.fail.append(0)
                self.own_output.append([])
                self.output_link.append(-1)
                self._prebuild_output.append([])
            state = self.next[state][symbol]
        self.own_output[state].append(pattern_id)
        self.pattern_terminal.append(state)
        self._output_cache = None
        return pattern_id

    def add_terminal(self, pattern):
        """互換性のため add は pattern ID を返す。本メソッドは終端 state を返す。"""
        pattern_id = self.add(pattern)
        return self.pattern_terminal[pattern_id]

    def terminal_node(self, pattern_id):
        """pattern ID に対応する終端 state。O(1)。"""
        if not isinstance(pattern_id, int) or isinstance(pattern_id, bool):
            raise TypeError("pattern_id must be an integer")
        if not 0 <= pattern_id < len(self.pattern_terminal):
            raise IndexError("pattern_id out of range")
        return self.pattern_terminal[pattern_id]

    def state_of(self, pattern):
        """trie 上で pattern を読んだ state。未登録 prefix なら -1。O(len(pattern))。"""
        pattern = self._snapshot_pattern(pattern)
        state = 0
        for symbol in pattern:
            state = self.next[state].get(symbol, -1)
            if state == -1:
                return -1
        return state

    def build(self):
        """failure/output link を構築し、互換 output cache を無効化する。期待 O(S)。"""
        size = len(self.next)
        self.fail = [0] * size
        self.output_link = [-1] * size
        que = deque()
        order = [0]
        for state in self.next[0].values():
            self.fail[state] = 0
            que.append(state)
        while que:
            state = que.popleft()
            order.append(state)
            fallback = self.fail[state]
            if fallback != 0 and self.own_output[fallback]:
                self.output_link[state] = fallback
            else:
                self.output_link[state] = self.output_link[fallback]
            for symbol, to in self.next[state].items():
                fallback = self.fail[state]
                while fallback and symbol not in self.next[fallback]:
                    fallback = self.fail[fallback]
                self.fail[to] = self.next[fallback].get(symbol, 0)
                que.append(to)
        self._order = order
        self._built = True
        self._output_cache = None
        return self

    def step(self, state, char):
        """state から hashable symbol char を一つ読む。単発最悪 O(state の深さ)。"""
        self._validate_state(state)
        try:
            hash(char)
        except TypeError as error:
            raise TypeError("char must be hashable") from error
        if not self._built:
            self.build()
        return self._step_built(state, char)

    def scan_states(self, text, start_state=0):
        """各文字後の state 列。走査全体で償却 O(len(text)+start state の深さ)。"""
        self._validate_state(start_state, "start_state")
        if not self._built:
            self.build()
        result = []
        state = start_state
        for symbol in text:
            try:
                hash(symbol)
            except TypeError as error:
                raise TypeError("text symbols must be hashable") from error
            state = self._step_built(state, symbol)
            result.append(state)
        return result

    def advance(self, text, start_state=0):
        """全文を読んだ state。走査全体で償却 O(len(text)+start state の深さ)。"""
        self._validate_state(start_state, "start_state")
        if not self._built:
            self.build()
        state = start_state
        for symbol in text:
            try:
                hash(symbol)
            except TypeError as error:
                raise TypeError("text symbols must be hashable") from error
            state = self._step_built(state, symbol)
        return state

    def failure_tree(self):
        """failure link を親とする木の子リスト。root は 0。O(node)。"""
        if not self._built:
            self.build()
        tree = [[] for _ in self.next]
        for state in range(1, len(self.next)):
            tree[self.fail[state]].append(state)
        return tree

    def failure_tree_euler(self):
        """
        failure tree の (tin,tout,parent,order)。部分木は [tin[v],tout[v])。O(node)。

        pattern p が現 state v の suffix であることと、terminal_node(p) が
        failure tree 上で v の祖先であることは同値。重複 pattern は
        同じ terminal state、空 pattern は root を使う。
        """
        tree = self.failure_tree()
        size = len(tree)
        tin = [-1] * size
        tout = [-1] * size
        parent = [-1] * size
        order = []
        stack = [(0, 0)]
        while stack:
            state, phase = stack.pop()
            if phase == 0:
                tin[state] = len(order)
                order.append(state)
                stack.append((state, 1))
                for child in reversed(tree[state]):
                    parent[child] = state
                    stack.append((child, 0))
            else:
                tout[state] = len(order)
        return tin, tout, parent, order

    def iter_output_ids(self, state):
        """state で終わる pattern ID を従来 output と同じ順で遅延列挙する。"""
        self._validate_state(state)
        if not self._built:
            self.build()

        def iterator():
            current = state
            yield from self.own_output[current]
            current = self.output_link[current]
            while current != -1:
                yield from self.own_output[current]
                current = self.output_link[current]

        return iterator()

    def iter_matches(self, text):
        """find_all と同順で遅延列挙。同じ境界では長い pattern から。空 pattern があるときだけ境界ごとに ID 昇順に並べる。"""
        if not self._built:
            self.build()
        empty_ids = tuple(self.own_output[0])

        def iterator():
            state = 0
            if empty_ids:
                for pattern_id in empty_ids:
                    yield 0, pattern_id
            for boundary, symbol in enumerate(text, 1):
                try:
                    hash(symbol)
                except TypeError as error:
                    raise TypeError("text symbols must be hashable") from error
                state = self._step_built(state, symbol)
                if empty_ids:
                    matched_ids = list(self.iter_output_ids(state)) if state else []
                    matched_ids.extend(empty_ids)
                    matched_ids.sort()
                    for pattern_id in matched_ids:
                        yield boundary - len(self.patterns[pattern_id]), pattern_id
                elif state:
                    for pattern_id in self.iter_output_ids(state):
                        yield boundary - len(self.patterns[pattern_id]), pattern_id

        return iterator()

    def find_all(self, text):
        """(開始 index, pattern_id) を終了境界順に列挙する。同じ境界で終わるものは、長い pattern から（空 pattern を登録しているときだけ ID 昇順）。"""
        return list(self.iter_matches(text))

    def count_each(self, text):
        """各 pattern の出現回数（重なりを含む）を O(|text|+node+pattern数) で返す。"""
        if not self._built:
            self.build()
        visits = [0] * len(self.next)
        state = 0
        text_length = 0
        for symbol in text:
            try:
                hash(symbol)
            except TypeError as error:
                raise TypeError("text symbols must be hashable") from error
            state = self._step_built(state, symbol)
            visits[state] += 1
            text_length += 1
        for v in reversed(self._order[1:]):
            visits[self.fail[v]] += visits[v]
        answer = [0] * len(self.patterns)
        for node, ids in enumerate(self.own_output):
            for pattern_id in ids:
                answer[pattern_id] = text_length + 1 if node == 0 else visits[node]
        return answer

    def count_total(self, text):
        """全 pattern ID の出現回数の総和を返す。O(|text|+V+K)。"""
        return sum(self.count_each(text))

    def contains_any(self, text):
        """いずれかの登録 pattern が text に現れれば True。見つかり次第終了する。"""
        if not self._built:
            self.build()
        if self.own_output[0]:
            return True
        state = 0
        for symbol in text:
            try:
                hash(symbol)
            except TypeError as error:
                raise TypeError("text symbols must be hashable") from error
            state = self._step_built(state, symbol)
            if self.own_output[state] or self.output_link[state] != -1:
                return True
        return False

    def transition_table(self, alphabet):
        """失敗リンクを前もって付け替えた全遷移表（goto 関数）を、平らな list で返す。

        alphabet は文字（symbol）の列（例: "abcdefghijklmnopqrstuvwxyz"、[0, 1] など）。σ = len(alphabet)。
        戻り値 table は長さ (state 数)×σ の list で、
        ``table[v * σ + c]`` = state v から ``alphabet[c]`` を読んだ先（``step(v, alphabet[c])`` と同じ）。
        alphabet に無い文字でつながる trie の辺は無視する（その文字を読むことはない前提）。

        作り方：BFS 順に、失敗リンク先の行を写してから trie の子だけ上書きする。O(σ × state 数)。
        step は失敗リンクをたどるので、任意の state から何度も遷移する用途（スタックで state を
        戻す消去問題、オートマトン上の DP・行列累乗）では、この表を使うと 1 文字 O(1) になる。
        build 前なら build する。alphabet に重複があれば ValueError。
        """
        if not self._built:
            self.build()
        alpha = list(alphabet)
        sigma = len(alpha)
        pos = {}
        for i, ch in enumerate(alpha):
            if ch in pos:
                raise ValueError("alphabet must not contain duplicates")
            pos[ch] = i
        nxt = self.next
        fail = self.fail
        size = len(nxt)
        table = [0] * (size * sigma)
        for v in self._order:
            row = v * sigma
            if v:
                f = fail[v] * sigma
                table[row:row + sigma] = table[f:f + sigma]
            for ch, to in nxt[v].items():
                c = pos.get(ch)
                if c is not None:
                    table[row + c] = to
        return table

    def dfa_table(self, alphabet):
        """オートマトン上の DP 用に (trans, bad) を返す。状態数は len(trans)。

        ``trans[v][c]`` = state v から ``alphabet[c]`` を読んだ先（失敗リンク込みの全遷移、O(1) で引ける）。
        ``bad[v]`` = state v を読み終えた時点で、どれかの pattern が終わっているか
        （output link 込み。つまり ``iter_output_ids(v)`` が空でないか）。
        空 pattern を登録した場合は state 0 だけが bad になる（iter_output_ids と同じ扱い）。

        禁止パターンを含まない文字列の数え上げ（bad な state に入る遷移を捨てる DP）、
        出現回数の最大化、含むパターン集合を bit で持つ DP などの最初の表づくりに使う。
        O(σ × state 数)。alphabet の意味は ``transition_table`` と同じ。

        >>> ac = AhoCorasick(["ab", "b"]); trans, bad = ac.dfa_table("ab")
        >>> trans, bad      # state: 0 = 根, 1 = "a", 2 = "ab", 3 = "b"
        ([[1, 3], [1, 2], [1, 3], [1, 3]], [False, False, True, True])
        """
        table = self.transition_table(alphabet)
        sigma = len(table) // len(self.next) if self.next else 0
        size = len(self.next)
        trans = [table[v * sigma:(v + 1) * sigma] for v in range(size)]
        own = self.own_output
        link = self.output_link
        bad = [bool(own[v]) or link[v] != -1 for v in range(size)]
        return trans, bad


def s_aho_corasick(patterns=()):
    return AhoCorasick(patterns)


class SuffixAutomaton:
    """文字列末尾へ online 追加できる Suffix Automaton。

    状態数・構築時間は文字列長 N に対して期待 O(N)。異なる非空部分文字列の個数と
    長さ総和を extend 時に差分更新して O(1) で返す。辞書順 cache は
    ``prepare_lexicographic`` または最初の辞書順照会で作り、``kth_substring`` と
    ``substring_rank`` を互いに逆の 1-indexed 順位として扱う。空文字列は辞書順列挙に
    含めない。

    public ``text`` は従来どおり str だが、内部では文字 list を保持し、読取り時だけ
    join するため online extend の二乗連結を避ける。成功した extend は出現数・辞書順
    cache を無効化し、失敗した extend は全状態と cache/version を変更しない。
    """

    def __init__(self, text=""):
        self.next = [{}]
        self.link = [-1]
        self.length = [0]
        self.first_pos = [-1]
        self._terminal_occ = [0]
        self.occ = [0]
        self.last = 0
        self._text_chars = []
        self._text_cache = ""
        self._occ_ready = False
        self._distinct_count = 0
        self._distinct_length_sum = 0
        self._version = 0
        self._lex_version = -1
        self._lex_paths = None
        self._lex_transitions = None
        for char in text:
            self.extend(char)

    @property
    def text(self):
        """構築文字列を str で返す。extend 後の初回だけ O(N) で join する。"""
        if self._text_cache is None:
            self._text_cache = "".join(self._text_chars)
        return self._text_cache

    def extend(self, char):
        """末尾へ1文字の str を追加し、新しい current state を返す。期待償却 O(1)。"""
        if not isinstance(char, str):
            raise TypeError("char must be a string")
        if len(char) != 1:
            raise ValueError("char must have length one")
        cur = len(self.next)
        self.next.append({})
        self.length.append(self.length[self.last] + 1)
        self.link.append(0)
        self.first_pos.append(self.length[cur] - 1)
        self._terminal_occ.append(1)
        self.occ.append(1)
        p = self.last
        while p != -1 and char not in self.next[p]:
            self.next[p][char] = cur
            p = self.link[p]
        if p == -1:
            self.link[cur] = 0
        else:
            q = self.next[p][char]
            if self.length[p] + 1 == self.length[q]:
                self.link[cur] = q
            else:
                clone = len(self.next)
                self.next.append(self.next[q].copy())
                self.length.append(self.length[p] + 1)
                self.link.append(self.link[q])
                self.first_pos.append(self.first_pos[q])
                self._terminal_occ.append(0)
                self.occ.append(0)
                while p != -1 and self.next[p].get(char) == q:
                    self.next[p][char] = clone
                    p = self.link[p]
                self.link[q] = self.link[cur] = clone
        self.last = cur
        self._text_chars.append(char)
        self._text_cache = None
        lower = self.length[self.link[cur]]
        upper = self.length[cur]
        self._distinct_count += upper - lower
        self._distinct_length_sum += (
            upper * (upper + 1) // 2 - lower * (lower + 1) // 2
        )
        self._occ_ready = False
        self._version += 1
        self._lex_version = -1
        self._lex_paths = None
        self._lex_transitions = None
        return cur

    def _state(self, pattern):
        state = 0
        for char in pattern:
            state = self.next[state].get(char, -1)
            if state == -1:
                break
        return state

    def contains(self, pattern):
        return self._state(pattern) != -1

    __contains__ = contains

    def build_occurrence_count(self):
        if self._occ_ready:
            return self.occ
        size = len(self.next)
        buckets = [0] * (len(self._text_chars) + 1)
        for value in self.length:
            buckets[value] += 1
        for i in range(1, len(buckets)):
            buckets[i] += buckets[i - 1]
        order = [0] * size
        for state in range(size - 1, -1, -1):
            value = self.length[state]
            buckets[value] -= 1
            order[buckets[value]] = state
        occ = self._terminal_occ[:]
        for state in reversed(order[1:]):
            occ[self.link[state]] += occ[state]
        self.occ = occ
        self._occ_ready = True
        return occ

    def count(self, pattern):
        if not pattern:
            return len(self._text_chars) + 1
        state = self._state(pattern)
        if state == -1:
            return 0
        return self.build_occurrence_count()[state]

    def first_occurrence(self, pattern):
        """pattern の最左の出現位置（str.find と同じ）を返す。存在しなければ -1、空 pattern は 0。"""
        if not pattern:
            return 0
        state = self._state(pattern)
        return -1 if state == -1 else self.first_pos[state] - len(pattern) + 1

    def count_distinct_substrings(self):
        """異なる非空部分文字列数を O(1) で返す。"""
        return self._distinct_count

    def sum_distinct_substring_lengths(self):
        """異なる非空部分文字列すべての長さ総和を O(1) で返す。"""
        return self._distinct_length_sum

    def longest_common_substring(self, other):
        """構築文字列と other の最長共通部分文字列を1つ返す。O(len(other))。"""
        state = current_length = best_length = best_end = 0
        for i, char in enumerate(other):
            while state and char not in self.next[state]:
                state = self.link[state]
                current_length = min(current_length, self.length[state])
            if char in self.next[state]:
                state = self.next[state][char]
                current_length += 1
            else:
                state = current_length = 0
            if current_length > best_length:
                best_length = current_length
                best_end = i + 1
        return other[best_end - best_length:best_end]

    def prepare_lexicographic(self):
        """辞書順遷移と各 state からの非空 path 数を cache する。期待 O(V log σ)。

        state を長さの降順（数え上げソート）に処理する。あわせて、出次数 1 の state が続く
        「一本道」の行き先と長さを記録し、kth_substring が一本道を 1 回で飛ばせるようにする。
        PyPy で N = 2×10^5 のとき 約 0.5 秒。
        """
        if self._lex_version == self._version:
            return self
        nxt = self.next
        length = self.length
        size = len(nxt)
        maxlen = len(self._text_chars)
        cnt = [0] * (maxlen + 2)
        for v in length:
            cnt[v] += 1
        for i in range(1, maxlen + 2):
            cnt[i] += cnt[i - 1]
        order = [0] * size
        for state in range(size - 1, -1, -1):
            v = length[state]
            cnt[v] -= 1
            order[cnt[v]] = state
        paths = [0] * size
        chain_to = [-1] * size      # 出次数 1 の state から一本道をたどって最初に出次数 ≠ 1 になる state
        chain_len = [0] * size      # その一本道の辺の数
        for idx in range(size - 1, -1, -1):
            state = order[idx]
            d = nxt[state]
            if len(d) == 1:
                for to in d.values():
                    paths[state] = 1 + paths[to]
                    if len(nxt[to]) == 1:
                        chain_to[state] = chain_to[to]
                        chain_len[state] = chain_len[to] + 1
                    else:
                        chain_to[state] = to
                        chain_len[state] = 1
            else:
                total = 0
                for to in d.values():
                    total += 1 + paths[to]
                paths[state] = total
        transitions = []
        for state in range(size):
            d = nxt[state]
            if len(d) == 1:
                for ch, to in d.items():
                    transitions.append(((ch,), (to,), (1 + paths[to],)))
                continue
            items = sorted(d.items())
            chars = tuple(char for char, _to in items)
            targets = tuple(to for _char, to in items)
            cumulative = []
            total = 0
            for to in targets:
                total += 1 + paths[to]
                cumulative.append(total)
            transitions.append((chars, targets, tuple(cumulative)))
        self._lex_paths = paths
        self._lex_transitions = transitions
        self._g07_chain = (chain_to, chain_len)
        self._lex_version = self._version
        return self

    def kth_substring(self, k):
        """異なる非空部分文字列を辞書順に並べた 1-indexed k 番目。

        出次数 1 の state が続く一本道は 1 回で飛ばし、最後に元の文字列の区間を切り出す
        （答えの長さに比例する文字ごとの下降をしない）。1 回 O(分岐の数 × log σ + 答えの長さ)
        （最後の切り出しは C の速さ）。
        """
        if not isinstance(k, int) or isinstance(k, bool):
            raise TypeError("k must be an integer")
        if k <= 0:
            raise IndexError("k is 1-indexed")
        self.prepare_lexicographic()
        paths = self._lex_paths
        if k > paths[0]:
            raise IndexError("k is out of range")
        trans = self._lex_transitions
        chain_to, chain_len = self._g07_chain
        nxt = self.next
        state = 0
        cur = 0                     # ここまでに読んだ長さ
        while True:
            if len(nxt[state]) == 1 and state != 0:
                c = chain_len[state]
                if k <= c:
                    w = chain_to[state]
                    end = self.first_pos[w] - (c - k)
                    cur += k
                    return self.text[end - cur + 1:end + 1]
                k -= c
                cur += c
                state = chain_to[state]
                continue
            chars, targets, cumulative = trans[state]
            index = bisect_left(cumulative, k)
            if index:
                k -= cumulative[index - 1]
            k -= 1
            cur += 1
            state = targets[index]
            if k == 0:
                end = self.first_pos[state]
                return self.text[end - cur + 1:end + 1]

    def substring_rank(self, pattern):
        """非空 pattern の1-indexed辞書順順位。不在または空なら None。"""
        if not isinstance(pattern, str):
            raise TypeError("pattern must be a string")
        if not pattern:
            return None
        self.prepare_lexicographic()
        state = 0
        rank = 0
        for char in pattern:
            chars, targets, cumulative = self._lex_transitions[state]
            index = bisect_left(chars, char)
            if index == len(chars) or chars[index] != char:
                return None
            if index:
                rank += cumulative[index - 1]
            rank += 1
            state = targets[index]
        return rank

    def longest_repeated_substring(self, min_occurrences=2):
        if min_occurrences <= 1:
            return self.text
        occ = self.build_occurrence_count()
        state = max((v for v in range(1, len(self.next)) if occ[v] >= min_occurrences),
                    key=lambda v: self.length[v], default=0)
        length = self.length[state]
        end = self.first_pos[state] + 1
        return self.text[end - length:end]


def s_suffix_automaton(text=""):
    return SuffixAutomaton(text)


class PalindromicTree:
    """文字列の異なる回文をオンラインで管理する Palindromic Tree / Eertree。

    node 0 は長さ -1 の仮想根、node 1 は長さ 0 の空回文根、実回文は node 2
    以降である。追加文字は厳密に ``type(char) is str`` かつ長さ1とし、失敗時は
    一切状態を変更しない。各追加で新しい実回文 node は高々1個なので node 数は
    文字列長 N に対して O(N)。suffix link は必ず既存の小さい node IDを指す。

    出現回数は ``_terminal_occ`` から必要時だけ逆node順に O(V) 伝播し、変更不能な
    private cacheへ保存する。公開取得は毎回copyであり、add成功時は関連cacheを
    完全invalidateする。
    """

    def __init__(self, text=""):
        """1文字strの有限iterableを検証し、左から追加して構築する。"""
        try:
            characters = list(text)
        except TypeError as exc:
            raise TypeError("text must be a finite iterable of one-character str") from exc
        for char in characters:
            self._check_char(char)

        self.next = [{}, {}]
        self.length = [-1, 0]
        self.link = [0, 0]
        self.suffix_depth = [0, 0]
        self._terminal_occ = [0, 0]
        self._occ_cache = None
        self._occ_total_cache = None
        self._hist_cache = None
        self.first_end = [-1, -1]
        self.last = 1
        self._longest_node = 1
        self.last_add_created = False
        self.text = []
        for char in characters:
            self.add(char)

    def __len__(self):
        """追加済み文字数を返す。"""
        return len(self.text)

    @staticmethod
    def _check_char(char):
        """追加文字を厳密な1文字strとして検証する。"""
        if type(char) is not str:
            raise TypeError("char must be a str (not a subclass) of length 1")
        if len(char) != 1:
            raise ValueError("char must have length 1")
        return char

    def _check_node(self, node):
        """rootを含むnode IDをbool除外int・範囲内として検証する。"""
        if type(node) is not int:
            raise TypeError("node must be an int other than bool")
        if not 0 <= node < len(self.next):
            raise IndexError("palindromic-tree node is out of range")
        return node

    def add(self, char):
        """1文字を末尾へ追加し、新しい最長回文suffix node IDを返す。"""
        node, _created = self.add_with_status(char)
        return node

    def add_with_status(self, char):
        """1文字を追加し、``(最長suffix node, 新nodeを作ったか)`` を返す。"""
        char = self._check_char(char)
        pos = len(self.text)
        current = self.last
        while True:
            left = pos - 1 - self.length[current]
            if left == pos or (left >= 0 and self.text[left] == char):
                break
            current = self.link[current]

        existing = self.next[current].get(char)
        if existing is not None:
            self.text.append(char)
            self.last = existing
            self._terminal_occ[existing] += 1
            self._occ_cache = None
            self._occ_total_cache = None
            self._hist_cache = None
            self.last_add_created = False
            return existing, False

        node_length = self.length[current] + 2
        suffix_link = 1
        if node_length > 1:
            fallback = self.link[current]
            while True:
                left = pos - 1 - self.length[fallback]
                if left == pos or (left >= 0 and self.text[left] == char):
                    break
                fallback = self.link[fallback]
            suffix_link = self.next[fallback][char]

        node = len(self.next)
        self.text.append(char)
        self.next.append({})
        self.length.append(node_length)
        self.link.append(suffix_link)
        self.suffix_depth.append(1 + self.suffix_depth[suffix_link])
        self._terminal_occ.append(1)
        self.first_end.append(pos)
        self.next[current][char] = node
        self.last = node
        if node_length > self.length[self._longest_node]:
            self._longest_node = node
        self._occ_cache = None
        self._occ_total_cache = None
        self._hist_cache = None
        self.last_add_created = True
        return node, True

    def _ensure_occurrence_count(self):
        """出現数cacheを逆node ID順にO(V)で構築し、内部tupleを返す。"""
        if self._occ_cache is None:
            counts = self._terminal_occ[:]
            for node in range(len(self.next) - 1, 1, -1):
                counts[self.link[node]] += counts[node]
            self._occ_cache = tuple(counts)
            self._occ_total_cache = sum(counts[2:])
        return self._occ_cache

    def build_occurrence_count(self):
        """各nodeの全出現回数を新しいlistで返す。内部cacheは公開しない。"""
        return list(self._ensure_occurrence_count())

    @property
    def occ(self):
        """``build_occurrence_count`` と同じ防御的list copyを返す互換property。"""
        return self.build_occurrence_count()

    def count_distinct(self):
        """異なる非空回文部分文字列の個数を返す。"""
        return len(self.next) - 2

    def count_total(self):
        """重なりを含む全回文部分文字列の個数を返す。"""
        self._ensure_occurrence_count()
        return self._occ_total_cache

    def palindrome_range(self, node):
        """node回文が最初に現れた代表区間 ``[left,right)`` を返す。"""
        node = self._check_node(node)
        if node < 2:
            return 0, 0
        right = self.first_end[node] + 1
        return right - self.length[node], right

    def palindrome(self, node):
        """nodeに対応する回文文字列を返す。二つのrootは空文字列。"""
        left, right = self.palindrome_range(node)
        return "".join(self.text[left:right])

    def all_palindromes(self, *, with_count=False):
        """全異なる非空回文を作成順に列挙し、任意で出現数も付ける。"""
        if type(with_count) is not bool:
            raise TypeError("with_count must be a bool")
        if with_count:
            counts = self._ensure_occurrence_count()
            return [
                (self.palindrome(node), counts[node])
                for node in range(2, len(self.next))
            ]
        return [self.palindrome(node) for node in range(2, len(self.next))]

    def longest(self):
        """最長回文を返す。同長なら最初にnode化された回文を選ぶ。"""
        return self.palindrome(self._longest_node)

    def suffix_palindrome_nodes(self):
        """現在prefixの非空回文suffix nodeを長い順の新しいlistで返す。"""
        result = []
        node = self.last
        while node >= 2:
            result.append(node)
            node = self.link[node]
        return result

    def longest_suffix_length(self):
        """現在prefixの最長回文suffix長をO(1)で返す。空なら0。"""
        return self.length[self.last]

    def count_suffix_palindromes(self):
        """現在prefix末尾で終わる異なる非空回文数をO(1)で返す。"""
        return self.suffix_depth[self.last]

    def suffix_palindromes(self):
        """現在prefixの非空回文suffix文字列を長い順に返す。"""
        return [self.palindrome(node) for node in self.suffix_palindrome_nodes()]

    def length_histograms(self):
        """長さ別の異なる種類数と全出現数を防御的list 2本で返す。"""
        if self._hist_cache is None:
            counts = self._ensure_occurrence_count()
            distinct = [0] * (len(self.text) + 1)
            occurrences = [0] * (len(self.text) + 1)
            for node in range(2, len(self.next)):
                length = self.length[node]
                distinct[length] += 1
                occurrences[length] += counts[node]
            self._hist_cache = (tuple(distinct), tuple(occurrences))
        return list(self._hist_cache[0]), list(self._hist_cache[1])


Eertree = PalindromicTree


def s_palindromic_tree(text=""):
    """文字列から ``PalindromicTree`` を構築して返す短縮factory。"""
    return PalindromicTree(text)

# ============================================================
# Ultimate Extension: Compact String Helpers (s_)
# ============================================================

def s_prefix_function(s):
    """KMP の prefix function。pi[i]=s[:i+1] の最長 proper border 長。O(N)。"""
    n = len(s)
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    return pi


def s_border_lengths(s, *, include_full=False):
    """prefix かつ suffix である長さを昇順で返す。O(N)。"""
    if not s:
        return [0] if include_full else []
    pi = s_prefix_function(s)
    result = []
    length = len(s) if include_full else pi[-1]
    while length:
        result.append(length)
        length = pi[length - 1]
    result.reverse()
    return result


def s_periods(s):
    """s[i]=s[i-period] (i>=period) を満たす全 period を昇順で返す。len(s) も含む。"""
    n = len(s)
    if n == 0:
        return [0]
    return sorted(n - border for border in [0] + s_border_lengths(s))


def s_min_period(s, *, require_full_repetition=True):
    """最小周期。require_full_repetition=True では同じブロックの完全反復のみ認める。"""
    if not s:
        return 0
    period = len(s) - s_prefix_function(s)[-1]
    if require_full_repetition and len(s) % period:
        return len(s)
    return period


def s_min_rotation_index(s):
    """辞書順最小の巡回シフト開始 index（2ポインタによる最小表現法）。空列は 0。同じ最小が複数あれば最小の index。O(N)。"""
    n = len(s)
    if n == 0:
        return 0
    doubled = s + s
    i, j, k = 0, 1, 0
    while i < n and j < n and k < n:
        a, b = doubled[i + k], doubled[j + k]
        if a == b:
            k += 1
            continue
        if a > b:
            i += k + 1
            if i <= j:
                i = j + 1
        else:
            j += k + 1
            if j <= i:
                j = i + 1
        k = 0
    return min(i, j)


def s_min_rotation(s):
    """辞書順最小の巡回シフト。O(N)。"""
    index = s_min_rotation_index(s)
    return s[index:] + s[:index]


def s_lyndon_factorization(s, *, return_ranges=False):
    """Duval algorithm による Lyndon 分解。O(N)。"""
    n = len(s)
    ranges = []
    i = 0
    while i < n:
        j, k = i + 1, i
        while j < n and s[k] <= s[j]:
            k = i if s[k] < s[j] else k + 1
            j += 1
        length = j - k
        while i <= k:
            ranges.append((i, i + length))
            i += length
    return ranges if return_ranges else [s[left:right] for left, right in ranges]


def s_min_subsequence(s, length):
    """長さ length の部分列のうち辞書順最小のものを O(N) で返す。"""
    if not 0 <= length <= len(s):
        raise ValueError("require 0 <= length <= len(s)")
    remove = len(s) - length
    stack = []
    for char in s:
        while remove and stack and stack[-1] > char:
            stack.pop()
            remove -= 1
        stack.append(char)
    result = stack[:length]
    return "".join(result) if isinstance(s, str) else result


# ============================================================
# Ultimate Extension: Assignment / Global Min-Cut (g_)
# ============================================================

def g_hungarian(cost):
    """
    長方形コスト行列の最小重み割当。各行に異なる列を1つ割り当てる。
    行数 N <= 列数 M が必要。戻り値は (minimum_cost, assigned_column_per_row)。O(N^2 M)。
    """
    n = len(cost)
    if n == 0:
        return 0, []
    m = len(cost[0])
    if any(len(row) != m for row in cost):
        raise ValueError("cost matrix must be rectangular")
    if n > m:
        raise ValueError("g_hungarian requires rows <= columns")
    u = [0] * (n + 1)
    v = [0] * (m + 1)
    matched_row = [0] * (m + 1)
    way = [0] * (m + 1)
    for row in range(1, n + 1):
        matched_row[0] = row
        min_value = [math.inf] * (m + 1)
        used = [False] * (m + 1)
        column = 0
        while True:
            used[column] = True
            current_row = matched_row[column]
            delta = math.inf
            next_column = 0
            for candidate in range(1, m + 1):
                if used[candidate]:
                    continue
                reduced = cost[current_row - 1][candidate - 1] - u[current_row] - v[candidate]
                if reduced < min_value[candidate]:
                    min_value[candidate] = reduced
                    way[candidate] = column
                if min_value[candidate] < delta:
                    delta = min_value[candidate]
                    next_column = candidate
            for candidate in range(m + 1):
                if used[candidate]:
                    u[matched_row[candidate]] += delta
                    v[candidate] -= delta
                else:
                    min_value[candidate] -= delta
            column = next_column
            if matched_row[column] == 0:
                break
        while True:
            previous = way[column]
            matched_row[column] = matched_row[previous]
            column = previous
            if column == 0:
                break
    assignment = [-1] * n
    for column in range(1, m + 1):
        if matched_row[column]:
            assignment[matched_row[column] - 1] = column - 1
    return sum(cost[row][column] for row, column in enumerate(assignment)), assignment


def g_hungarian_max(weight):
    """最大重み割当。返り値は (maximum_weight, assigned_column_per_row)。"""
    value, assignment = g_hungarian([[-x for x in row] for row in weight])
    return -value, assignment


def g_stoer_wagner(weight):
    """
    非負重み無向グラフの global minimum cut（Stoer-Wagner）。O(V^3)。
    weight は対称隣接行列（非対称・負の重み・非正方は ValueError）。
    戻り値 (cut_weight, one_side_vertices)。
    """
    n = len(weight)
    if n == 0:
        return 0, []
    if any(len(row) != n for row in weight):
        raise ValueError("weight must be a square matrix")
    if any(weight[i][j] < 0 for i in range(n) for j in range(n)):
        raise ValueError("g_stoer_wagner requires non-negative weights")
    if any(weight[i][j] != weight[j][i] for i in range(n) for j in range(i)):
        raise ValueError("weight must be symmetric")
    matrix = [row[:] for row in weight]
    vertices = list(range(n))
    groups = [{v} for v in range(n)]
    best_weight = math.inf
    best_side = {0}
    while len(vertices) > 1:
        used = [False] * n
        connection = [0] * n
        previous = -1
        for phase_index in range(len(vertices)):
            selected = max((v for v in vertices if not used[v]), key=connection.__getitem__)
            used[selected] = True
            if phase_index == len(vertices) - 1:
                if connection[selected] < best_weight:
                    best_weight = connection[selected]
                    best_side = groups[selected].copy()
                if previous != -1:
                    for v in vertices:
                        if v != selected and v != previous:
                            matrix[previous][v] += matrix[selected][v]
                            matrix[v][previous] = matrix[previous][v]
                    groups[previous].update(groups[selected])
                    vertices.remove(selected)
                break
            previous = selected
            for v in vertices:
                if not used[v]:
                    connection[v] += matrix[selected][v]
    return (0 if best_weight == math.inf else best_weight), sorted(best_side)


class RangeChminPointGet:
    """range_chmin([l,r),x) と point_get(i) をともに O(log N) で行う。"""

    def __init__(self, n, initial=math.inf):
        if n < 0:
            raise ValueError("n must be non-negative")
        self.n = n
        self.initial = initial
        self.size = 1 << (n - 1).bit_length() if n > 1 else 1
        self.lazy = [initial] * (2 * self.size)

    def range_chmin(self, left, right, value):
        if not 0 <= left <= right <= self.n:
            raise IndexError("require 0 <= left <= right <= n")
        left += self.size
        right += self.size
        while left < right:
            if left & 1:
                self.lazy[left] = min(self.lazy[left], value)
                left += 1
            if right & 1:
                right -= 1
                self.lazy[right] = min(self.lazy[right], value)
            left >>= 1
            right >>= 1

    apply = range_chmin

    def point_get(self, index):
        if not 0 <= index < self.n:
            raise IndexError("index out of range")
        node = index + self.size
        answer = self.initial
        while node:
            answer = min(answer, self.lazy[node])
            node >>= 1
        return answer

    get = point_get

    def to_list(self):
        return [self.point_get(i) for i in range(self.n)]


def g_kruskal(n, edges, *, maximum=False):
    """
    Kruskal で全域木を作り (weight, original_edge_ids) を返す。
    非連結なら (None, forest_edge_ids)。自己辺・平行辺・負辺を許す。
    同重みは元 edge ID で安定化。O(E log E)。
    重みがすべて int なら「重み×E＋辺番号」の整数 1 つで並べ替える（PyPy で E = 4×10^5 のとき
    約 1.65 秒 → 約 0.25 秒）。maximum=True なら最大全域木（同重みはやはり辺番号の小さい順）。
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    U = []
    V = []
    W = []
    for edge in edges:
        if len(edge) < 3:
            raise ValueError("each edge must contain (u,v,weight)")
        u, v, weight = edge[:3]
        if not 0 <= u < n or not 0 <= v < n:
            raise IndexError("edge endpoint out of range")
        U.append(u)
        V.append(v)
        W.append(weight)
    E = len(W)
    if all(type(w) is int for w in W):
        if maximum:
            keys = [-W[i] * E + i for i in range(E)]
        else:
            keys = [W[i] * E + i for i in range(E)]
        keys.sort()
        order = [k % E for k in keys] if E else []
    else:
        if maximum:
            order = sorted(range(E), key=lambda i: -W[i])
        else:
            order = sorted(range(E), key=W.__getitem__)
    parent = [-1] * n
    need = max(0, n - 1)
    chosen = []
    total = 0
    if need:
        for edge_id in order:
            ru = U[edge_id]
            while parent[ru] >= 0:
                ru = parent[ru]
            rv = V[edge_id]
            while parent[rv] >= 0:
                rv = parent[rv]
            if ru == rv:
                continue
            if parent[ru] > parent[rv]:
                ru, rv = rv, ru
            parent[ru] += parent[rv]
            parent[rv] = ru
            total += W[edge_id]
            chosen.append(edge_id)
            if len(chosen) == need:
                break
    return (total if len(chosen) == need else None), chosen


class MSTSensitivity:
    """
    MST の全辺感度解析。構築 O((N+M)log^2 N)、重み仮変更 query O(1)。

    tree edge にはその cut を跨ぐ最小 replacement weight、non-tree edge には
    それを強制使用するときの path maximum を前計算する。同重み・平行辺・
    自己辺・負辺に対応。非連結グラフは ValueError。
    """

    def __init__(self, n, edges):
        self.n = n
        self.edges = [tuple(edge[:3]) for edge in edges]
        self.m = len(self.edges)
        mst_weight, chosen = g_kruskal(n, self.edges)
        if mst_weight is None:
            raise ValueError("graph must be connected")
        self.mst_weight = mst_weight
        self.mst_edge_ids = chosen
        self.in_mst = [False] * self.m
        for edge_id in chosen:
            self.in_mst[edge_id] = True
        if n <= 1:
            self.replacement_weight = [math.inf] * self.m
            self.path_max_weight = [None] * self.m
            self.force_mst_cost = [mst_weight if self.in_mst[i] else math.inf for i in range(self.m)]
            self.remove_mst_cost = [math.inf if self.in_mst[i] else mst_weight for i in range(self.m)]
            return

        graph = [[] for _ in range(n)]
        for edge_id in chosen:
            u, v, weight = self.edges[edge_id]
            graph[u].append((v, weight, edge_id))
            graph[v].append((u, weight, edge_id))
        parent = [-1] * n
        depth = [0] * n
        parent_edge = [-1] * n
        parent_weight = [-math.inf] * n
        order = [0]
        parent[0] = 0
        for v in order:
            for to, weight, edge_id in graph[v]:
                if to == parent[v]:
                    continue
                parent[to] = v
                depth[to] = depth[v] + 1
                parent_edge[to] = edge_id
                parent_weight[to] = weight
                order.append(to)
        size = [1] * n
        heavy = [-1] * n
        for v in reversed(order):
            best_size = 0
            for to, weight, edge_id in graph[v]:
                if parent[to] != v:
                    continue
                size[v] += size[to]
                if size[to] > best_size:
                    best_size = size[to]
                    heavy[v] = to
        head = [-1] * n
        position = [-1] * n
        stack = [(0, 0)]
        current = 0
        while stack:
            v, path_head = stack.pop()
            while v != -1:
                head[v] = path_head
                position[v] = current
                current += 1
                for to, weight, edge_id in reversed(graph[v]):
                    if parent[to] == v and to != heavy[v]:
                        stack.append((to, to))
                v = heavy[v]

        base = [-math.inf] * n
        for v in range(1, n):
            base[position[v]] = parent_weight[v]
        seg_size = 1 << (n - 1).bit_length()
        max_tree = [-math.inf] * (2 * seg_size)
        max_tree[seg_size:seg_size + n] = base
        for node in range(seg_size - 1, 0, -1):
            max_tree[node] = max(max_tree[node * 2], max_tree[node * 2 + 1])

        def range_max(left, right):
            answer = -math.inf
            left += seg_size
            right += seg_size
            while left < right:
                if left & 1:
                    answer = max(answer, max_tree[left])
                    left += 1
                if right & 1:
                    right -= 1
                    answer = max(answer, max_tree[right])
                left >>= 1
                right >>= 1
            return answer

        replacement_tree = RangeChminPointGet(n)

        def path_ranges(u, v):
            ranges = []
            while head[u] != head[v]:
                if depth[head[u]] < depth[head[v]]:
                    u, v = v, u
                ranges.append((position[head[u]], position[u] + 1))
                u = parent[head[u]]
            if depth[u] > depth[v]:
                u, v = v, u
            if position[u] + 1 < position[v] + 1:
                ranges.append((position[u] + 1, position[v] + 1))
            return ranges

        path_max = [None] * self.m
        for edge_id, (u, v, weight) in enumerate(self.edges):
            if self.in_mst[edge_id] or u == v:
                continue
            maximum = -math.inf
            for left, right in path_ranges(u, v):
                maximum = max(maximum, range_max(left, right))
                replacement_tree.range_chmin(left, right, weight)
            path_max[edge_id] = maximum

        replacement = [math.inf] * self.m
        for v in range(1, n):
            replacement[parent_edge[v]] = replacement_tree.point_get(position[v])
        self.replacement_weight = replacement
        self.path_max_weight = path_max
        self.force_mst_cost = [math.inf] * self.m
        self.remove_mst_cost = [mst_weight] * self.m
        for edge_id, (u, v, weight) in enumerate(self.edges):
            if self.in_mst[edge_id]:
                self.force_mst_cost[edge_id] = mst_weight
                repl = replacement[edge_id]
                self.remove_mst_cost[edge_id] = (math.inf if repl == math.inf
                                                 else mst_weight - weight + repl)
            elif u != v:
                self.force_mst_cost[edge_id] = mst_weight + weight - path_max[edge_id]

    def query_changed_weight(self, edge_id, new_weight):
        """1辺の重みだけを仮変更し (new_mst_cost, edge_can_be_in_some_mst) 。O(1)。"""
        if edge_id < 0:
            raise IndexError("edge id out of range")
        u, v, old_weight = self.edges[edge_id]
        if self.in_mst[edge_id]:
            keep = self.mst_weight - old_weight + new_weight
            alternative = self.remove_mst_cost[edge_id]
            return min(keep, alternative), keep <= alternative
        if u == v:
            return self.mst_weight, False
        force = self.mst_weight + new_weight - self.path_max_weight[edge_id]
        return min(self.mst_weight, force), force <= self.mst_weight


def g_mst_sensitivity(n, edges):
    return MSTSensitivity(n, edges)


# ============================================================
# Autocomplete Prefix Index / Compatibility Aliases
# ============================================================
#
#   l_     : list・配列・部分列・静的区間操作
#   s_     : string・文字列アルゴリズム
#   g_     : general graph・最短路・フロー・閉路・割当
#   grid_  : 2次元グリッド
#   nt_    : number theory・整数論
#   geo_   : geometry・幾何
#   ds_    : data structure のクラス
#   bs_    : binary search
#   opt_   : optimization search
#
# 定番の短い名前・クラス名はそのまま残し、上記 prefix からも Tab 補完できる。

# --- graph classes ---
g_SCC = SCC
g_TwoSAT = TwoSAT
g_LowLink = LowLink
g_Dinic = Dinic
g_MinCostFlow = MinCostFlow
g_LowerBoundFlow = LowerBoundFlow
g_HopcroftKarp = HopcroftKarp
g_Tree = Tree
g_RerootingDP = RerootingDP
g_LCAEdgeAggregate = LCAEdgeAggregate
g_VirtualTree = VirtualTree
